/* 令和3年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20210421-18","meetingId":"r03-cm04","date":"2021年4月21日","dateIso":"2021-04-21","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ２時２１分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"東京2020オリンピック・パラリンピック聖火リレー","agenda":"東京2020オリンピック・パラリンピック聖火リレー","exchanges":[{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれど、オリンピック聖火リレーについてですが、どなたが走られるかというのは、先ほど未定とおっしゃったのですけれど、未定ですか。それは決まったらいつ発表されるのかとか、何かあれば。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"しかしながら、一般的に公表は、まだされていないです。最終的には、前日に出るというようには聞いておりますので、今のところは私どもも、どなたが走るかとか、どこを走るかということは分かっていない状態です。","voiceIndex":11,"id":"exchange-001"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。この感染拡大というところが一番心配な点でありますので、その点は十分に対応されていくのだろうなと考えていますが、今、７月２１日に、しな助のボランティアを募集されているのでしょうか。もう終わったのでしょうか、募集中でしょうか。その応募状況ですとか、そのようなことをちょっと教えていただきたいのですが、お願いいたします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"一般の方だけではなく、職員も連絡調整役として必要ですので、一定程度は職員も従事するということで、ほぼ予定どおりに協力していただいているかなと考えています。","voiceIndex":14,"id":"exchange-002"},{"speaker":"こんの委員","kind":"質問","question":"セレブレーションについて少し伺いたいと思います。観覧方法です。「会場への入場は事前予約制（予定）」と記載されているわけですが、今のところ予定というところで、どんな方法でその予約、また周知を考えていらっしゃるのか、その点が１点。それから、もう一つが、感染対策のほうです。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"実際に、例えばそこを５０ｍ置きに人が要るとか、その辺りについては、もう少し、日本全国の聖火リレーが進んでいく中で、特に都会ですね、名古屋の辺りなどはすごかったと思うのですけれど、都会の聖火リレーが過ぎたものの検証を踏まえながら。","voiceIndex":18,"id":"exchange-003"},{"speaker":"こんの委員","kind":"質問","question":"セレブレーションのほうは分かりました。そうすると、東京都のほうがすべてそちらをということですから、区としては、東京都が調整した、予約された、その結果を聞き、それに態勢をとる。そこの直接予約の窓口というのは区で、ということなのでしょうか。システムはつくって、区がその予約を受け付ける窓口になる、こういう理解でよろしいですかというのが一つ。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"いずれにしましても、安全にやるということがまず大前提ですので、そこを守れるような態勢というのを、これから７月までいろいろ、他所の状況も見ながら考えていきたいと考えています。","voiceIndex":20,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"交通規制について伺います。詳細が決まり次第、別途お知らせということだったのですけれども、地域の方たちにとっては、いつの時間帯が通れなくなるとか、そういったことなどの情報はとても必要だと思うので、そういった周知についてお知らせいただければと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"交通規制についてのご質問です。交通規制に関しましては、今、委員もおっしゃいましたとおり、非常に生活に直結する部分です。決まり次第、チラシをつくりまして、沿道およびその近隣の地域の方にはポスティングをする予定です。","voiceIndex":24,"id":"exchange-005"},{"speaker":"田中委員","kind":"質問","question":"地域の方たちへの周知、分かりました。ただ、なるべく早めの周知がいいかなということを思います。バスであったり配達の車など、そういった方たちへの周知というのがどのようにされているのかも併せて伺いたいのですけれども。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"例えば、コインパーキングも、全国的な大きなところは東京都が通知をすることになっていますが、個人で経営されているところというのはなかなか網羅できないので、そういったところは区がするというような分担ですとか、あとはバスでも。","voiceIndex":26,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"日本の世論調査、共同通信調査でも、７２％が中止・再延期を求めるというような状況だと思います。ちょっと伺いたいのは、今やるべきことは、一刻も早くやらなくてはいけないなと思いますのは、国に対し、品川区が、一刻も早く、今年夏の五輪開催を断念して、コロナの拡大を抑え込むためにあらゆる力を集中するよう、国に求めることこそ、今行うべきだと思うのですけども、いかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今現在、その開催の可否について私どもが意見するという立場にはございませんので、それをするつもりはございません。","voiceIndex":29,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-008"}]},{"id":"topic-02","title":"集団回収事業の団体支援","agenda":"集団回収事業の団体支援","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"雑がみ回収なのですけど、取り組んでいる団体の全体の何％ぐらいの団体が取り組んでいらっしゃるのか伺いたいと思います。１,０００円の協力金ということですが、この額の根拠についてもお聞かせください。","respondent":"品川品川区清掃事務所長","answer":"雑がみの回収につきましては、大体ですけど６割前後の団体にお金を出しているという状況です。","voiceIndex":36,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"６割というのは、割と取り組んでいらっしゃるなと、個人的には感じたのですけれど、この協力金というのが１,０００円だとやはりちょっと少ないというか、もう少し引き上げることで、さらに雑がみ回収に取り組んでいただける団体は増えるのではないかと思うのです。もう少し引き上げて、そういった取組にできないかなと思うのですけれど、いかがでしょうか。","respondent":"品川品川区清掃事務所長","answer":"そういった意味では、８円に上げているということで、この件に関しましては、品川区は先進的に進めているというものです。","voiceIndex":40,"id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"自民党としてもこの報奨金は前から要望していた部分なので、今度上がったことによって、各団体も非常に喜んでいるというのを聞いています。それからルート対策費なのですが、現状で、これ、７円が差額が出た場合ということですが、現在の段階ではまだそんなに影響はないということでいいのですか。","respondent":"品川品川区清掃事務所長","answer":"これは令和２年度から、やはりコロナ等の関係で、この紙の引取価格がかなり下落をしております。現在のところ、７円を下回っておりまして、その分について昨年度、やはりその分を補う助成等をしています。","voiceIndex":45,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"品川区の業者はかなり頑張っていただいているのですけれど、他区では、業者がもう集団回収をやめてしまったところも聞いていますので、事業を進めていく上でも、金額、今が７円にどのぐらい乗っかっているのかちょっと分からなかったのですが、うまく対応していただきたいなと思います。","respondent":"品川品川区清掃事務所長","answer":"特に大規模マンション等については、非常に効果があると考えておりますので、そういった面も見ながら、集団回収が少しでも向上していくように考えていきたいと考えています。","voiceIndex":47,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"分かりました。それはいいのですけれど、逆に行政回収のところに、今も、要するに回収業者が勝手に持って行ってしまっている。いわゆるアパッチ対策というものは、現状も、多分、見回りをやっていると思うのですけれど、まだまだその業者が出ているということに対して、区としてどう考えているか。そこら辺の今後の対応についてお聞きしたかったのです。","respondent":"品川品川区清掃事務所長","answer":"全体としては、やはり常習犯が大分いらっしゃるみたいで、こういったところも集中的に指導を強めて、今後もやっていきたいと考えています。","voiceIndex":49,"id":"exchange-013"},{"speaker":"こんの委員","kind":"質問・要望","question":"集団回収の、今、お話があったマンションの管理組合の方たちの状況をちょっと参考までにお聞きしたいのですが、区内マンションの件数は正確な数字はちょっと分かりませんが、この区内にあるマンション、大規模、中規模、小規模、いろいろな集合住宅があると思うのですが、どれぐらいのマンションの管理組合の方たちがこの活動をされているかというのは、状況が分かりますでしょうか。","respondent":"品川品川区清掃事務所長","answer":"この周知方法については、例えば、新築のときに一緒に説明をするだとか、それから順次回って呼びかけをしていくだとか、いろいろな方法が考えられるかと思います。どういう方法が効果的かというところも検証しながら、今後その辺も考えていきたいと考えています。","voiceIndex":52,"id":"exchange-014"},{"speaker":"こんの委員","kind":"質問","question":"ちなみに、私のマンションは３５所帯なのですが、やはり活用させていただいておりまして、みんなで出していこうねという機運は結構、うちのマンションなんかはあるほうなのです。ですので、そうしたところもされたらどうかというところです。今後そうしたその集団回収の品目を拡充していくというようなお考えは、どのようでしょうか。お願いします。","respondent":"品川品川区清掃事務所長","answer":"ただ今後、要するに脱プラというところでプラスチック関係の回収、この辺を充実していかなければいけないという流れがありますので、そういったところも集団回収のほうに、より協力をしていただくというような方向性はあるかと思いますので。","voiceIndex":54,"id":"exchange-015"},{"speaker":"こんの委員","kind":"質問・要望","question":"脱プラの関係で、やはりそうしたことを考えていかれると、今伺いました。コロナ禍で、やはり自宅で食事をすることが増えている中で、こうした脱プラの製品、ペットボトルも含めて、かなり多い。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-016"},{"speaker":"つる委員","kind":"質問","question":"集団回収のグループということで、町会・自治会、マンション、ＰＴＡというところなのですけれど、その集団回収の作業をしているときに何らかの事故等、けがとかトラブルとか、そういうことが発生したときの保険のようなものというのは、どういう待遇になっているのでしょうか。","respondent":"品川品川区清掃事務所長","answer":"多分それぞれ町会等の活動の中で保険等に入っている場合があるかと思いますので、これも町会によって、それから集団回収団体によってもいろいろ、別々だとは思いますが、そういうところでの対応という形になるかとは考えております。","voiceIndex":58,"id":"exchange-017"},{"speaker":"つる委員","kind":"確認","question":"要は、一生懸命こうやって区の事業にも協力するような立ち位置での集団回収であると思うのですけれども、そういったときに、先ほど鈴木真澄委員からの話があって、そういえばそういうことがあったなということで、ちょっと改めての確認なのです。そういう積極的な支援と、そうなってしまったときの対応という部分では、どういう対策になっているのかを確認させてください。","respondent":"品川品川区清掃事務所長","answer":"ただ一方で、集団回収のみの団体という考え方もあるかとは思いますが、そういった点については、どういうふうに保険の関係をやっていくかというところは一つ課題にはなると思いますが、他の自治体等での動きなども少し参考にしながら考えていきたいというように思っております。","voiceIndex":60,"id":"exchange-018"},{"speaker":"つる委員","kind":"質問・要望","question":"そういった形でカバーできているのだろうなという理解もありますし、そもそもそういうトラブルがないということが一番いいわけなのですけれども、そういうときに際して、既存のものがあればその一層の連携、そういった形のときにも適用できるということを明確に、清掃事務所のほうでもはっきりと分かるような形で確認等をしておいていただきたいなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-019"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひそれは区として、ブラインドサッカーを盛り上げていくという意味で、強めていただきたいのですが、いかがでしょうか。どういったことを考えていらっしゃるのか、伺いたいと思います。そこら辺をちょっと伺いたいと思います。これらの、こういう共催プログラムという予算についても、東京２０２０大会の開催総予算に含まれるという考え方でよろしいのか、伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ブラインドサッカーの中継等の周知のことですが、これから広報しながわに１面を使いまして周知をします。それから私どものＳＮＳやホームページ等でも周知の予定です。","voiceIndex":67,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"一度実施しているキャナルアートモーメントですけれど、２回目をやるということになるのですけど、１回目の開催を踏まえて、２回目というのは何かこう変化というか、工夫というのでしょうか、そこら辺はどういう考えなのか、伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"大会自体は延期になってしまいましたが、これ自体は世界に発信できるものだということで、去年、実施をいたしました。","voiceIndex":69,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。では今回はオンラインだけではなくて、そういうことも実施するということですね。ちょっと先ほど質問したのですけれど、仮に大会が中止になってしまった場合、これらのプログラムというのは、去年の場合は別に、それはそれで文化だということで実施されて、今回の場合はどうなのでしょうかという質問をしたので、そこだけ聞かせてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"中止になった場合の取り扱いですが、今時点での決定ということはございませんが、大会の有無に関わらず、こちらの世界に発信できるものということでは、やっていきたいなと考えております。","voiceIndex":71,"id":"exchange-022"},{"speaker":"田中委員","kind":"意見","question":"ブラインドサッカーについてなのですけれども、先ほどその周知については、広報しながわとＳＮＳ、ホームページということだったのですが、サッカーをしている子どもたちにもブラインドサッカーに関心を持っている子たちもいるので、そういった子どもたちへの周知をどのように考えているのかといった点と、あと、区民観戦は実施をするとのことだったのですけれど。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ブラインドサッカーに関して２点ご質問いただきました。子どもへの周知ということなのですが、実は区が音頭を取っているのではなくて、実はブラインドサッカーの応援連絡会というのが立ち上がっております。","voiceIndex":74,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"この移転の経緯について教えていただきたいのです。チームのほうと品川区、あと会社もありますけれども、どちらがどんな目的でどんな話し合いを、いつ、何回ぐらい重ねて移転が合意決定されたのでしょうか。ちょっと伺いたいと思います。","respondent":"中元スポーツ推進課長","answer":"区内企業の社長の方たちでつくっている団体で、協議会としてはプロチームの誘致やスポーツでの品川区を盛り上げる活動を行っていくという団体が立ち上がりまして、そちらの団体からも、ぜひ支援・協力をお願いしたいというご要望をいただき、それに対して。","voiceIndex":79,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"なるほど。そういって、協力しましょうということでお返事した品川区として、このプロスポーツチーム区内移転のこの２チームのメリットについて区はどういうふうに考えて承諾したのでしょうか、伺いたいと思います。","respondent":"石田（ち）委員長、中元スポーツ推進課長","answer":"区民委員会でも報告をされている内容ですけれども、私としては、この場でお答えいただける内容ですので、お答えいただけたらと思います。ホームゲームですが、現在、総合体育館の主競技場は大変利用頻度が高いので、実際にはなかなか難しいかなと考えております。その合間でリーグ側との調整・協議がつく範囲で、少しでも。","voiceIndex":81,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"その際どうするのかということを伺いたいのですが、昇格後の環境整備のことを考えないで承認するということは、やはり普通に考えてあり得ないと思うので、近い将来、アリーナの建設を当然視野に入れた今回の承諾なのではないかなと考えてしまうのです。ここは、アリーナの問題も所管している委員会なので伺います。それとも出さなかったのでしょうか。ちょっとそこだけ確認させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-026"}]},{"id":"topic-04","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"「令和２年７月２日時点のものですが」という文言がこの文書の中にはあるのですけれども、やはりちょっと前回の委員会でも指摘したとおり、今のこの感染症が広がっている状況があるので、文言については気をつけていただきたいなということを思っております。いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-027"},{"speaker":"渡部副委員長","kind":"質問","question":"しようがないというよりも、そういう議論があったわけですから、そこを変えることはできないのかなというふうに考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"本文にも書いてあるとおり、去年７月２日時点での議論のまとめということなので、正副委員長案には賛成なのですけれど、ご承知のように、その後状況が大きく変わってきていますので、共産党としては、やはり今年夏のオリンピック・パラリンピック開催は中止をすべきだという立場には変わりありません。これは意見だけ述べさせていただきたいということです。すみません、以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-029"},{"speaker":"田中委員","kind":"確認","question":"すみません、ちょっと確認なのですけれども、もし修正をする場合には、４月２８日に文書で出してくださいといったことだったのですが、７月時点で話し合ったことを書いているといったことは重々よく分かっているのですけれども、でもやはり、この状況の中で区民が見たときにどう思うのか、この議論を見たときにどのように思うのかといったところをやはり考えてしまうので。","respondent":"石田（ち）委員長","answer":"そうですね、ご意見や修正案はご提出いただいて構わないです。そして、その上で正副委員長でまた検討するということになりますので。","voiceIndex":94,"id":"exchange-030"},{"speaker":"こんの委員","kind":"確認","question":"体裁というところでちょっと確認なのですが、これ、やはり項目別に、１枚、１枚、この記の上のこの文章は、こういう形でということだったのでしたか。要するに、冒頭の４行と、その下の４行は、どれもついていて、その真ん中がいわゆる項目に沿った、こういうように調査を進めてきて、記書きがあると。これ、何というのでしょうか、その冒頭とその下の部分というのは、どこにもついている文章なので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-031"},{"speaker":"こんの委員","kind":"質問","question":"体裁的にはまとめたほうがいいのかなと。これは１枚、１枚のほうがいいのですか。ちょっと気になりました。そこら辺のところはどうなのでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-032"},{"speaker":"こんの委員","kind":"意見","question":"今までのがこういう項目別にそれぞれしてきたというところで。なるほど、分かりました。ちょっとそれが気になったので、どうなのだろうと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-033"},{"speaker":"こんの委員","kind":"質問","question":"もう一つは、機運醸成に関することのまとめに書いてある、先ほども話が出ましたけれども、「７月２日時点のものですが」という日付が入っていますが、それ以外の各調査事項の調査の日付はどうなのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-034"},{"speaker":"渡部副委員長","kind":"意見","question":"すみません、ちょっと考えます。田中委員が先ほど言ったものも含めて、今回はその辺の前置きをちょっとつけたほうがいいのかなというふうにも思ってきたので、また、それは統一したような感じで次の委員会に出するということでご了承いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":103,"id":"exchange-035"},{"speaker":"田中委員","kind":"質問","question":"ここで発言しなくても修正案を出すのは可能ですよね。ここで発言しなかったから駄目だとか、そんなことはないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-036"},{"speaker":"田中委員","kind":"意見","question":"よかったです。やはりここでも、「積極的に」などはちょっと気になったなということを思っていて、ではそういう修正案を出していきたいと思います。今の「さっき言ったじゃないか」とかいうものは、議事録に残りますか。そういった発言は副委員長としていかがなものかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":108,"id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6592#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":25751,"voices":113}},{"id":"r03-20210428-10","meetingId":"r03-cm04","date":"2021年4月28日","dateIso":"2021-04-28","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5408#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":6581,"voices":39}},{"id":"r03-20210514-10","meetingId":"r03-cm05","date":"2021年5月14日","dateIso":"2021-05-14","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"東京都後期高齢者医療広域連合議会議員の選挙における候補者の推薦","agenda":"東京都後期高齢者医療広域連合議会議員の選挙における候補者の推薦","exchanges":[{"speaker":"本多委員","kind":"意見","question":"この選挙にあたりまして、品川区議会からの選出方法なのですが、議長経験者の中から品川区議会を代表する候補者を出すべきだと思います。今までの慣例もそうでしたけれども、やはり品川区議会を代表してのということで、選出方法については議長経験者でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"議長経験者からというご意見もありますが、私はやはり立候補したい人が、自らまたは会派から推薦をして、やりたい人が出るというのがよろしいかと思います。しかも東京都後期高齢者医療広域連合議会での意見や態度については異なる部分もあるだけに、しっかりと立候補をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"今言ったほうがいいですか。共産党からは、石田ちひろ議員が立候補したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-003"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"確認","question":"例えば、この委員会室では委員長のところに、１か所、たけうち副議長のところで２か所、仕切板で音が防がれてしまっているから、聞こえやすいように何か工夫をしていただけないかと。私だけが耳が遠くなったのか、そう言われるとそれまでなのですけれども、一応、藤原議員にも確認をしたら、聞こえにくいと。その辺、もし工夫できるようでしたらご対応をお願いしたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5410#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":7861,"voices":40}},{"id":"r03-20210517-6","meetingId":"r03-cm05","date":"2021年5月17日","dateIso":"2021-05-17","committee":"区民委員会","time":"午後 １時００分～午後 １時５５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の順番を入れ替えて、２、その他","agenda":"の順番を入れ替えて、２、その他","exchanges":[{"speaker":"藤原委員","kind":"確認","question":"１つだけ確認させていただければありがたいのですが、たしか前々回ぐらいの委員会の報告で、戸籍住民課でＬＩＮＥを使う事業が報告されたと思うのですけれども、その後にマスコミ等でＬＩＮＥの課題のようなものが出たので、行政としてその辺はどう考えているのか、報告事項に出てきた案件なので、聞ければ幸いなのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":3,"id":"exchange-001"}]},{"id":"topic-02","title":"令和２年度町会・自治会活動活性化促進調査の中間報告書","agenda":"令和２年度町会・自治会活動活性化促進調査の中間報告書","exchanges":[{"speaker":"くにば委員","kind":"質問・要望","question":"もちろん町会・自治会のほうでは、町会・自治会が抱えている様々な課題は、ほかのところも課題になっているのだということを、おおむね肌感で分かっていらっしゃる部分はあると思うので、それらを見て、どういった部分を変える、どういった部分を参考にする、ほかのところではこのような工夫をしていると、この報告書を基にどのようにしたらいいか、そこをぜひともそれぞれに伝えていただきたい。","respondent":"川島地域活動課長","answer":"アンケートの回収率の件です。こちら、９ページに出てくる表を見ていただけますと、そうしたデータが出ておりまして、八潮地区の回答率が４６.４％になってあります。","voiceIndex":16,"id":"exchange-002"},{"speaker":"くにば委員","kind":"質問","question":"今、八潮の回答率４６.４％の部分について触れていただいたのですけれども、例えばこれ、回答がなかった１５の自治会ですか、こちらに関して回答率が著しく低かったのは、品川区の行政とのつながりが薄く、あまり接点がないので向こうから回答がなかったのか、それとも何かしら理由があって回答がなかったのかという部分、例えばそれがもう一つの傾向なのですが。","respondent":"川島地域活動課長","answer":"今回のアンケートは非常に項目が多く、回答も負担になったのかなと私どものほうでは分析しています。","voiceIndex":18,"id":"exchange-003"},{"speaker":"くにば委員","kind":"質問・要望","question":"そこに関して、アンケートは回答が得られなかったですけれども、先方のお時間があるとき、また何度もご連絡をしてみて、アンケートという形ではなく、ぜひともヒアリングだけでも実施していただきたいです。これは要望です。同様に、これ以外にも出てくるのですけれども、八潮では高齢者に対するサポート、アプローチという部分に非常に力を入れてやっていらっしゃると思います。","respondent":"川島地域活動課長","answer":"こういった事業も町会は力を入れてやっていただいているところですが、アンケートにはほかのものが多分重要だったのかなというところで、プライオリティーの中で、このようになってきたのかなと考えているところです。","voiceIndex":20,"id":"exchange-004"},{"speaker":"くにば委員","kind":"質問","question":"今、ご答弁を聞いていて思ったのですけれども、これ「子育て支援に関する活動」、具体的にアンケートをお聞きするときに、地域の親睦を図るためのイベント、これはもちろんお子さんや子育て世代の方々も含めた地域のイベント、これが「地域の親睦を図るためのイベント」、あとは「青少年育成に関する活動」「子育て支援に関する活動」、それぞれどこに入ってくるのか。","respondent":"川島地域活動課長","answer":"特に区の事業との関連づけでということではなくて、こちらに書いてあるような項目についての活動ということですので、きっちりした正確な数値が出てくるということではないのですけれども、大まかな活動の内容については傾向というか。","voiceIndex":22,"id":"exchange-005"},{"speaker":"くにば委員","kind":"質問","question":"もちろんそれぞれの地域で、この活動を今年はしていない、令和元年度に関してはしなかった、そういった時期的なものもあるとは思うのですけれども、それぞれこの具体的な活動実績についての分析は何か伺えますでしょうか。","respondent":"川島地域活動課長","answer":"なかなか各町会ごとの分析、何ができていて、何ができていないというよう活動診断のような形での分析はしていないところです。","voiceIndex":24,"id":"exchange-006"},{"speaker":"くにば委員","kind":"意見","question":"最後に、今現在、町会・自治会に関するヒアリング調査で、既に行われたのが女性会長であるとか、マンションに関してのヒアリング結果だと思うのですけれども、これから行っていくヒアリングが残り幾つかあったと思うのですが、それらの進捗状況だけ最後にお聞かせください。","respondent":"川島地域活動課長","answer":"残りのヒアリングを３つぐらいのカテゴリーでやりたいということで、次が５月中に、様々なイベント等を活発に行っているような町会ということでお声がけをして、準備しています。そのほかの２つのカテゴリーは、これから検討していくところになっております。","voiceIndex":26,"id":"exchange-007"}]},{"id":"topic-03","title":"期限切れマイナンバーカードの紛失事故","agenda":"期限切れマイナンバーカードの紛失事故","exchanges":[{"speaker":"くにば委員","kind":"確認","question":"隣接する別会場でカードの失効処理を行った、その後の保管状況がはっきりしていない、なぜここの文章だけではなく、今回紛失になってしまった原因、例えば職員がこういった業務の流れの中で、ここの部分でもしかしたら紛失をしたかもしれないという、そういったフローであるとか、あとはその担当の方がどのような部分を必ず確認をしてやるべきだったのに。","respondent":"木村戸籍住民課長","answer":"今、警察のほうとも連携をいたしまして、何かご本人に心当たりのないような問合せが来たり、どこかでそのようなことがあれば、すぐ１１０番をしていただく、あるいは私どものほうにご連絡いただくというような形で、被害者の方とはご連絡を取ってあります。","voiceIndex":33,"id":"exchange-008"},{"speaker":"くにば委員","kind":"質問・要望","question":"最後に１点、複数の職員で確認の上、その場で即時破砕するという部分、これはほかの自治体で同じ期限切れマイナンバーカードに関してどのようなオペレーションで行っているかというので、ほかの自治体の事例というか、現在行っている流れというものを何か確認した上で参考にしたのでしょうか。","respondent":"木村戸籍住民課長","answer":"今回このことに関しては、他の自治体の動向などというよりも、まずそれが最善であろうというところで、私どものほうで進めたものです。その後も他自治体の状況については確認はしておらないところであります。","voiceIndex":35,"id":"exchange-009"},{"speaker":"くにば委員","kind":"意見","question":"そこを参考にすることによって、今回のような穴をふさぐだけではなく、もっといい業務のルーチンがあるかもしれないかなと思うので、そこに関しては他自治体などがどういった形でこれを行っているのか、今回勉強するという形で、他自治体でどのようにして流れをやっているかということは聞いてみたらいいのかなと思います。最後は所感です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-010"},{"speaker":"藤原委員","kind":"確認","question":"確認なのですけれども、警察署から保護者の方に、このようにカードが落ちていましたよという電話があったのですよね。ということは、警察署ではどこで拾ったのかということは分かっているわけですよね。その辺についてはいかがですか。","respondent":"木村戸籍住民課長","answer":"ご指摘のとおりで、なかなか言えるところ、言えないところはありますけれども、ただこの警察署につきましては、埼玉県の警察署に届けられたです。","voiceIndex":38,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"そうしたら、現実問題そのカードがそこまで行ったわけですよね。そして、そのような品川区の庁舎内ではないところに捨てられていたということは、やはりこれからの課題というか、今後の対応で出ていますけれども、このようなことが現実に起きてしまうのだということは、担当の課として、また全体として、きちんと押さえていていただきたいと思うのですけれども、いかがでしょうか。","respondent":"木村戸籍住民課長","answer":"おっしゃいますように、本当に個人情報の最たるもので、私どもも普及を進めているところ、そのような立場の者がこのような事故を起こしてしまったということは、大変あってはならないことだと思いますので、今後これを契機にというわけではないのですけれども。","voiceIndex":40,"id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"これは、先ほど課長もあってはならないことということで、でも起こってしまったというところで、なくしたということを職員がもう認識していて、それで探して探して、そうしたら警察署から連絡があったということなのか、警察署から連絡が来たことでなくしたということが分かったということでいいのでしょうか。","respondent":"木村戸籍住民課長","answer":"まさに後者でございまして、警察のほうから連絡があって分かったということです。","voiceIndex":43,"id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なので、そのようなところでは本当になくしたかどうかも分からない、先ほど話もありましたけれども、それで、起こった原因も先ほどくにば委員のほうのお話でありましたが、それに対して再発防止の対応がされるということなのですけれども、この特設会場が現在何人体制で、なくしたときに混雑していたという、混雑というのはどのぐらいの方がいらっしゃるのか、分かれば教えていただきたいのと。","respondent":"木村戸籍住民課長","answer":"３点ご質問がございました。スタッフの体制なのですけれども、時間帯ごとで柔軟に対応しているところもあるのですが、約１５から２０名程度配置をして、この４月からそのような形で強化をしてそのぐらいということです。","voiceIndex":45,"id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そのような会計年度任用職員という在り方がどうなのかと私は感じます。ですので、私は改めてこういったさらなる交付というところでは検討していただきたいと思いますし、職員へのさらなる負担、あと雇用の仕方というところは、ちょっと改めてご検討いただきたいなと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-015"},{"speaker":"小芝委員","kind":"質問・要望","question":"このマイナンバーカードの交付というのは、決まった流れがあるかもしれませんけれども、その一方で当然に区民の、国民の情報を扱う大変重要な仕事だと思いますので、その辺しっかりとそれ相応の職員の方を充てて対応していただきたいということを意見して終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-016"},{"speaker":"つる副委員長","kind":"質問・要望","question":"ちょっと確認で、先ほど藤原委員のほうからもあったのですけれども、カードがそのような形で紛失した原因とか、各委員からあったとおり、そのようなことがなくやっていくということが大切なことで、それを求められているという緊張感というものは、すごくあって、だけれどもそれが当たり前だという中で起こってしまったという、その事実はしっかりと受け止められて。","respondent":"木村戸籍住民課長","answer":"本当に核心のところが、なかなか裏づけあってこうですというところでご説明できないのがちょっと苦しいところなのですけれども、今のところはそのような形で、職員が何らかの形で着衣の中に入れてどこかに落としたというようなところぐらいしか分からないです。","voiceIndex":51,"id":"exchange-017"},{"speaker":"つる副委員長","kind":"質問・要望","question":"個人的に何かがあってそのような行為に至ったのかどうか、それは分からないけれども、やはり本人からしてみればなぜ私のものだけがそのような形で一職員の方の身に呈されてしまったのかということは、これは非常に気味が悪いことかと思います。そのような意味では、犯人探しとか、そのようなことではなくて、やはり改善をしていかなければいけないわけですから、そのような部分でのことをどこまでやるのかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2896#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":17154,"voices":55}},{"id":"r03-20210517-7","meetingId":"r03-cm05","date":"2021年5月17日","dateIso":"2021-05-17","committee":"厚生委員会","time":"午後 １時００分～午後 ２時４８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区立大崎高齢者多世代交流支援施設（大崎ゆうゆうプラザ）","agenda":"品川区立大崎高齢者多世代交流支援施設（大崎ゆうゆうプラザ）","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"説明いただいたのですけれども、今になって委託から指定管理に変える理由がいま一つ飲み込めないのですが、なぜ初めから指定管理にされなかったのか、もう少し具体的にご説明願いたいと思うのです。今、委託でやっていて、何か課題が出てきて、それで指定管理に変えられるのでしょうか。あるいは事業の中身に変更があるのか。あるいは委託料と指定管理料で違いが出てくるのか。","respondent":"菅野高齢者地域支援課長","answer":"そのときが、ゆうゆうプラザでの初めての施設運営ということで、委託か指定管理か、どちらか適切な運営方法を検討するために、そのように規模に応じて委託、指定管理というふうに分けた次第です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、大規模あるいは複合云々に関わらず、要するに指定管理のほうが管理上効率がよくなるということなのですか。","respondent":"菅野高齢者地域支援課長","answer":"私、先ほど最大のメリットとして管理上の効率性のことをお話しさせていただきましたが、それだけではなく、今後、高齢化が進む中、積極的な事業展開が期待できるということで、他のゆうゆうプラザと運営形態を統一化したいと考えた次第です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"様々提案をしていただくというのが指定管理の特徴でもありますので、いろいろ特徴も出てくるのかなという思いもあるのですけれども、基本的に区が求める業務内容の変更は業務委託から指定管理になることで変わることはないのか。職員体制なども基本的に何人で行うとか、そういうことについての変更があるのかないのか、その点についてもお聞かせいただきたいと思います。お願いします。","respondent":"菅野高齢者地域支援課長","answer":"今回、この大崎ゆうゆうプラザ、７００m2ということで、規模としてどちらにするかということで、メリット・デメリット、いろいろ考えた結果、今回につきましては指定管理に移行することが適切であると判断させていただいた次第です。","voiceIndex":10,"id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ということは、区の支出は委託料と区が持っていた分の合計という形で、基本的に区の支出が変わるということではなく、同じ経費で運営ができると考えていいのでしょうかということを確認させていただきたいと思います。その点についてもお聞かせいただきたいと思います。それから、平塚ゆうゆうプラザのときは、公募しても福栄会１事業者だけの応募だったという経過がありますよね。","respondent":"菅野高齢者地域支援課長","answer":"平塚ゆうゆうプラザのときの募集についてですけれども、今回の予定としましては、６月に入りましたら公募を開始させていただいて、その後、先ほども説明させていただきましたが、６月下旬に説明会をして、その後、応募期限という形なので、３週間程度、間を空けて。","voiceIndex":12,"id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これまで大崎ゆうゆうプラザで介護保険の総合事業として地域ミニデイを行ってきたと思うのですけれども、多分ここが初めて行った地域ミニデイではないかなと思うのですが、利用の実態ですとか週何回ぐらい実施されているのか、また、この地域ミニデイはたしか社協職員の運動指導員の方と、それから地域のボランティアの方で運営するという中身になっていたかと思うのですけれども。","respondent":"菅野高齢者地域支援課長","answer":"こちらは、委員ご指摘のとおり、社会福祉協議会の職員の方で運動指導員の方がいらっしゃいまして、今、各法人のほうで、ゆうゆうプラザで地域ミニデイをやっているのですが、その先駆けといった形になっております。現在は毎週金曜日に週１回、教室が行われております。","voiceIndex":14,"id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"ということは、これから引き継がれるところに対しても、総合事業の地域ミニデイはゆうゆうプラザの事業として行ってくださいということで業務の中に入っていると考えていいのか、その確認だけお願いします。","respondent":"菅野高齢者地域支援課長","answer":"こちらの地域ミニデイ事業は、団体や事業者が行ったその事業に対しての補助金制度になっておりますので、新しい事業者に私としてはできればやっていただきたいということはやまやまなのですけれども、まずはやっていただいた上での補助金という形になりますので。","voiceIndex":16,"id":"exchange-006"}]},{"id":"topic-02","title":"食品衛生法の改正に関する事業者への周知","agenda":"食品衛生法の改正に関する事業者への周知","exchanges":[{"speaker":"渡部委員","kind":"確認","question":"猶予期間もありますから、何かそういうお気づきのところに網を張っておいて、地域からもお声をお寄せいただいたりとかで、漏れのないように進めていただければと思いますので、確認だけさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-007"}]},{"id":"topic-03","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"今、変異株が非常に話題というか大変なことになっているとよく聞くのですけれども、品川区内での変異株の状況の調査とか把握というのはどういうふうになっているのでしょうか。お伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"ただ、都の直接の衛生検査所については、全例ではなく、およそ４割の検査をしていると聞いておりますけれども、そのうち民間から検査されたものについては、直接国の国立感染症研究所にその報告が行きまして、そこから東京都に戻って。","voiceIndex":29,"id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今の変異株のことですけれども、何人かというところですが、品川区の陽性の方の中でどれくらいの方が、変異株の検査をされているうちのどれぐらいかというのは分かるのでしょうか。それと、裏のページの（５）のところに、クラスターが発生した施設へも出張で検査を実施していると書かれていますけれども、この間、この１か月ぐらいだと思うのですが、どんなところでどれぐらいクラスターが発生しているのか。","respondent":"鷹箸保健予防課長","answer":"それからそこのクラスをしばらくお休みにするとか、そういった対応も必要な場合に実施しておりますが、幸い学校で５人以上のいわゆるクラスターが発生しているという事実は、４月以降はございません。","voiceIndex":32,"id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうしますと、クラスターは４月以降は４施設で全て企業だということですけれども、では、学校が休校したというプレス発表は、クラスターまではいかない人数、４人とかそういうことで休校したということだったのでしょうか。","respondent":"鷹箸保健予防課長","answer":"ただ、特に高齢者施設等での感染拡大を防ぐという意味で、濃厚接触者という定義に当てはまらずとも、お一人でも陽性者が出た場合には、その施設で例えばそのフロアの全従業員・全入所者を検査するとか、検査については幅広く実施していくことになります。","voiceIndex":34,"id":"exchange-010"}]},{"id":"topic-04","title":"品川区の新型コロナウイルス感染症にかかるワクチン接種準備状況","agenda":"品川区の新型コロナウイルス感染症にかかるワクチン接種準備状況","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"私たちも１４日に出すのだなんて思っていて、びっくりしたところで、確かにテレビとかで大手町の話はされていたので、それに間に合わせるように出さなければいけないのだなというのがあって、確認を取らせていただきました。そこでやはり気になるのが、１４日で、６５歳以上の方は今もうお手元に届いている状況で、予約開始が１か月後ですよね。７５歳以上の方と６５歳以上の方の封入物は基本的に一緒ですか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"予約枠についてですが、予約開始日当日については、コールセンターで受けるものは、ネットでやると入りませんので、委員がおっしゃるそのとおりですので、別の方法を使って、電話枠とネット枠をあらかじめある程度分けておいて、それで対応するということで。","voiceIndex":40,"id":"exchange-011"},{"speaker":"渡部委員","kind":"確認","question":"最後のところだけがとにかく大事で、それだけ確認しなければと思っていたのです。だから、そういうところへのアナウンスをどういうふうに考えているのか。これから様々広がっていく中で、そういうアナウンスに関してはどういうふうに考えているのか。ワクチンは安定的に入ってくるという話で、私も院長先生にお話を伺ったりする中で、多分この量があれば６５歳以上の方までいってしまうわけです。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"基礎疾患等々の考え方についてですが、もちろん引き続き検討はしていますが、細部に詰めて行うところまでは現在いっておりませんで、まずは７５歳以上の高齢者の１９日をしっかり迎えることと、それから次の６月１４日を迎えることと。","voiceIndex":42,"id":"exchange-012"},{"speaker":"渡部委員","kind":"質問","question":"ワクチンの情報ではないけれども、こうなりましたというのは、課長に説明していただいたようなやり方で十分だとは思うのですが、できれば、月２回の回覧板があるではないですか。１０日と２５日でしたか。５日と２０日でしたか。電話で、いつがご希望ですか、いついつだとどこしかできませんよ、私はどこが近いのにねと、１人１０分や１５分では終わらない話になるわけですよ、電話の予約が。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-013"},{"speaker":"あくつ委員","kind":"確認","question":"２枚貼ってありました。ただ、町会の掲示板には貼っていないのですね。貼ることにしました。それで意見があればお伺いします。その辺についてもう１回確認、さっき、今詰めているところだというお話があったのですけれども、このままだと結局優先接種も普通の方も一緒の状況で予約をするというふうに見えてしまうので、そこについてどういうふうにされるのかというのをまとめてお伺いしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"基礎疾患等、高齢者の次の優先順位の方の期間ですが、これは現在検討しておりまして、決定しているものではございませんが、一応優先期間と申しますか、一般の方の予約開始日よりも先に、何日間か、もしくは何週間か、基礎疾患とか、優先的な方が受けられる期間を。","voiceIndex":46,"id":"exchange-014"},{"speaker":"おくの委員","kind":"質問・要望","question":"そうすると、どうやったらいいのかというご質問なのです。例えば港区や世田谷区にそういう書類を求める場合にはどういう手続きを取ったらいいのか、どういう書類を出したらいいのかということが非常に具体的に書いてあって、特に世田谷区は非常に分かりやすかったのです。地図を見てみますと荏原地域がすこーんとない感じがするのですが、そこら辺のことをお伺いしたいと思います。いかがでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ネットができない方の電話ですが、５月１９日に、７５歳以上の方、約４万６,０００人おりますけれども、その段階で４万６,０００以上の枠を用意して１９日を迎える予定ですので、希望の日時ということにはもしかしたらいかないかもしれませんが。","voiceIndex":50,"id":"exchange-015"},{"speaker":"渡辺委員","kind":"質問・要望","question":"私は大きく２点。それぞれ今までの質問とかぶります。最初、接種券郵送の段階の話。これは質疑ではなく、よく間に合わせられたなということで、評価というとおこがましいのですが、実は今日の朝あたりも情報番組で、届いていない自治体、２３区が結構取り上げられていました。逆にいうと、品川区は先週の段階ですか、相当な苦労があって前倒し郵送をある意味達成したと。最初にお願いします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ただ、Ｗｅｂに関しては、昼を過ぎればそんなにストレスもなくつながるようになっていたという情報も入っておりますので、恐らく電話は、先ほどの話ではありませんが、つながりさえすれば翌日でも枠はもちろん空いていますし、当然Ｗｅｂも枠は空いていますので。","voiceIndex":52,"id":"exchange-016"},{"speaker":"渡辺委員","kind":"質問","question":"先ほどの繰り返しですが、接種券の発送業務、これは本当にすばらしい功績だと私は思っています。そこで、ではこの日ならどうぞ、この日ならどうぞと、やっとつながった貴重な通話を結論に導く、この日だったら空いているというのを本当に達成するような、そんなことをぜひ一押し、二押し、行政が責任ある課として、局として、部として押してもらえないかなというのがあれなのですが、いかがでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"委員ご指摘の今のお話、コールセンターとすぐに連絡を取りまして、対応させていただきたいと考えています。","voiceIndex":54,"id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"本当にお疲れさまです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"増やした。５０台。すみません、５０台になったということなのですね。ほかのところでは歯科医師にも協力をお願いするという自治体もあるとニュースで流れていますけれども、品川区は歯科医師の協力についてはお願いしないで、医師会との協力でできるという状況なのか、その点について教えていただきたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"計画についてです。７月末でできるか否かということですが、７月末でということで回答はしています。ただ、そこについては今試算等々をしておりまして、それに基づいて回答したものです。","voiceIndex":58,"id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"かかりつけの医療機関でできるようになると一番いいのだけれどもという声を地域からたくさんお聞きしていまして、先ほどの報告でも、６月をめどに個別接種会場、診療所等を追加検討するという報告がありましたけれども、品川区内にクリニックとかは２００近くあるのですかね、かなりあると思うのですが、うちは協力するよというところが接種会場になっていくのかと思うのですけれども。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"移動支援につきましても、区として検討の俎上には上がりましたが、ほかの方法等々を使いまして、例えばもう少し違った形で移動支援ができるのではないかということで検討していることもありますので、タクシー券を配布するような支援については現在考えておりません。","voiceIndex":60,"id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"スクエア荏原が今度できるということなので、若干よくなったかと思うのですけれども、中原街道の向こう側は本当に今までなかった、これも６月中旬からということなので、ちょっと遅れるということもありますし、そういうところでは移動の支援というのはやはり欠かせないので、高齢者は駅から歩いていくのも本当に大変ですし、移動の支援は本当に必要ではないかと思うので。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"旗の台方面ですけれども、スクエア荏原のほかに、個別接種、診療所については荏原地区をまずは中心に話を先に進めておりますので、その辺りで、６月のしかるべき時期が来たら病院。施設についてですが、福祉部とも調整を進めさせていただいておりまして、上がっている施設については何とか打ちにいける方向で、こちらも引き続き調整を進めているところです。","voiceIndex":62,"id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"分かりました。往診の先生に聞いても、自分はやらないよと言われてしまったのだけどと。では、どうすればいいのと。寝たきりで連れていくのもすごく大変だし、ストレッチャーで介護タクシーを使って会場まで連れていくしかないのではないかと言われたというのですけれども、往診の先生に依頼したり、また、巡回接種とかの体制も必要なのではないかなと考えるのですが、その点についてはいかがでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ご協力いただける先生もいらっしゃるということは聞いております。ただ、もちろん行ける方と行けない方がおりますので、その辺りどういうふうにしていくかということの検討を現在進めている段階です。","voiceIndex":65,"id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"在宅の方ですけれども、検討を進めているというものの検討の中身なのですが、検討の中身というのは、在宅の高齢者の方に対して巡回接種みたいな形でやってもいいよという先生がいらしたら、そういう形で巡回接種を何とかできないかということで検討されているのか、そのときに、様子を見るというのは在宅でどういうふうにしたらできるのかという思いもしているのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そうか、寝たきりの患者なのでハイリスクということで、３０分、看護師が付き添って様子を見るという体制を取るのか、そういうことも含めての巡回接種ということで、区としてできないかということで検討しているのか。検討の中身について教えていただきたい。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ただ、委員ご指摘のとおり、そこで待機の時間等々も発生しますので、どのようにすればいいかということはまだ今答えが出ていない状態です。現在検討というか協議を進めている最中です。","voiceIndex":69,"id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこのところは医師会の先生とだけ協議をしている感じなのですか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、秋山保健整備担当部長、鈴木（博）委員長","answer":"基本的にはかかりつけ医がおりますので、その方が打ちにいくのが一番いいということは皆さん分かってはいるのですが。介護サービス……。すみません、ちょっと飛んでしまいました。申し訳ないです。介護につきましては、在宅介護支援センター等の協力が得られるように今話を進めておりますので、介護サービスの利用者の方はそちらから情報ないしは。まだ始まるばかりで、決まらないことが多くあるところなので、答えられるところだけ答えていただければ結構です。","voiceIndex":71,"id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それからもう１つ、最後ですけれども、高齢者が終わった後のスケジュール、先ほどからも出ているのですが、基礎疾患がある方の接種、それとともに介護従事者とか高齢者施設の従事者のリスクも高いと思うのですけれども、あと保育園とか学校職員とかなんかも含めての優先接種についてはどういうふうに考えられているのかについてお聞かせいただきたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ただし、高齢者施設の従事者については、今、施設を回っているときに、余った分のワクチン等々で先に打つことは認められておりますので、その辺りについては接種を進めているです。","voiceIndex":76,"id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"本当に初めて全区民、若い方はあれですけれども、多くの区民の皆さんにワクチンをこれだけ急いで打つという体制で、本当にご苦労されていると思うのですが、様々な課題もたくさんあると思うのですけれども、様々なところと連携をしながら、スムーズにいくように取組んでいただきたいと思います。どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-027"},{"speaker":"西村委員","kind":"質問","question":"既に始まっている自治体が幾つかあるので、いろいろとウォッチしていただきながら進めていただいていると思うのですが、１つ、幾つかの自治体が会場の空き状況を見える化するということに取組んでおりまして、把握にどれだけのマンパワーがかかってしまうのか想定できないのですが、もし可能であれば、予約枠数ですとか、こういうふうに会場によってやっている曜日がばらばらなので。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"見やすくなる一覧表みたいなもの、現在検討を進めておりますので、うまくいくように進めてまいりたいと考えております。","voiceIndex":80,"id":"exchange-028"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほどちょっと遠いということがあったのですが、車を利用される方が多いと思って、ご家族が近くまで行ったり、あるいは周辺でとかということなので、その辺に車が並んだりみたいな、そういった混乱も生じるのではないかと思って、あるいはコールセンターに車で行っても大丈夫ですかとか駐車場はありますかとか、そういう話も出てくると思うのですけれども。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"先日、大井競馬場とも調整させていただきまして、かなり大きな駐車場もお借りすることができたので、入れることはできるのですが、ただ、やはり４番スタンドまで確かに距離がありますので。","voiceIndex":83,"id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ホームページについては、本当にお忙しい中ですけれども、十分にチェックをお願いします。特別に何かが来たのではなくて。ほかのところは、周辺の混雑……、車の中で待っていて、打つ車でとかといって駐車の問題とかが起きそうな気がするので、そこはどうなのでしょうか、どなたかが外にいるのかとか、そういったところは気をつけたほうがいいのではないかと。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"私も６５歳を過ぎていまして、接種券が届いたのですけれども、手続きのところで、１回目を打ったときに、その後、２回目は電話またはＷｅｂで予約をするとなっていたのですが、でも、高齢者のところでは、たしか１回目の接種のときに接種会場で２回目の予約をして帰るということだったのではないかなと思ったのですけれども。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今ご指摘の点についてですが、同封するときからいろいろと状況が変わりまして、結論、会場で２回目の予約についてはお取りするというか、取った状態でご案内をする方向に変更いたします。","voiceIndex":87,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3594#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":35093,"voices":91}},{"id":"r03-20210517-8","meetingId":"r03-cm05","date":"2021年5月17日","dateIso":"2021-05-17","committee":"建設委員会","time":"午後 １時００分～午後 ４時２１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を81件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和３年陳情第１４号、コミュニティバスの運行に関する陳情","agenda":"令和３年陳情第１４号、コミュニティバスの運行に関する陳情","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"やっぱり話し合いの場というものをもっと持っていただきたいということと、あと、これに併せて要望もしてしまうのですけれども、ほかの２ルートについても、やっぱり運行を開始してほしいということを思います。１点、質問したいのですが、今回この陳情を出された方が、資料としてアンケートの中間集計報告を提示してくださいました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-001"},{"speaker":"田中委員","kind":"意見","question":"せっかくの資料でしたし、あと、大量に資料があるとなったときにはちょっと大変だったとは思うのですけれども、今回、たったの１枚だけで、とても分かりやすい資料だったと思うので、ぜひ配付していただけたらなということを思いました。これは意見として発言させていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-002"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"今回、コミュニティバスの運行に関する陳情ということで、南大井の地域の方から出されたものです。大井町駅に歩いていくと、２５分から３０分ぐらいかかってしまう。こうした声をしっかりと受け止めていただいて、ルート変更も含めてやっていっていただきたいというふうに思うのですけれども、この南大井の住民の交通の不便さを、区のほうでは認識しているのかどうかというところで伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"大井ルート、南大井地域に限らず、それぞれほかと比較した場合で、劣っている、あるいは充実しているというところが様々だと思いますが、そこをやはり客観的な指標として、１１の指標を点数化して、各１３地域を比較して最終的な候補ルートを。","voiceIndex":10,"id":"exchange-003"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"どうやってルートを決めていったかというのは分かりましたけれども、そうではなくて、南大井の住民の不便さを、区はどのように考えているかということでお聞きしましたので、その答弁をいただきたいと思います。","respondent":"鈴木都市計画課長","answer":"そうしたところには、交通不便地域を多少なりとも解消できるようにというところで、大井第三地域センター管内ですべてのルートを完結せずに、そうしたルートの設定も１つには配慮をしています。","voiceIndex":12,"id":"exchange-004"},{"speaker":"のだて副委員長","kind":"質問","question":"住民の声を生かしてルート設定をしていくということが必要だと思います。伺いたいと思います。旧東海道のところですとか、大井町駅、そういったところを経由することで利便性も高まってくると思いますので、利用率も上がっていくということで、利用しやすいルートになると思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"基本的にこうした区民の声をこのルート検討に反映していくという視点は非常に大事だとは思うのですが、やはりこうした声をすべて反映した形でのルート設定というのは、現実的に非常に不可能だというところと、やはりルート設定にあたっては。","voiceIndex":14,"id":"exchange-005"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"反映すべきところは反映してきているということですが、それでは、この南大井地域を通らないということ、反映させなかったということには、どういった理由があったのか。実際にこの南大井を通るルートを検討したのかということで質問をいたしましたので、そのご答弁もいただきたい。","respondent":"鈴木都市計画課長","answer":"本日机上配付となっております資料の、ルートの追加と拡充とともに停留所につきましても、やはり地域からそれぞれの施設について直接行けるようなルートというところは、これは、重ね重ねになりますが、ほかの地域でもいただいているところですが、公共施設であったり。","voiceIndex":16,"id":"exchange-006"},{"speaker":"のだて副委員長","kind":"質問","question":"民間のルートとの競合ということを言われるのですけれども、そう考えるなら、旧東海道のほうを通れば同じルートは通らないというふうになると思うのですが、そういった検討もされたのでしょうか。伺います。やはりこうした利便性が上がっていくルートにしていくべきだと思うのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"ご質問いただいた旧東海道沿い、先ほどご紹介しましたが、２００ｍ近傍には第一京浜国道のところに民間のバス路線が走っているというところと、やはり１３地域ごとで補完という意味合いで。","voiceIndex":18,"id":"exchange-007"},{"speaker":"のだて副委員長","kind":"質問","question":"大崎ルートでは検討して変更したということですけれども、それがこの大井ルートではなぜできないのか、伺います。","respondent":"鈴木都市計画課長","answer":"基本的には、今回、陳情いただいた方のお住まいの周辺、南大井周辺になりますが、そこから大井町駅を結ぶルートが、繰り返しになりますが、既に第一京浜国道を通るバス路線として設定されてありますので、そこに並行して旧東海道を走らせるということは、やはり同様のルート。","voiceIndex":20,"id":"exchange-008"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"今回、試行ルートは１ルートだけを進めていくと、先行してやっていくということですけれども、２月の建設委員会で、ほかのルートをやらないのかというところの質問で、判断の１つとして、コロナ禍で、今後、収束が不透明だと、コロナ感染防止対策にいろいろ予算を投入していかなければならない中で、まずは導入効果の高い大井ルートを実施していきたいということで答弁されているのですけれども。","respondent":"鈴木都市計画課長","answer":"冒頭でご紹介しましたように、今のコミュニティバスの状況は、今まさにプロポーザルを行っているところでございまして、この具体的な中身については、この場でご紹介することはできませんが、６月上旬の事業者選定に向けて、今、プロポーザルを実施しています。","voiceIndex":22,"id":"exchange-009"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"１ルートだけ先行実施していくということですけれども、ほかの２ルートもやはり実施してみなければ、どれだけ導入効果があるのか分かりませんので、１ルートをやって判断をしてやめてしまうということはないようにしていただきたいと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"まだ全く実績のない品川区にとって、３つ同時にやるよりは、やはり一番導入効果の高い大井ルートで、様々な取組、検証を行いながら、試行運行、その後のほかの２ルートについてどうしていくかというところをしっかり検討しながら。","voiceIndex":24,"id":"exchange-010"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"利便性を考えれば、ぜひ増やしていっていただきたいと思うのですけれども、いかがでしょうかということと、八潮－大井町駅路線が廃止になった理由を事業者から聞いていましたら教えていただければと思います。","respondent":"鈴木都市計画課長","answer":"区のほうには事前に説明がありまして、地域交通検討会の中でも情報はお出ししていますが、その理由としては、基本的には、従前から乗車の人数が非常に少ないというところと、それから、その当時、説明があったのは。","voiceIndex":26,"id":"exchange-011"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"この京急バスについて復活と増便を求めているわけですが、区としてのお考えを伺いたいと思います。私は、ぜひ住民の利便性向上のために区としても動いていただきたいと思うのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"民間バス事業者の実施体制といいますか、営利的なところも踏まえて検討されるですので、区民の声としては、その都度、バス事業者には伝えておりますが、やはり区として求める、要望する内容につきましては、例えば補助２６号線が開通した場合のバス路線の新設ですとか。","voiceIndex":28,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"ちょっと教えてほしいのですけれども、このルートを考えたときに、ルートをもう少し広げた場合を考えると、例えば１周するときに時間がかかってしまうわけですよね。そうするとニーズも変わってくるというところがあると思うのです。そういうニーズのとり方とか、あとは民間事業者の方々との意見交換の在り方とかというのは、今後どういうふうな形で進めていこうとされていますでしょうか。","respondent":"鈴木都市計画課長","answer":"ご指摘のように、本当に勝島などは、倉庫街からマンションが建ち出してきて、若い世代の方が非常に多く住み始めているというところで、短期間に集中的に人口が増えて、それでバスの需要が高まってというところも今後出てくるところがあるのかどうかですが、今回の勝島などは。","voiceIndex":31,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"このコミュニティバスの試行運行に際しての検討は、非常に細かくよくされているなと思うのですよね。ですので、今回こういう形で試行でやっていただいて、いろいろと課題もあるでしょうし、いろいろな見方も出てくるかと思うので、今後も継続的にお話し合いがされるということですから、それに期待したいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"すみません、確認だけさせていただきたいのですけれども、コミュニティバスの運行事業に係る事業者の募集の事業概要書の中で、事業継続の考え方について、本格運行への移行についての中で、「試行運行４年目（令和７年度）に、令和８年度以降の本格運行への移行（本格導入）ならびに路線廃止を選択肢に入れた見直しの実施について、区が判断を行う」というのがあるのですけれども、いつだったか。","respondent":"鈴木都市計画課長","answer":"それとともに、利用者の方に、どういう形になるか分かりませんが、アンケートなどもとりながら試行運行を行っていきたいというところで、その試行運行期間の中では、試行錯誤を行いながら行っていきたいというふうに考えてありますので、最終的な判断も。","voiceIndex":35,"id":"exchange-015"},{"speaker":"田中委員","kind":"質問・要望","question":"収支率５０％以上というのもとても分かるのですけれども、ただ先ほどお話もあったとおり、やっぱり福祉の面でのコミュニティバスという視点は欠かさないでいただきたいということを思っていて、区民の方が求めているのであれば、この収支率５０％ではなく、区民の意見がまず第一に来て、廃止をするのではなくて、区民の意見を聞きながら継続されるように改善を、そういった運行をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-016"},{"speaker":"若林委員","kind":"質問・要望","question":"本日結論を出すでお願いします。コミュニティバス、これまでも様々な、数多くの陳情が出される中で、まさに様々なご要望が地域から出されているという中だと思います。この点については非常に評価をする中で、今日の個別のルートも含めて、様々なルート、要望をまた１つ捉えられたというふうに私どもは理解をしております。この声も地域の声として捉えていただきたい。ということで、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-017"},{"speaker":"大沢委員","kind":"質問・要望","question":"それゆえに、ここのところを先行して導入するという、試運転でしょうか、それをやるというまさに行政ならではのスタンスに出たわけであります。よって、この最後に言った税の公平性、やはりまだ満足度１００％に近づけるご努力は必要ですけれども、個別の案件について、要望を取り入れて変更するという作業は非常に大変な作業になりますので、このところは承服できない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-018"},{"speaker":"のだて副委員長","kind":"意見","question":"結論を出すということで、採択を主張します。いろいろなところで様々声があるということですが、やはりそういった声をしっかり反映していくことこそ、使いやすいコミュニティバスにしていくことになると思いますし、やはり住民の方々が交通不便を感じているというこの困難を改善していくためにも重要だというふうに思いますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出すで、趣旨採択を主張します。生活者ネットワークとしても、コミュニティバスの個別の判断というのはなかなか難しいなと、それぞれの要望を聞いていると、そのルートもどんどん広がっていってしまうので。やはり話し合いの場が少なかったと思うので、ぜひそういう機会をこれからももっとつくっていただきたいということで、趣旨採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"これから先のこともいろいろ考えられていると思いますので、それで進めていただきたいと思います。ただ、その中で１つは、やはり情報。それから、こういう形で請願・陳情がときどき出ていますけれども、これは今進めているからということではなくて、やはり住民の皆さんの気持ちもあるので、こういう地域はこういう不便さがあるのだなとかというのは、大きな情報の１つだと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-021"}]},{"id":"topic-02","title":"品川区営住宅・品川区立区民住宅指定管理者候補者の公募","agenda":"品川区営住宅・品川区立区民住宅指定管理者候補者の公募","exchanges":[{"speaker":"田中委員","kind":"質問","question":"選定委員会のことでお伺いしたいのですけれども、品川区立区民住宅・品川区営住宅指定管理者選定委員会設置要綱を見たときに、第２条の組織を見たら、「（６）その他委員長が必要と認める者」という記載が委員会構成の組織の中にあるのですが、委員長というと都市環境部長に当たるのですけれども、その委員長が必要と認める者が、これまでの選定委員会の中でいたのかということと、もしいたならば。","respondent":"竹田住宅課長","answer":"従来は、外部委員の方は特にいらっしゃらない形で進めてまいりました。しかし、今年度につきましては、一定、選定委員会の形の見直しを行いまして、二段階で選定委員会を開くことを予定しております。","voiceIndex":54,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"その改定された方針が生かされて今回のようなことになったのかという部分と、あと、特に区営住宅には、やっぱり福祉的な視点も必要だと生活者ネットワークは考えていて、そういった委員の方たちが、これからは組織の一員になるのかなと思ったのですけれども、いかがでしょうか。その辺をお知らせいただけますか。","respondent":"竹田住宅課長","answer":"総務委員会でご報告させていただいた内容に沿いまして、今回、区全体で選定委員会の方式を改めて、今年度より開催する予定です。","voiceIndex":56,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"モニタリングの評価もよかったのではなかったかなと思うのですけれども、その中で、５の指定管理者候補者の選定の中で選定基準というのがあります。これはどうやって評価をするのでしょうか。非常に主観が入ってしまうのではないかと思うのですが、やはり選定であるならば、ある程度の、数値が一番いいのでしょう、分かりやすいと思うのですが、これはどうやって選定していくのでしょうか。","respondent":"竹田住宅課長","answer":"あまり申し上げると選考に影響しますので、概略の部分だけを申し上げますが、例えば、人員の配置体制、滞納者に対する納付指導、それから管理コストの削減、環境に対する配慮、あるいは社員教育などを具体的に計画、ヒアリングしまして。","voiceIndex":60,"id":"exchange-024"},{"speaker":"西本委員","kind":"提案","question":"それともう１つは、指定管理者制度を使っているということで、かなり品川宅建管理センターもいろいろやっていただいていたのではないかと思うのですけれども、指定管理者制度だから、独自でいろいろと工夫を凝らしてやっていただく、いろいろ改善をしていただいたり、提案をしていただいたりということが必要だと思うのですが、それは今までの実績、そしてこれから品川区として。","respondent":"竹田住宅課長","answer":"今までの指定管理者で行われました内容ですが、例えば、地域づくりとか、それから居住者間のトラブルの回避等々をやっていただいております。今後も区民サービスを的確に捉えた満足度の高いサービスをしていただける指定管理者を選定していきたいと考えております。","voiceIndex":62,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"指定管理者制度というのと、それから委託というのがあると思うのです。委託とは全然違うわけですよね。指定管理という制度を使う以上は、民間のノウハウを活用していこうという大きな動きの中の１つの手法なのですよね。それが本当に生かされているのかどうかというのは、区として何をしたいのかというのをもう少し明確にしていただきたい。そういうものも含めて評価をするという認識でよろしいでしょうか。","respondent":"竹田住宅課長","answer":"このプロポーザル方式による公募の趣旨ですが、民間企業の能力やノウハウを活用して、満足度の高いサービス、あるいは経費削減をするものが今回の趣旨ですので、新たなる提案等をしていただきまして、よりよい指定管理にしていきたいと考えております。","voiceIndex":64,"id":"exchange-026"},{"speaker":"のだて副委員長","kind":"質問","question":"やはりこういった企業というのは、１つの目的としては、利益を上げていくということになりますので、こういった住宅の管理をしていく中で、なかなか利益を上げていくというところはないというふうになっていくと、人件費を削減したりとかということになって、そうすると、労働者の方々が大変な状況になってしまいますので、区営、直営にしていくべきだと考えますけれども、いかがでしょうか。","respondent":"竹田住宅課長","answer":"その中では、民間企業を含め、広く公募し、そのノウハウを活用していくというのが趣旨です。区営住宅につきましても、平成１８年度からこの制度を実施して一定の成果を上げているところです。直営に戻す考えはございません。","voiceIndex":67,"id":"exchange-027"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"戻す考えはないということですが、やはり私は、直営にすべきだということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-028"}]},{"id":"topic-03","title":"品川区耐震改修促進計画の改定","agenda":"品川区耐震改修促進計画の改定","exchanges":[{"speaker":"田中委員","kind":"質問","question":"２７ページには区民の声が記載されているのですけれども、こういった声は生活者ネットワークも本当によく聞いていて、どうやって改善できるかということを考えているのですが、ブロック塀についても、助成制度があるといった周知がなかなか区民の方に知られていない状況がある中で、どうやってこれから浸透させていくのかというところを伺えればと思いますが、いかがでしょうか。","respondent":"長尾建築課長","answer":"１つは戸別訪問を引き続き、または事業周知については戸別のポスティングという形が１つ考えられるのですが、今後の課題として捉えております。","voiceIndex":74,"id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもたちの通学路の近くとかに、やっぱりまだブロック塀があって危険だなと思う箇所が幾つかあるので、今ありましたように戸別のポスティングとかで、ぜひこれからもお知らせをしていっていただきたいと強く要望いたします。","respondent":"長尾建築課長","answer":"建築課のほうには、ある程度、これまで行われている地盤調査の結果も閲覧できるようにしておりますし、最近ですと、東京都のホームページとか、国のホームページでも、一定程度、地盤調査の結果が公表されておりますので、そういったところを確認いただきながら、また。","voiceIndex":76,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"１点だけ。ブロック塀の安全化支援なのですが、これは道路に面したブロック塀というふうに認識しているのですが、道路に面していなくても、近隣とのブロック塀があって、そこにも区からのご案内とかが入っていたのです。それを見ると、助成してくれるのかなと期待してしまったのですが、先ほど個別対応というふうに言っておられましたけれども、それはどういう状況でしょうか。","respondent":"長尾建築課長","answer":"こちらは平成３０年度に行った調査結果をもとにして戸別に周知を行っているのですけれども、居住者の方もしくは所有者の方から、うちにはもう道路沿いの塀がないのだけれどもというようなお問い合わせというか、確認のお電話もいただいておりまして、今。","voiceIndex":79,"id":"exchange-031"},{"speaker":"西本委員","kind":"意見","question":"隣同士のところに同じように塀があるわけですけれども、それも助成していただけるとうれしいななどと一瞬思ったのです。たしか違ったのではなかったかなと思いながら、私は知っているから違うだろうなという認識があるのですけれども、いろいろ訂正するのは難しいと思うのですが、今後、誤解のないように、可能であるならば、その壁も助成を。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":81,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"２３ページなのですけれども、区有建築物のところで、耐震診断の結果で、今後対応すべき施設が２棟残っているということなのですけれども、この２棟というのはどこなのでしょうかということをお知らせいただきたいのと、あと、５１ページの超高層建築物等の長周期地震動対策についての情報提供の部分なのですけれども、今、品川区内にはとても高い建物が建っていますが。","respondent":"長尾建築課長","answer":"荏原第一地域センターにつきましては、武蔵小山駅前に新しく建ちました建物のほうに７月に移転予定ということで、これは表の内容自体が令和３年３月現在ということですので、カウントせざるを得なかったのですけれども、１つは解消予定となっております。","voiceIndex":83,"id":"exchange-033"},{"speaker":"田中委員","kind":"質問","question":"２３ページの部分です。区有施設の耐震のことについて。１つは、荏原第一地域センターが解消予定ということだったのですけれども、今の荏原第一地域センターのところに、今後、男女共同参画センターが入るという話も聞いていたのですけれども、それもなくて、今あるものはそのまま残すのですか。どうするのでしょうかというのがちょっと疑問に思ったので、お伺いしてもよろしいですか。","respondent":"長尾建築課長","answer":"すみません。予定されている施設については、既存のきゅりあんのほうに入っている建物の改修工事中の仮使用といいますか、移転先として使う予定となっておりますので、その工事が終わればまた元に戻るというところで計画されているものです。","voiceIndex":85,"id":"exchange-034"},{"speaker":"田中委員","kind":"質問","question":"仮移転先というのは承知しているのですけれども、でも、今、既存の荏原第一地域センターのところは、耐震すべき建物ではあるのですよね。今後、耐震工事を行って活用していくとか、そういったことでしょうか。何もせず、そのまま置いておくということはないですよね。","respondent":"長尾建築課長","answer":"荏原第一地域センターが新しい建物に移転することで、区有施設としての地域センターは耐震化が図られた建物に移転しますので、それでまずは１つ耐震化が図れたというようなカウントになります。","voiceIndex":87,"id":"exchange-035"},{"speaker":"大沢委員","kind":"質問","question":"今の荏原第一地域センターについて。前回この耐震化の話が出てきて、そのときはそうではないような話で、水神児童センターだけが出てきたのですけれども、その間、どのような状況があって荏原第一地域センターがここにカウントされてきたのか、教えてください。","respondent":"長尾建築課長","answer":"今年の７月に移転するという予定がその時点で立っておりましたので、実質的に耐震化の見込みが立っているということで、私がご説明をしていなかったのですけれども、実際は荏原第一地域センターはもともと耐震化が図られていない建物として挙がっておりました。","voiceIndex":90,"id":"exchange-036"},{"speaker":"のだて副委員長","kind":"確認","question":"確認を１点。荏原第一地域センターが今のところから移るとなると、区有施設ではなくなるということでしたけれども、区分所有しているところに入るのではなかったかなという感じがするのですが、そういうものは区有施設ではないということになってしまうのか、そこを伺いたいと思います。","respondent":"長尾建築課長","answer":"所有権のお話と、地域センターのような施設として、区有施設として活用するかというところは切り分けて考えておりますので、この耐震化率の算定の中では、実際に使っている施設を対象としてカウントしている状況になっております。","voiceIndex":93,"id":"exchange-037"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"それで、資料のほうなのですけれども、耐震化率の今後の目標のところなのですが、これまできちんと数値を示していたと思うのですが、今回、住宅のところでは、「耐震性が不十分な住宅をおおむね解消」、民間特定建築物の多数の者が利用する一定規模以上の建築物というところは、「更なる耐震化の促進」ということで目標が挙げられているのですが、目標が曖昧というのですか。","respondent":"長尾建築課長","answer":"区有建築物につきましては、令和２年度までに防災上重要な施設は１００％の耐震化を達成するというふうな目標を設定しておりましたが、２棟についてまだ耐震化が完了しておりませんので、令和７年度までに１００％を達成するというところで、こちらの目標値については。","voiceIndex":95,"id":"exchange-038"},{"speaker":"のだて副委員長","kind":"質問","question":"今の説明ですと、基本的に計画策定時の目標をそのまま使って引用しているということだと思うのですが、説明の中で、数値にすると目標が後退してしまうというお話があったのですが、そこのところがよく分からなかったのですけれども、どういうことかということを伺いたいのと、あと、この多数の者が利用する一定規模以上の建築物では９５.１％になっておりますが、全体の数が分からないのですけれども。","respondent":"長尾建築課長","answer":"住宅の目標値の設定につきましては、平成２９年度の計画の中で、令和２年度と令和７年度の耐震化率の目標値は設定しておりました。そちらの設定した目標値をそのままスライドしているというところになります。","voiceIndex":97,"id":"exchange-039"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"目標が下がってしまうという説明は分かりましたけれども、文章で書くと、言葉は適切でないかもしれませんけれども、曖昧になってしまうのではないかというふうに思うのです。その中で除却ですとか、不燃構造化支援ですとか、こういった助成制度をぜひ区内全域に広げていただいて、そうすることで耐震化率も上がってくるというふうに思いますので、そうしていただきたいと思いますが、いかがでしょうか。","respondent":"長尾建築課長","answer":"耐震改修につきましては、区内全域に既に広めておりますので、診断等も今もお受けしておりますし、そういったところは建築課のほうで引き続き対応していきたいと考えております。","voiceIndex":99,"id":"exchange-040"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"民間の建物については１００％という目標はなかなか難しいということでしたけれども、そうすると、２０２７年度は１００％を目指していくというつもりで取り組んでいくという区のお考えでいいのかというところを確認させていただきたいと思います。","respondent":"長尾建築課長","answer":"今回、耐震化率の現状把握を改めて行っておりまして、特に木造住宅と緊急輸送道路沿いの耐震化を課題として認識しておりますので、これまでの拡充してきた助成事業をしっかりと周知して、皆さんに使っていただきながら、耐震化をさらに進めていきたいと考えております。","voiceIndex":101,"id":"exchange-041"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"これまでも制度を拡充してきたということです。そうすると、今後も計画をつくって、その後も拡充をしていくということだと思いますので、ぜひ耐震化率１００％を目指して進めていっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-042"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ、頭出しだけするので答弁は要らないです。そういうことによってＣＯ２の削減に品川区としても自治体として一緒になって取り組んでいるのだよということを、取りあえず６００億円あって、品川区に来るのは非常に少ないけれども、そういうものがあるわけだから、それは一緒になって取り組んでいきますよという、そういう外へ向けて発信することも１つ必要だと思っています。それだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-043"}]},{"id":"topic-04","title":"しながわECOフェスティバル２０２１の開催中止","agenda":"しながわECOフェスティバル２０２１の開催中止","exchanges":[{"speaker":"西本委員","kind":"意見","question":"去年に引き続き、今年も非常に残念だなというふうに思っております。ただ、このECOフェスティバルはいろいろ目玉がありますよね。ですので、今回は残念なのですが、これは仕方がないことだなと思っています。ですので、けじめはけじめで早くしていただいてもよかったかなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":110,"id":"exchange-044"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"質問","question":"今ご説明いただいた説明会については、机上配付の資料とかも特にはないということですか。口頭だけの説明なのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-045"},{"speaker":"田中委員","kind":"質問","question":"説明会の実施については、どのように住民の方たちにお知らせをするのか、周知方法についてお伺いします。","respondent":"中道まちづくり立体化担当課長","answer":"説明会の周知についてですが、先週、ＪＲ東海からは、区の広報紙に掲載をしたいということを要望として聞きました。今、区としましては、今ご説明した内容を広報しながわ６月１日号に記載をしていくというところで調整をしています。","voiceIndex":117,"id":"exchange-046"},{"speaker":"田中委員","kind":"意見","question":"ＪＲ東海の周知については、今後ということですね。了解しました。区のホームページではお知らせはあるのかということと、あと、この大ホールで５００名ということだったのですけれども、これは抽選だったりとか、直接会場に行ってしまっていいのか、それとも何か、今、感染症のこともありますし、申込みとかが必要なのかとか、そういった点についてもお知らせいただければと思うのですが。","respondent":"中道まちづくり立体化担当課長","answer":"区のホームページでの開催案内ですが、区としましては、ホームページに掲載する予定はございません。ＪＲ東海からは、先着５００名というところでお話は聞いてあります。特に何か事前に申込み等が必要ということは聞いてございません。","voiceIndex":119,"id":"exchange-047"},{"speaker":"田中委員","kind":"意見","question":"このリニアの問題も、やっぱり区全体に影響があるので、特定の地域の方たちだけではなく、周知はしてほしいと思います。先着５００名ということだったのですけれども、やっぱり十分な周知がなおさら必要なのかと思うのです。区のホームページでは広報しないということだったのですけれども、その理由についてお知らせいただけますか。","respondent":"中道まちづくり立体化担当課長、塚本委員長","answer":"ですので、まず今回、コロナ対策というところで、先着５００名というところもありますので、ＪＲ東海が考える対象者にまず照準を絞って。田中委員、先ほどご説明にもありましたけれども、これは、説明会が６月８日ということで、先週末かなり急に決まって、今日、この委員会に報告するというのは、本当に生煮えの情報ということがあるのです。","voiceIndex":121,"id":"exchange-048"},{"speaker":"田中委員","kind":"質問・要望","question":"説明会の対象者について、ＪＲ東海が考える対象者がまだ分からないということなのですが、ただ、シールド工事のことでリニアについて関心が高まっている中で、区として積極的に区民への周知は必要だと思います。大変だったろうなということは感じるのですけれども、ただ、区民にとっては、この情報は積極的に区として出していただきたいということを強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-049"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"まとめて伺いたいと思いますが、今回の説明は、シールド工法の取組と安全性ということだったのですが、外環道の工事で陥没事故などがあって、やはりそういった住民の皆さんの不安や心配というところで、これに関連して説明をしたいということなのかなと受け止めたのですが、そこの確認と、今回、説明会をやるにあたって、先着５００名ということで、コロナ対策というのは一定理解するのですけれども。","respondent":"塚本委員長、中道まちづくり立体化担当課長","answer":"先ほども申し上げましたけれども、先週末、非常に急な話で、建設委員会は日程的に今日しかないということで、口頭での説明ということであえてしていただいていますので。ですので、５００名の説明会の２回目とか、そういったことは、まだＪＲ東海とは特に何か話しているということはないのですけれども、やはり先ほどの丁寧な説明というところでＪＲ東海とは話を進めていますので、そうしたことを踏まえて。","voiceIndex":126,"id":"exchange-050"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"周知の件ですとか、その辺の回答がなかった。地上への影響についての説明をしてほしいということで、それを要望していただきたいということで、それをご答弁いただければと思います。","respondent":"中道まちづくり立体化担当課長","answer":"今、ＪＲ東海も、関連する影響範囲とか、そういったことを踏まえて周知範囲を検討しているということですので、まず、そこの部分について、ＪＲ東海の見解を確認していきたいというふうに考えてあります。","voiceIndex":130,"id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"ＪＲ東海のホームページでも今後は説明会についての記載がされるのか。今は、私の調べ方が悪いのか、ＪＲ東海のホームページを見たときに、その説明会の実施ということが書かれていなかったのですけれども、もしＪＲ東海でもそういった周知をされるのであれば、それを区のホームページでも貼りつけていただきたいなと思うのですが、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"ＪＲ東海のホームページの活用方法ですが、今までの流れでいきますと、説明会をした後に、説明会で使った資料などをホームページに記載をしています。","voiceIndex":132,"id":"exchange-052"},{"speaker":"田中委員","kind":"質問・要望","question":"そういった方たちのためにも、ぜひ区として積極的にＪＲ東海にも、説明会の後に資料を公開するのではなく、説明会の開催の周知についても求めてほしいですし、区としても区のホームページでもお知らせをしていただきたいと思います。区の広報が６月１日。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-053"},{"speaker":"田中委員","kind":"質問・要望","question":"その配布場所が示されたことや、区のホームページで報告されたことについては、とても評価をしているのですけれども、まだまだ周知が足りないので、周知と、あと拡充をしてほしいなといった方向から質問したいのですが、まず、この「羽田空港のこれから」、国が出している通知なのですけれども、このカードについては、いつ、何枚、区に届いたのか、まずお知らせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-054"},{"speaker":"田中委員","kind":"質問・要望","question":"カードがいつ配布されたのか。何枚区に届いたのか。国のこのカードが、品川区から国に求めて配布されたのか、それとも、国からどうぞといった形で届いたのかといったことや、これまでの経緯について伺いたいのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"ご意見カードについてのこれまでの経緯のお尋ねですが、ご意見カードにつきましては、本格運用決定前の平成２７年辺りだったと思うのですが、オープンハウス説明会ですとか、区内１３地域での説明会ですとか、あるいは、情報発信拠点での説明会場ですとか。","voiceIndex":138,"id":"exchange-055"},{"speaker":"田中委員","kind":"質問・要望","question":"届いたのは１２月の下旬ということで、１００部だったということで、区として、この１００部を区から求めたのか、それとも国のほうから１００部を渡されたということなのかというところと、あと、この１００部だと、どうしても足りないのではないかということを思っていて、区民の方たちからは意見を述べたいといった声がとても多くありますので、ぜひ１００部以上。","respondent":"塚本委員長、鈴木都市計画課長","answer":"学校に関しては教育委員会なので、これは答えられないと思います。踏み込まないようにお願いします。配架したというご案内ですが、基本的には、先ほども委員からご紹介いただきましたが、区のホームページも１２日に修正をいたしまして、ホームページ上でお知らせをしています。","voiceIndex":141,"id":"exchange-056"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"二部で足りなければ、また別の日も設けていただきたいと思います。特にこのアンケートにも示されていますけれども、回答数、１回目が２７３名で、２回目が３２８名ということですから、やはりそれだけ関心を持っている方がいるということになりますので、ぜひ周知をしっかりしていただいて、できる限り参加できるようにしていただきたいと思いますが、いかがでしょうか。","respondent":"高梨公園課長","answer":"その結果を受けて、約３０名前後の出席といったところで想定をしていますが、今、委員からもありましたとおり、基本的には抽選といった形で人数を絞るのではなくて、出席したいという方の人数に応じた開催ということで、大人数となった場合には。","voiceIndex":189,"id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"すみません、説明会のことから外れてしまうのですが、１つだけ要望を言いたいと思います。樹木がいろいろあると思うのです。ここだけではないのですけれども、今回、多様な品種の桜をということで、いろいろなものがあると思うのですけれども、木の名前について、プレートか何か、つけている場合もあるのですけれども、そういうものをなるべくつけてほしいなと思うのです。要望だけ申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":192,"id":"exchange-058"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、なかなかホームページとかでも情報をつかみ損ねてしまう方とかもいると思うので、例えば、スポーツをされている子どもたちへの情報発信とかをどのように考えているのか、説明会の実施についての情報発信をどのように考えているのかなど、具体的な周知方法を、ホームページよりも、もうちょっと広く考えた何かを、もし検討されているのであれば、お知らせいただきたいと思います。","respondent":"高梨公園課長","answer":"説明会のほか、ホームページ以外の周知方法といったところですが、まず、今ご提案のありましたスポーツをしている子どもたちといったところにつきましては、今回アンケートをする段階でもそうなのですけれども、各スポーツ団体等にヒアリングをしまして、利用している子どもたち。","voiceIndex":194,"id":"exchange-059"},{"speaker":"田中委員","kind":"質問","question":"先ほど、都市環境部のところで、「羽田空港のこれから」のご意見募集のはがきについて、その他で伺いましたが、このことについては、前もって委員長と担当の課長にも伝えていたにもかかわらず、あのように途中で打ち切られてしまったのはなぜなのかと、とても納得がいかないと思いまして、その他の運用というのですか、その他というのはどうやって委員会運営していくのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-060"},{"speaker":"田中委員","kind":"確認","question":"後ほど、会議規則でその他の取り扱いについて確認をしたいと思います。私がここのところの知識がなかったので、申し合わせ確認事項とかで確認をしたのですけれども、特にその他の扱いについて、ああやって途中で議論が遮られてしまうようなことが書かれていなかったので、おかしいなと思ったのです。会議規則のほうということで確認をしました。分かりました。私からは以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":199,"id":"exchange-061"},{"speaker":"西本委員","kind":"質問・要望","question":"その他のところでは議論をするという場ではないということだと思うのです。ただ、先ほど田中委員のほうからのご指摘の内容は、やはり興味のある部分でもあるし、議論するべきものだろうと私も思っております。報告事項の中で議論させてほしいというのは、委員長にお願いをするとか、依頼をするという。ちょっと今日は引継ぎも何もできる状況ではないなということを率直に思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":200,"id":"exchange-062"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"その他の取り扱いということですが、やはり委員の関心のもとで質問ができる機会が設けられているということですので、質問するということは保障していくべきだと私も思います。今回の議題も関心が高い、私自身も興味のあるところでしたので、そこはぜひ保障していただきたいと、私からも意見を言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":202,"id":"exchange-063"},{"speaker":"石田（秀）委員","kind":"質問","question":"西本委員が言ったとおりです。このことについて委員長に申し出があって、委員長が、それではこれはどうなっているのだと行政側にも話をして、では、これは報告事項で上げてくださいというのは、委員長の権限としてあるわけだから。別にその他で質問を止めているわけでも何でもなくて、今日の場合では、ちゃんとその他の扱いの中で、それを踏まえてやってくださいねと。それだけのことだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":203,"id":"exchange-064"},{"speaker":"大沢委員","kind":"意見","question":"委員会の運営は委員長にすべて権限があるわけです。委員会の運営権はすべて委員長が持っていらっしゃることですので、そこはもう総合的に判断をされて先ほどのやり取りになったと思います。さっき田中委員がおっしゃったような遮っているというお考えには、私は当たらないと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":204,"id":"exchange-065"},{"speaker":"田中委員","kind":"確認","question":"前もって委員長にも、そして担当の部長、課長にも、こういうことを聞きますということを伝えていて、「最後の質問にしてくださいね」と委員長が言ったときに、質問したことに対して答弁が足りなかったのです。私はもう一度、各配布場所にそれぞれ何枚ずつ配布されたのかというのを確認したかったので、再度質問しようとしたときに、もう最後の質問だと言ったので、もう駄目ですとなってしまったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":205,"id":"exchange-066"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"田中委員にぜひお考えいただきたいのは、先ほど来、委員長がそういう形で委員会を仕切っていらっしゃって、最後の質問にしてくださいということであるならば、こういうことで、どこに何枚、どういうことで全部やっているということも含めて、ご質問をするということならいいわけで、それが答弁が違う答弁だとしても、それはここで全体のことを考えているのであるならば、そこはそこで止めるということも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":206,"id":"exchange-067"},{"speaker":"田中委員","kind":"質問・要望","question":"今回のこの件に関しては、生活者ネットワークとして、担当の部課長にも、その他で取り扱いをするようにということも求めています。ぜひそういった議論の場、きちんと議事録に残すという、公の場に残すということは大事だと思うので、そういった議会となってほしいなという要望も併せて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-068"},{"speaker":"西本委員","kind":"質問","question":"今後のこともあるので、仕切りの話なので。その他のところで議論はあまりしてはいけないと思うのです。その他は、報告があって、多少質問はあるかもしれないのですけれども、そこで議論は難しいと思います。議論するのだったら、ちゃんと報告事項に上げてくださいと。今日の流れでいうと、二、三回質疑をやっている状況で、これはもうちょっと深い議論が必要だなと思うわけではないですか。すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":209,"id":"exchange-069"}]},{"id":"topic-06","title":"品川区営自転車等駐車場指定管理者候補者の公募","agenda":"品川区営自転車等駐車場指定管理者候補者の公募","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"指定管理者候補者の選定について伺います。品川区営自転車等駐車場指定管理者候補者選定委員会設置要綱を読んだときに、組織、第２条のところで、「（６）その他委員長が必要と認める者」というものがありますが、これまでのこの選定委員会の中で、委員長が必要と認める者とした委員がいたのかということと、もしいた場合には、どういった方が選定されたのかということをお知らせいただきたいです。","respondent":"川口交通安全担当課長","answer":"過去の指定管理者の候補者の選定に関して、特に必要と認めて要望したものはございません。","voiceIndex":153,"id":"exchange-070"},{"speaker":"田中委員","kind":"確認","question":"４月１９日の総務委員会で指定管理者制度活用に係る基本方針の改定が報告されたのですけれども、今回、この選定委員会の中で、その基本方針改定のものが生かされるのかどうかといったところを確認したいのと、どういったところが生かされるのか、生かす部分についてお知らせいただければと思います。","respondent":"川口交通安全担当課長","answer":"その後、選定委員会がありますけれども、これは以前のメンバーから有識者委員が含まれることとなります。具体的には、学識経験者や弁護士で構成。これから具体的に人選を行う予定ですけれども、そちらのところも適切に対応してまいる予定です。","voiceIndex":155,"id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"選定基準のところで、先ほどの区民住宅のところでもちょっとお話ししたのですけれども、「物的能力」、「人的能力」、「十分な能力」と書いてあるのですけれども、何の能力ですか。この選定基準の中で非常に曖昧なので、どういう能力を差しているのかというのをお示しいただけますか。","respondent":"川口交通安全担当課長","answer":"こちらにつきましては、今、資料に記載をさせていただいているのは、一般的な基準として示させていただいているところでございまして、今回は自転車等駐車場になりますので、例えば、一定の自転車等駐車場における規模に応じた対応をできるスキルを持っているのかということと。","voiceIndex":158,"id":"exchange-072"},{"speaker":"西本委員","kind":"質問","question":"そうすると、その配置基準、配置の可能性とかというようなことだと思うのですけれども、何か「能力」と書かれると、いろいろな広い意味になってしまって、何を示しているのだろうかというふうに思うわけです。いろいろな人がいらっしゃいますよね。そういうのは何か選定基準の中に入っているのか、どういうふうに図って、区民サービスに対しての考え方とかというふうに基準をつくっているのでしょうか。","respondent":"川口交通安全担当課長","answer":"その辺の具体的な能力の評価という部分ではあるのですけれども、例えば、実際についていただく方に対して、日頃からどのように研修をやっていくだとか、そういうようなカリキュラム。","voiceIndex":160,"id":"exchange-073"},{"speaker":"西本委員","kind":"意見","question":"非常に評価しにくいところだと思うのです。ですので、そこら辺がちゃんと評価できるようなことをぜひお願いしたいと思う。これはやっぱり相手が住民なので、利用する側の方々が気持ちよく、危険性がないようにお願いしたいところがあるので、ぜひ評価の中にはそういうことを重視した形でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":162,"id":"exchange-074"},{"speaker":"のだて副委員長","kind":"質問","question":"前回、公募をしたときに、最終的に応募したのが１者ということになってしまったのですけれども、そういうことがないようにということで、区としては、この改善点といいますか、取組などがあるのか、伺います。","respondent":"川口交通安全担当課長","answer":"そのような形で、広く公募の期間も設けて、何とか１者にならないような対応をしていきたいというふうに考えております。","voiceIndex":164,"id":"exchange-075"}]},{"id":"topic-07","title":"道路通報システムの試行","agenda":"道路通報システムの試行","exchanges":[{"speaker":"田中委員","kind":"質問","question":"予算について伺いたいのと、あと、この通報システムの周知方法について伺いたいのと、あと、損傷や不具合といったことなのですけれども、例えば車椅子やベビーカーでつまずく道路の段差についてなどもここで報告ができる、その対象となっているのかといったところもお知らせいただければと思います。","respondent":"溝口道路課長","answer":"今回、品川区が試行するにあたって、まずはホームページ、また、５月２０日になりますけれども、プレスリリース等をかけて周知を図っていきたいというふうに考えているところです。","voiceIndex":170,"id":"exchange-076"},{"speaker":"田中委員","kind":"質問・要望","question":"車椅子、ベビーカーの報告もしていいということで、安心しました。新しくきれいになった道路でも結構段差があったりして、つまずくところがあって、どうしようかなというところがあったりしたので、ぜひ積極的にそういった報告もしてほしいとお知らせをしていただきたいと思います。","respondent":"溝口道路課長","answer":"委員がお話しされている子育てアプリのほうにも、所管課と調整して、周知がかけられるかどうか、その辺は調整をさせていただければというふうに考えているところです。","voiceIndex":172,"id":"exchange-077"},{"speaker":"田中委員","kind":"質問・要望","question":"子育てアプリのほかにも、また障害者福祉課のほうにも、ぜひお伝えいただいて、周知いただければと思います。要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":174,"id":"exchange-078"},{"speaker":"西本委員","kind":"質問","question":"これは、チラシを見ると、「都道」になっているのですけれども、品川区内の全道路という認識でよろしいのでしょうか。そのエリアを教えてください。","respondent":"溝口道路課長","answer":"一部国道も、ちょっとあれなのですけれど、話を聞いている限りですと、投稿していただければ管理者につながるとか、そういった形になるので、基本的には品川区内の道路は区別なく投稿ができるような形になるというふうには聞いているところですが、国道については。","voiceIndex":176,"id":"exchange-079"},{"speaker":"西本委員","kind":"質問","question":"区道ということなのですが、これ、私道も入ってしまうと、多分、私道までは入らないと思うのですけれども、ただ、大体、私道なのかな、区道なのかなと分かりづらいところもあって、住民は割と分からない部分があると思うのです。それから、修理という段階になったときに、このアプリで報告が来ました、その情報をどういう流れで、どういう形で、修理というか、補修というか、していくのでしょうか。","respondent":"溝口道路課長","answer":"今までと変わらず、今までご連絡がなかった区民の方たちから道路管理者のほうに通報できるシステムが新たに加わったというふうにご認識いただければというふうに考えているところです。","voiceIndex":178,"id":"exchange-080"},{"speaker":"のだて副委員長","kind":"質問","question":"既に先行してやっているところがあるということで、先行してやっている事例、取り組み状況ですとか、あと品川区も都道でやっているということなので、実際の取り組み状況を伺いたいのと、あと、今回の試行で、スマートフォンを情報収集の手段として活用した道路管理の有効性を検証していくということで、この検証が、実際、具体的にはどういう形で検証していくのかというところを伺いたいと思います。","respondent":"溝口道路課長","answer":"ほかの自治体の状況です。区部でいきますと、葛飾区、港区の２区が既に導入してやっているところですが、港区は、今年の１月から始めていまして、まだ本当に三、四件しか通報が入っていなかったりとかという状況です。","voiceIndex":183,"id":"exchange-081"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4320#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":55963,"voices":212}},{"id":"r03-20210517-9","meetingId":"r03-cm05","date":"2021年5月17日","dateIso":"2021-05-17","committee":"文教委員会","time":"午後 １時００分～午後 ４時１３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和３年度新入学学校別増減要因一覧","agenda":"令和３年度新入学学校別増減要因一覧","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、希望実数というか、そこは選択制を取って移ったという方があるのですけれども、その隣の指定校変更というのは、それなりの人数がいると思うのです。小学校で７１名、中学校で２３名なのですけれども、この経緯、それと、おおよそどういう方が指定校変更ということで入ってこられるのか、その内訳や内容などを伺いたいと思います。","respondent":"勝亦学務課長","answer":"人口が増えた分、選択によって入学できる枠が少なくなって、ご希望の数も減っているのではないかと判断しています。指定校変更につきましてお答えいたします。こちらについては、様々な要因によりまして、保護者のお申立てを受けて教育委員会が指定校を変更するものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"一定数、指定校の変更でそういう方が手続きを経て認められてということなので、私は、選択制で保護者に学校を選択させるということの弊害というのはやはりあると思うので、一方で、そういうやむにやまれぬ事情で指定校変更というので変わらざるを得ない方に対して制度上は担保されているわけですから、私はそういうのを勘案するに、選択制は必要ないのではないかと思うのですけれども。","respondent":"勝亦学務課長、有馬庶務課長","answer":"指定校変更の時期ですけれども、年度が変わりまして、この４月５月頃に転居等が出てまいりますので、そういった影響を受けて、選択制が終わってからの実施になります。抽選結果は１１月下旬に行いまして、それから最終的に１月、２月というところが最終的な抽選の結果が出ますので、小学校でいえば、１月末が終わった後、中学校でいえば２月末が終わった後の段階で。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"制度が違うので、何ともあれですけれども、ただ、やはり私は、必要な配慮というのは指定校変更でできるし、選択をさせて学校の特色を出して教育の質を上げるという、選択制そのものが私は教育の質の向上にはつながらないと思いますし、地域との関係もうまくいかなくなるという面もありますし、様々な面から、改めてこれは見直しをすべきということを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003"},{"speaker":"あべ委員","kind":"質問・要望","question":"今、学校選択制と指定校変更の話が出ていましたが、少し古い話になりますけれども、学校選択制ができる前の品川区の指定校変更は２割から３割ぐらいの数字があったのではないかと記憶しているのですが、それは選択制になっても結局動く人数は、制度が変わっても同じぐらいだったかと記憶しているのですけれども、区教委としてどのようにその数字を捉えていらっしゃるかを教えていただきたいというのが１点と。","respondent":"勝亦学務課長、有馬庶務課長","answer":"選択制の始まる前の指定校変更の考え方ですけれども、先ほど申しましたように、学校選択制、それから指定校変更につきましては、理由というか、制度的なものが違いますので、考え方としてはまた別のものかと考えています。ただ、全体の人数が増えているので、実際に入学する方は、私立に行って抜ける方もいるし、転出される方もいるし、最終的には今日説明した１４.何％というところで数字が落ち着いているということなのだろうと思っています。","voiceIndex":11,"id":"exchange-004"},{"speaker":"あべ委員","kind":"意見","question":"なので、そうした視点から今後も制度設計をしていただければと思います。人口のほう、これも教育委員会だけでどうこうということではないと思うのですけれども、今後、３５人学級の話もありますし、人口動向というのはそういう視点からもしっかりと見ていっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-005"}]},{"id":"topic-02","title":"令和４年度品川区立学校教育職員採用候補者選考日程","agenda":"令和４年度品川区立学校教育職員採用候補者選考日程","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"あるとしたら、どんな業務なのかとか、そこら辺についてまず伺います。","respondent":"工藤指導課長","answer":"そういった意味では、都費の教員との比較でいきますと、今申し上げた一貫教育の特徴と併せて、業務というところではありませんが、区固有教員の特徴としましては、やはり区固有教員だけの研修が予定されていて、教員研修については、都費の教員の研修に加えて。","voiceIndex":19,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"独自採用の教員しかやらないような業務というのは、特に日常業務ではないと理解していいのか。独自の研修もあるということなのですけれども、その独自の研修の特徴というのですか、どんな感じの特徴があるのかというのをお伺いしたいのと、あと、独自採用の財源なのですが、これは全額単費ということでよろしいのでしょうか。それとも何らかの補助金などは少しあるのかということもお伺いします。","respondent":"工藤指導課長","answer":"区固有教員の特徴的な研修につきましては、やはり今年度も６回組む中では、区独自で組んでおりますので、例えば、品川区にゆかりのある著名な方に講演いただいたりであるとか、品川区をより理解するための研修などを中心に行っているところです。","voiceIndex":21,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"改めて独自採用の教員の方を、３５人学級の小学校の全学年前倒しですとか、中学校までの拡大ですとか、そういったものに活用、そのために配置していくということが必要だと私は思うのですけれども、いかがでしょうか。それで、品川でそれを行わない理由というのですか、それは何なのかを改めて伺いたいと思います。","respondent":"工藤指導課長","answer":"他区におきまして、いわゆる固有教員を採用しているという事例については認識をしておりますけれども、それぞれ他区の事情で採用されているものと私どもは把握しています。","voiceIndex":23,"id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"管理職の方が１人ということだったのですけれども、私も最近、制度を追い切れていなくて、これは校長にはなれるようになったのですか。２７人の方の年齢構成を教えてください。","respondent":"工藤指導課長","answer":"今採用しております２７名中、特別支援教育の免許を持っているのは４名です。今、管理職というのは副校長ということで、いわゆる５級職が１名おります。現状は副校長職までの制度です。","voiceIndex":25,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"校長になれるようにということで条例改正を進めていらっしゃるというのは、大変心強い。スケジュール的な見通しというのは何かあるのでしょうか。と同時に、これ、中核市でも教員人事権という流れの中で頑張ってつくった制度というふうにも理解しているのですけれども、そもそも教員人事権についての議論というのはどこかで行われているのでしょうか。ご存じでしたら教えてください。","respondent":"工藤指導課長","answer":"本年度中にはというところの予定で進んでいるところではありますので、そのようにご了承いただければと存じます。","voiceIndex":27,"id":"exchange-010"},{"speaker":"あべ委員","kind":"提案","question":"校長職、本年度中、間もなくの条例提案ということで、大変喜ばしく思います。全体の教員の中での特別支援の免許所持率が決して高くないという中で、せめて独自教員の方々には、本来であれば全員に持ってほしいぐらいの思いですが、そこの働きかけと目標について教えてください。そこについてもお考えを教えてください。","respondent":"工藤指導課長","answer":"特別支援教諭の免許状等につきましては、免許状取得に対して助成する制度は引き続き働きかけをしていきますけれども、具体的に免許取得の目標ということで数値を定めているものではございませんが、併せて特別支援教育に対する理解に関する研修などを行っていきますので。","voiceIndex":29,"id":"exchange-011"},{"speaker":"横山委員","kind":"質問","question":"１点目なのですけれども、３番の選考区分（年齢要件）とあるのですけれども、そもそもの受験年齢制限があるというところの理由が分かりましたら、教えていただけますでしょうか。","respondent":"工藤指導課長","answer":"そういう意味では、東京都教育委員会の行っています採用選考等も勘案しておりますけれども、東京都との大きな違いにつきましては、やはり今求められている教育を担うという意味では、経験年数等が比較的、いわゆる私どもの一般選考でいうと。","voiceIndex":31,"id":"exchange-012"},{"speaker":"横山委員","kind":"質問","question":"今年もしくは来年以降とかなのですが、やはりＩＣＴに強い方であったり、民間企業でのコミュニケーション力の高い方であったりとか、そういった能力のある方の採用というのも積極的に考えていただくといいのかと思うのですけれども、３０代の若い方というのは、先ほど１２名いらっしゃるということだったのですが、４０代３名、５０代３名ということで、その辺りの考え方について。","respondent":"工藤指導課長","answer":"年齢要件をどんどん緩和していくと、それだけ募集があるというところだと思いますが、本区におきましては、前回行いました、令和元年の選考でいきますと、そのときは２０倍でございましたので、２０倍から実際に採用できたのは２名という、そういった倍率を。","voiceIndex":33,"id":"exchange-013"},{"speaker":"横山委員","kind":"質問・要望","question":"一貫教育ですとか、英語教育ですとか、また、さらにＩＣＴのほうもこれからいろいろと品川区の中で進んでいくのかと思いますので、そういったところでリーダーシップを取れるような優秀な人材というのを積極的に、要件の緩和等も含めて検討していっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-014"},{"speaker":"せお委員","kind":"質問・要望","question":"２点目ですが、これも予算特別委員会などでお話、質問させていただきましたが、小中一貫教育のところで、区固有教員というのが関わっていくのが重要だと思うのですけれども、やはりその中でも、区固有教員が特別支援教育に関わっていただくことというのが、やはり小中一貫で特別支援のお子さんというのは、そういった同じ先生がずっと関わってくれたりとか。","respondent":"工藤指導課長","answer":"３０名を目途に今進めているですが、やはり今、もちろん管理職として副校長で任用した者が１名おりますけれども、この３名を採用して３０名になった、その段階でまたさらにその後どうするかというのは検討の課題であると認識しておりますので、まずは３名。","voiceIndex":36,"id":"exchange-015"},{"speaker":"あべ委員","kind":"質問","question":"サービスコーナーの概要についてもう少し伺いたいのですけれども、これ、荏原第一地域センターだったところを、全て図書取次に使うということなのでしょうか。今後ずっとその形で、あの場所の建物が取次センターということなのでしょうか。面積的なものを知りたい。そこまでお願いします。","respondent":"吉田品川図書館長","answer":"図書取次施設として引っ越す部分が、約２０平米から４０平米ぐらいのところが図書の取次部門となります。残りの部分につきましては、男女共同参画センターが、工事の間、入る予定で進めているところです。","voiceIndex":43,"id":"exchange-016"},{"speaker":"あべ委員","kind":"確認","question":"その確認と、そもそもの図書館なのですけれども、これ、時々私も行っているのですが、品川区内の図書館は、五反田・品川エリア、大崎・品川、そうした辺りというのは、結構、整った図書館、蔵書の数ですとか、あるいは規模ですとか、新しさとか機能とか、そういうのは整っているのですが、荏原地域の図書館というのがどこも割と狭くて、若干使いづらいとか、蔵書が少ないとか、閲覧場所が少ないとか。","respondent":"吉田品川図書館長","answer":"２点ご質問いただいたかと思います。今回、荏原第一地域センター跡地に引っ越した後は、取次施設を無期限で置かれるかどうかというところについては、今のところ、特にいつまでということはなく、図書取次施設として継続していく予定です。","voiceIndex":45,"id":"exchange-017"},{"speaker":"あべ委員","kind":"質問・要望","question":"これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"３つなのですけれども、サービスコーナーで現在行っている図書取次業務の実績、かなり利用されていた、どれぐらい利用されていたのかというのをざっくりと伺いたいのが１点と、あと、新しい荏原第一地域センターのほうに移れない理由というのを伺いたいというのが２点目です。それと、移転後の委託先の業者というのは変わるのか変わらないのか。どこがやるのかというのを、３点お願いします。","respondent":"吉田品川図書館長","answer":"移転に当たっての委託先ということなのですけども、現在、サービスコーナーですので、職員と会計年度任用職員のほうで対応しているところなのですが、今後につきましては、業者に委託することで対応を進めてまいります。","voiceIndex":48,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"図書業務は結構、実は専門性の蓄積とかも必要だと思うので、今回、これまで区職員と会計年度任用職員でやっていたということですけれども、これが業者に委託ということですが、その辺は少し安易かと思います。ぜひ図書館に詳しい、あるいは利用されている方々の意見も伺いながら、そこら辺は今後検討、研究していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-020"}]},{"id":"topic-03","title":"電子図書館・音楽データベースの導入","agenda":"電子図書館・音楽データベースの導入","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"音楽も。それと、前に予算特別委員会か決算特別委員会のやり取りで、電子図書館にするに当たっての権利というか、それの関係があってなかなか難しいのだという話を聞いたような気がするのですが、そうすると、それは予算がついていますけれども、この中にそういう権利みたいなのが予算でついたという考え方でいいのでしょうか。","respondent":"吉田品川図書館長","answer":"１点目の１,０００冊の考え方なのですけれども、例えば、Ａという本があった場合、こちらの何冊分の権利を有するかというところがまず問題になります。３冊分の権利を有する、簡単に言うと、３冊本があるのと同じになるのですけれども、その場合は３人同時に借りられます。","voiceIndex":55,"id":"exchange-021"},{"speaker":"たけうち委員","kind":"意見","question":"そうすると、この５３９万円、７９万２,０００円というのは、その権利、今言った本１冊、それが３冊なのか２冊なのかは分からないですが、それを購入する権利というよりは、今ある本をデータベース化するための経費と考えていいのかということと、それから、これも多分できないということだと思うのですけれども、本であれば、いいか悪いかは分からないですが、借りてきたときに。","respondent":"吉田品川図書館長","answer":"コピーして保管ができるかどうかということに関しては、物として手元に何も残らない形になります。少し細かい話になりますけれども、画面上に本の内容が出る、表示されるだけになります。そこから何か印刷とか保存とかというのはできない形です。","voiceIndex":57,"id":"exchange-022"},{"speaker":"横山委員","kind":"確認","question":"確認なのですけれども、児童・生徒が使っているｉＰａｄタブレットからというのは使えるのでしょうか。周知方法なのですけれども、例えば、品川区のアプリ、パパママ応援アプリですとか、そういったアプリでのご案内というのはあるのでしょうか。","respondent":"吉田品川図書館長","answer":"それが取得されていて、ＩＤとパスワードの交付を受ければ、インターネットに繋げられるｉＰａｄであれば、それは見ることが可能であります。それから、パパママ応援アプリ、これにつきましても、紹介媒体につきましては、使えるものは使ってまいりたいと考えています。","voiceIndex":59,"id":"exchange-023"},{"speaker":"あべ委員","kind":"質問・要望","question":"新刊本をどのくらい選んでいくのかとか、区民の方々の要望に応えつつ、でも、出版文化に打撃を与えないような選書というのは、なかなかどこも苦労されているかと思うのですけれども、品川区として選書の一つの基準ですとか、何かそういうものを、要件という考え方があるのか。何かあったほうがいいだろうと思っているのですが、その辺りの考え方を教えていただければと思います。","respondent":"吉田品川図書館長","answer":"選書に当たりましては、実際に今考えているのは、区民の利用度の、それはどの本がどのぐらい、アナログというのですか、実際の本によってどういったものがどのぐらい借りられているかというところをまず参考にするのと、同じように絵本だとか、子ども向けのものにつきましても。","voiceIndex":61,"id":"exchange-024"},{"speaker":"あべ委員","kind":"質問・要望","question":"確かに１,０００冊というと、大々的にサービス開始というよりは、少し試行という意味合いもあるのかと思います。それでなくてもなかなか接する機会がないのですけれども、日本の音楽に逆に、特に伝統音楽に接する機会がなかなか少ない中で、せめて日本の図書館の中ではそうしたデータがそろうような機会が増えるようなことも意識していただきたいと思いますが、そこについてお考えをお伺いします。","respondent":"吉田品川図書館長","answer":"電子のこういうものというのは、図書館を含めまして始まってまだ日が浅いところがありますので、今後、いろいろなサービスが出てくると思います。そういうものがいろいろと出てきたときに、またいろいろなサービスを選んでいければと考えているところです。","voiceIndex":63,"id":"exchange-025"},{"speaker":"あべ委員","kind":"質問・要望","question":"そうですね。サービスは今後また広げていただきたいのですけれども、１つ、ポップスについてではなくて邦楽と言ったのは、どちらかというと日本の伝統音楽のジャンルなので、そこだけ誤解のないようにお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"電子図書館についてなのですけれども、全国でも電子図書館、かなり利用が広がっていることかと思いますが、今回品川区で導入する電子図書館、当然、システム会社、サービス提供会社を介してやられると思うのですけれども、具体的にどういったお名前の会社なのか。全国で比較的に使われているような会社なのかということを、まず１点お伺いします。","respondent":"吉田品川図書館長","answer":"そのため、図書館として、選びやすさだとか、そういうところを含めまして、こちらの会社を選んだ次第です。会社としましては、株式会社図書館流通センターと大日本印刷株式会社、それから、株式会社日本電子図書館サービスの３社の合体した事業となっております。","voiceIndex":66,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"音楽データベース、ナクソス・ミュージック・ライブラリーの導入ということで、これは７９万２,０００円かかっておりますけれども、その内訳を教えてください。このナクソス・ミュージック・ライブラリーというのは、そうした音楽の電子サービスで定評があるというか、それなりの実績があるところなのでしょうか。それをお伺いします。","respondent":"吉田品川図書館長","answer":"このナクソスにつきましては、他区の導入実績としましては、千代田区、江東区等、２３区ではそのようなところで使っているのと、やはり音楽のデータベースについてのシェアというのも、こちらの会社が広く取っているです。","voiceIndex":68,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"それと、選書の件ですけれども、確かに大事だと思うのです。紙の現状の図書館でも、選書というのは現状ではどういう仕組みで誰が行っているのか。今回のこれからの電子図書館の選書についても、利用者ですとか住民の声が十分反映するような、ある意味、そういう選書の仕方の仕組みというのが必要だと思うのですけれども、そこら辺についてのお考えをお伺いします。","respondent":"吉田品川図書館長","answer":"２点ご質問いただきました。一度図書館に来ないとＩＤ・パスワードが交付できない。","voiceIndex":70,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"まだ導入段階なので、いろいろと費用の関係もあると思うので、分かりました。手続きについては、現在のところはそういう感じということで了解しました。選書の件ですが、最後にお伺いしたいのは、現状では誰がどういう形で決定するのか。そこら辺、誰がどういう形でいつ決めているのかということだけ最後にお聞かせください。","respondent":"吉田品川図書館長","answer":"指定管理者の中から、このような本の希望があるので入れてほしいというものが上がってまいります。それから、当然、品川図書館のほうでも全体を見ながら、こういうものを入れていくべきだろうというものを、またその意見を踏まえて調整いたします。","voiceIndex":72,"id":"exchange-030"},{"speaker":"芹澤副委員長","kind":"確認","question":"何点かお伺いしますが、まず、内容として、電子書籍を読む際に、いわゆる音声のサービス、アプリとかを通じて見るというものがあると思うのですけれども、今回の場合は、そこのサイトにアクセスをして書籍を見ていくということでいいのでしょうか。とりあえずまずそこまでお聞かせください。","respondent":"吉田品川図書館長","answer":"期間的なものは今簡単にご説明したような形になりますが、買取りのものも、どちらかというと、古い書籍については買い取って永続的に権利を持ち合わせるというものがありますけれども、比較的新しめのものにつきましては、先ほど申し上げたように。","voiceIndex":74,"id":"exchange-031"},{"speaker":"芹澤副委員長","kind":"提案","question":"図書カードをつくりに行くために来館する必要があるのか、図書カードを持っている人も、この申込みのために一回来館する必要があるのかという、図書カードをつくるには、多分、身分証とかの確認が必要なので、その来館はしようがないのかと思うのですけれども、持っている人は、ＩＤ・パスワード発行にもやはり来館の必要があるのかというのを教えていただきたいのと、あと、以前。","respondent":"吉田品川図書館長","answer":"通信料ほかのこと、３点ご質問いただきまして、ダウンロードできるかどうか、今後、そのような対応ができるかどうかは、相手側の業者との話になりますので、そちらは今後の研究材料とさせていただければと思います。","voiceIndex":76,"id":"exchange-032"}]},{"id":"topic-04","title":"の２のその他","agenda":"の２のその他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"その他で１点だけ。区立小学校の保護者の方から、４月に配られた年間スケジュールのところに、８月３１日と９月１日と９月２日がオリ・パラ観戦ということで書いてあって、始業式とかぶっているということで、どうなっているのでしょうかと。今現在どうなっていらっしゃるのか。児童・生徒や保護者には、どういう内容をどのように伝えていらっしゃるのか、お伺いしたいと思います。","respondent":"工藤指導課長","answer":"オリンピック・パラリンピック競技大会が開催され、応援観戦ができるという状況であれば、安全・安心に配慮しながら行うというところで学校にお伝えしていますし、学校からは、保護者等へ保護者会などを通じながら説明いただいているです。","voiceIndex":82,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり教育委員会として、子どもを観戦に連れていくことは中止をしていくという決断が必要かなと。オリンピックそのものも、私は一日も早く中止を決断して、感染対策に専念する必要があると思っているのですけれども、五輪そのものの開催の中止も教育委員会として申し入れていただきたいのですが、いかがでしょうか。矛盾しているのではないかと思うのですけれども、いかがでしょうか。","respondent":"工藤指導課長","answer":"オリンピック・パラリンピックの競技観戦等につきましては、オリンピック・パラリンピックが開催される、今その開催に向けて最大限安全・安心に配慮しながら、組織委員会も都教育委員会等も進めていると認識していますので、その中で私どもも。","voiceIndex":84,"id":"exchange-034"}]},{"id":"topic-05","title":"に戻りまして、(5)子ども若者応援フリースペースの移転","agenda":"に戻りまして、(5)子ども若者応援フリースペースの移転","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"移転の理由なのですけれども、資料に直接には賃貸借契約満了としか書かれていないのですが、契約は更新すればいいと思うのです。それと、フリースペース、現状のワンフロアから１階と２階で２つの部屋に分かれるということになりますと、やはり物理的に２つの目が必要といいますか、スタッフの配置増というのは必要だと思うのですけれども、今回、そうしたことは行われたのでしょうかというのが２つ目です。","respondent":"廣田子ども育成課長","answer":"場所が分かりづらいのは本当におっしゃるとおりでございまして、それについては、今度分かりやすい地図等も作成するとか、学習支援事業等もこれから６月、７月ぐらいから始まりますので、それまでにどのように分かりやすくしていくかについて今検討しています。","voiceIndex":91,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、いろいろな経緯があったとはいえ、スタッフ、逆に増えるということなので、やはり福祉は人ですし、そういう意味ではよかったかと思います。それと、場所の問題について、東急とかの力も借りて、これまで荏原方面から大井町線で下神明は一本で来られますので、下神明駅には少なくとも地図、案内板みたいな、そういった工夫もぜひしていただきたいと改めて要望しまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-036"},{"speaker":"あべ委員","kind":"質問・要望","question":"そこら辺、どのように把握されていますでしょうか。聞き落としたかもしれませんが、スタッフが何人から何人になるのかということも併せて教えていただきたいと思います。これ、大崎駅からが多分一番分かりやすいかと思うのですけれども、なぜか道がつながっていない地図になっていて、一応、確認させてください。きっと分かるようにするという意思はあるのですよね。よろしくお願いします。","respondent":"廣田子ども育成課長","answer":"引っ越しで、工事もほぼ内装は終わって、今防犯カメラをつけたりいろいろとやっているのですけれども、その中で案内をどうつけるかであるとか、また、フリースペースまでたどり着いても入り口が分からなかったりするため、まとめてサインについては検討しているので。","voiceIndex":94,"id":"exchange-037"},{"speaker":"あべ委員","kind":"質問","question":"もう一つ、以前、何かの質問のときにお願いしていたと思うのですが、活動内容を少し広げて、単なる居場所だけではない、ニーズに応じた活動をということもお願いしていたところですので、そうした意味でも少し展開が広がっていくのかと期待しています。それから、同じ場所になるぐんぐんスクール、キッズドアとのサービス、具体的にどう連携させるイメージを持っているのかを教えてください。","respondent":"廣田子ども育成課長","answer":"学習支援に来ていてさらにフリースペースもあるというところで、同じ建物でつなげるであるとか、こういう話を定期的に、この２つの運営者と区側と、状況によっては保健センターであるとか教育総合支援センターとの連携会議をつくっていくという。","voiceIndex":96,"id":"exchange-038"},{"speaker":"あべ委員","kind":"意見","question":"今後の展開は、通ってくる子どもたちの実態に合わせて、少しずつまたつくっていくのかと思います。中延のときより少し教育というワードが増えていくのかと思うのですけれども、それがプレッシャーになり過ぎないように運営していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-039"},{"speaker":"横山委員","kind":"質問","question":"お聞きしたいのですけれども、１階から４階のトイレの配置の状況はどのようになっているのでしょうか。教えてください。","respondent":"廣田子ども育成課長","answer":"ファミーユはもともと住宅だったので、トイレはついているのですけれども、１階にだれでもトイレを造りまして、間口も車椅子でも入れるような形で造っております。基本、各部屋に１つずつトイレがあるという形となっています。","voiceIndex":99,"id":"exchange-040"},{"speaker":"横山委員","kind":"質問","question":"１階にだれでもトイレで、また、各部屋に１つずつあるということで承知をいたしました。そして、私はトイレに生理用品をぜひ置いてほしいと思っているのですけれども、現在のフリースペースでの、そういった生理用品が必要なお子さんがいらしたときにどのようにされているのかという状況と、あと今後、移転後、どのようになるのかというところを教えてください。","respondent":"廣田子ども育成課長","answer":"今のフリースペースで生理用品を置いているかは分からないのですけれども、子ども家庭支援センター等と連携をしながら、必要があれば置くことは可能だと思ってあります。","voiceIndex":101,"id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"私が春の時点でフリースペースにヒアリングさせていただいたときに、トイレには置いていないけれども、もし必要な子がいたらお渡しできるようにはしていますと確認していたところなのですが、そういった形でもいいのですけれども、もし今後、だれでもトイレであったり、その年の子が使うような、しかも今度、ぐんぐんスクールですとか。","respondent":"廣田子ども育成課長","answer":"状況に合わせて検討していきたいと思います。","voiceIndex":103,"id":"exchange-042"}]},{"id":"topic-06","title":"子育て支援団体への助成","agenda":"子育て支援団体への助成","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"新しい支援がいろいろと誕生するところなのですけれども、まず、２番の育成支援助成、これはこれからつくる団体に対する支援に限られるのでしょうか。それから、前後しますけれども、開始時期とあるのは、これは申請受付開始時期という意味でよろしいのでしょうか。","respondent":"廣田子ども育成課長","answer":"説明会を求められていて、勉強会以外の場でもご要望があれば説明会を開こうと思っておりまして、順次、受付については随時お受けするという形で考えています。","voiceIndex":110,"id":"exchange-043"},{"speaker":"あべ委員","kind":"質問・要望","question":"６月９日の勉強会というのは、クローズドなものなのですか。それとも子育て支援に関心がある方、どうぞ皆さん寄ってみてくださいというものなのか。後者であれば、その内容などを教えていただきたいと思います。併せて３番のほうは、これは令和３年度から前期・後期の２回募集とありますけれども、同じ団体が前期・後期２回ということも可能なのでしょうか。","respondent":"廣田子ども育成課長","answer":"自主グループ支援のほうなのですけれども、同じ団体が２回まではできることにしているのですが、前期の申込みが実は５月でもう終わってしまっていて、後期は９月頃を予定しています。","voiceIndex":112,"id":"exchange-044"},{"speaker":"あべ委員","kind":"質問・要望","question":"そこはぜひ今後の検討課題にしていただきたいというのがあって、これについてもお考えをご答弁いただければと思います。それからもう一つ、新規の事業として、今回新規と拡充が出てきているのですけれども、これと反面で、なくなった事業というのはあるのでしょうか。その設計について教えてください。","respondent":"廣田子ども育成課長","answer":"この子育て支援の団体はどんな方々がいるのかというところ、どんな費用が要るのかというところを、今まだ聞き取りを続けておりまして、それを見ながら、今後必要な経費について、どんな出し方なら助成が可能なのかというのを今後検討していくので。","voiceIndex":114,"id":"exchange-045"},{"speaker":"安藤委員","kind":"意見","question":"１番の区内で子育て支援活動を行っている団体というところと、３番のお子さんを持つ保護者が会員となり学習を進めている団体というところですけれども、結構活動が行われているから、今回こういう助成制度ができるのかと思うのですが、区内でどれくらいあって、実際にどのような活動をされているのかというのをご紹介いただければと思います。","respondent":"廣田子ども育成課長","answer":"自主グループの支援の学習会については、お申込みがそんなに多くないので、今まで３か所、４か所ぐらいで、金額を少しずつ、１万円ぐらいずつ、どのぐらいだと使い勝手がいいのかと上げてきているところがあって、具体的に区内でどれだけというマックスは押さえていないので。","voiceIndex":116,"id":"exchange-046"},{"speaker":"横山委員","kind":"質問","question":"１点目なのですけれども、まず、こちら、いろいろと新規だったり拡充だったりということで、素晴らしいなと私は感じております。質問なのですけれども、まず１点目が、特に２番の新規の部分なのですけれども、成果というのはどのようにはかっていく予定になっていますでしょうか。教えてください。","respondent":"廣田子ども育成課長","answer":"説明会もするのですけれども、これ以外にもほかにもいろいろなご要望があって、制度とかが聞きたいとか、子ども家庭支援センターのことが聞きたいとか、そういうご要望をいただいているので、勉強会というか。","voiceIndex":118,"id":"exchange-047"},{"speaker":"横山委員","kind":"質問・要望","question":"これからどんどんそういった部分も進んでいくのかと思うのですけれども、なかなか中間支援というのですか、実際にお子さんとかお母さん方を支援したいという方は結構たくさんいらっしゃると思うのですが、そういったことを始めたい方とか、こういった支援の事業を継続するというのはすごく大変なことだと思いますので、各地域の事情に精通していたり、また、行政がやっている子育て政策を把握していて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-048"}]},{"id":"topic-07","title":"令和３年４月入園申込状況等","agenda":"令和３年４月入園申込状況等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今年の申込者数自体は１７５人減ったということですが、その理由についてどのように考えているのか伺いたいのと、それと、二次募集の結果が出た時点で予算特別委員会等で質問した際には、不承諾数が１,１７５人ということだったと思うのですけれども、今回の報告では９９６人ということで減っているのですが、これはなぜなのですか伺いたいと思います。","respondent":"立木保育課長","answer":"その前の年と比べると、今年は若干増となっておりますので、去年が比較的多かったということが一つあるというところはあります。それから、不承諾数が以前ご報告した数字から減っているところですが、こちら、辞退等があった関係で減っているものです。","voiceIndex":127,"id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"報道等では、やはりコロナの関係で保育園に預けるのは不安があるのだという方も若干増えているという話も報道されていたりするのですけれども、そういうのもやはり品川区も無縁ではないのではないかと思いますので、ぜひ保育園の従事者の方への定期的なＰＣＲ検査等を実施していただきたいと思うのですが、少しでも安心・安全に通えるような環境を整えていただきたいと思いますけれども、いかがでしょうか。","respondent":"立木保育課長、若生保育支援課長","answer":"保育現場へのＰＣＲ検査は、保健所ともお話をした上で、現時点では行っておりません。今後、情勢等が変わりましたら、きちんと見ながら対応することになるかと思います。現状としては以上です。順不同になってしまうのですけれども、求職活動をされていて、継続して利用申請が確認できない方、求職する書類のほうが確認できなかった等々で、継続的に求職活動をされているというのが確認できなかった方、こちらについては６６名。","voiceIndex":129,"id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、今、わざわざ具体的に聞かざるを得ないのは、不承諾者数の内訳を公表するようにと再三求めてきたのですけれども、今回、変わらなかったということで聞いているのです。報告や公表のあり方について、事業部として検討したのでしょうか。それとも、検討すらしなかったのか。そこら辺について併せて伺いたいと思います。","respondent":"若生保育支援課長、立木保育課長","answer":"こちら、昨年度までは、この育休延長希望者で、かつ１園希望者という方がいらっしゃった場合に、１園希望者のほうに計上していたというところでしたが、今年度は内訳を細かく拾ったため、育休延長希望者のほうが大幅に増えていると。補足ですが、育休希望の件に関しましては、申込みの段階で今回、令和３年の４月の申込みに当たり、育休を希望しているかどうかというところのチェックをつけていただくようにしました。そこが統計で拾えるようになったというところです。","voiceIndex":132,"id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、特定の保育園のみ希望している者ということで除外していますけれども、自宅からおおむね徒歩３０分以内で通える保育園を選んでいない方ということを除外しているということで間違いないのかということをお伺いします。それと、求職活動を休止している人も６６人いらっしゃるということでしたけれども、これは具体的にはどういうケースを指しているのかについても伺います。","respondent":"立木保育課長、若生保育支援課長","answer":"求職関係で６６名というような形でお答えしましたが、ハローワーク等に求職の申込みをしているという確認書類ですとか、あとは、令和３年５月の入園申込みを継続してされなかった方、そういった方が求職休止案件として、今回。国の基準等々の話で、自宅から３０分以内、これは通える範囲でというところがということですが、こちらについては、ご指摘のとおり、そういった基準で算出しているものです。","voiceIndex":135,"id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"ですから、こういう方々を、国の指針に従って唯々諾々と待機児童から外すという話は、それは保育行政を預かる行政としてどうなのかと。改めて、待機児童数５人という報告になったのですけれども、区はこの数字をどう評価しているのか伺いたいと思います。これから区としては、認可保育園を何園増やす考えなのでしょうか。それも伺いたいと思います。","respondent":"若生保育支援課長","answer":"今後の期中開設、今年の９月開設と、来年度の令和４年４月の開設、こちらの予定ですけれども、今、募集をかけているところでもありますが、それを含めますと５園を開設していく予定です。","voiceIndex":138,"id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後に質問とご要望ですけれども、待機児童数５名と言っているのですが、今年度の９園、今年の９月と来年を合わせて５園増やすということなのですけれども、なぜこれからこんなに増やすのでしょうか。なぜここまで増やそうとしているのか、理由を伺います。それと、これから５園増やす計画を持っているわけですから、私は、品川区の現在の待機児童数というのは実態に合わないと。これは要望です。","respondent":"若生保育支援課長","answer":"それ以外の３園というのは、これは子ども・子育て支援事業計画のほうでの人口増加の部分というところで当初から計画していた部分でございまして、コロナ禍で今、就学前人口が不透明な部分はありますけれども、今後若干増えていくというところも見込んで。","voiceIndex":140,"id":"exchange-054"},{"speaker":"あべ委員","kind":"質問・要望","question":"数字の数え方について教えていただきたいのですけれども、先ほどのご答弁の中で、登園可能な範囲で空きがあるのに希望していない方、３６８名という数字でよろしかったでしょうか。それは数字が合わないのではないでしょうか。それがみんな自分は空いているのに行かない人なのだというところにカウントされてしまうというのは、数字の処理の上ではおかしいのではないかと思うのですが、いかがでしょうか。","respondent":"立木保育課長","answer":"統計上の数値というところでは、確かに希望の園に入れないというところで申しますと、マッチングのところ、全てが認可保育園で、現在、品川区の待機児童対策をしておりませんので、いろいろな形態をご用意する中で、なかなか希望どおりのところに入れず。","voiceIndex":142,"id":"exchange-055"},{"speaker":"あべ委員","kind":"意見","question":"前半の空きがあるのに希望しているというところ、もう少し具体的に言うと、Ａという保育園に１人空きがあります。Ａ保育園には１個空きがあるわけですけれども、Ｂさん、Ｃさん、Ｄさん、Ｅさんの全員が入れるわけではないですよね。だけど、Ａに１個空きがあったら、このカウントの仕方では、ＢさんもＣさんもＤさんもＥさんも、空きがあるのに入れなかった人数にカウントされてしまいませんか。","respondent":"立木保育課長","answer":"算出している時点では、そのような形で順に算出しているものです。","voiceIndex":144,"id":"exchange-056"},{"speaker":"あべ委員","kind":"質問・要望","question":"とすると、３６８人以上の定員がこの人数で空きが現在あると考えていいのですか。だと数字が合わないと感じるのですけれども、これ、あまりやっていると長くなりますが、そのご説明だけではなかなか数字の納得がいかないと感じております。それから、そもそも片道３０分ということが現実的な通園範囲であるのかということも、やはり見直す必要があるのではないか。","respondent":"若生保育支援課長","answer":"片道３０分というところのカウントの仕方というか、範囲の決め方というところでいえば、先ほど委員おっしゃるところでいうと、３０分あれば区内どこでも通えてしまうというようなご指摘だったと思うのですが、ほかの自治体ですとか国の考え方というのは。","voiceIndex":146,"id":"exchange-057"},{"speaker":"あべ委員","kind":"質問・要望","question":"徒歩３０分だと、片道２ｋｍくらいでしょうか、品川区は縦横４ｋｍ四方ですから、やはりほとんどカバーしてしまうような形になってしまうのではないかと思いますけれども、そこら辺はここでの議論は控えますが、やはり現実的に通える、毎日荷物を持って、雨の日も通えるということを考えれば、やはり品川区としてどういう需要があるのかということを、厚労省の報告とは別に把握する必要があり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-058"},{"speaker":"横山委員","kind":"質問","question":"８ページの調整指数の１５番のところなのですけれども、今回、医師・看護師、プラス１点の加点というところで、数字も出てきているのかと思うのですが、加点、内定、それぞれどのような形になっているのでしょうか。何％ぐらい内定が決まったのか、教えていただけたらと思います。","respondent":"立木保育課長","answer":"こちらの１５番の加点について、医師・看護師の職に就いている方の加点の部分ですが、今回の令和３年４月の入園のお申込みの方で、加点対象となったのは１９９名です。そのうち内定が１６８名で、不承諾になりましたのが３１名ということになります。","voiceIndex":149,"id":"exchange-059"},{"speaker":"横山委員","kind":"確認","question":"今、数字を伺いまして、政策の効果がしっかりと出ているというところが確認できたかと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-060"},{"speaker":"あべ委員","kind":"質問・要望","question":"すみません。１つ聞き忘れていました。それで、今後の時期の見通しが分かればですけれども、それが１点と、それから、ご要望が多かったのは、やはり歯科医師の方と薬剤師の方が、コロナに直面している中で、私たちも入らないのかというお声をいただいていますが、その検討というのはされたのでしょうか。","respondent":"立木保育課長","answer":"今回、１９９名の方が加点対象になっているというところでは、これは拡大していくとさらに加点対象者が増えることから、他の方とのバランスもありますので、そういったところも含めまして、今のところは現行を引き続きと考えているところです。","voiceIndex":152,"id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5030#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":55712,"voices":155}},{"id":"r03-20210517-5","meetingId":"r03-cm05","date":"2021年5月17日","dateIso":"2021-05-17","committee":"総務委員会","time":"午後 １時００分～午後 ２時１５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"新型コロナウイルス感染症の対応","agenda":"新型コロナウイルス感染症の対応","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"その本部会議での話合いも踏まえて、関係機関に東京２０２０大会の開催中止を改めて求めるべきだと思いますが、いかがでしょうか。改めて本部会議の中で、オリンピック・パラリンピック中止を関係機関に求めることについて話し合われたことがあるのか、ぜひ話し合っていただいて中止を関係機関に求めるべきだと思いますが、いかがでしょうか。","respondent":"古巻総務課長","answer":"区におけます新型コロナウイルス感染症対策本部会議ですけれども、こちらは、例えば区有施設の状況の確認でありましたりとか、また様々な職員体制のことですとか、そういった区の動きに関してのいろいろな取決めといいましょうか、確認をするような場ですので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり品川区民の生命、財産を守るためにも、自治体として感染拡大が広がる中、開催中止を求めるべきだと思いますし、所管にその判断を委ねるのではなくて、対策本部会議で様々な角度からしっかり現状を確認した上で、区として、つまりは区長が関係機関に開催中止を求めるべきだと強く求めたいと思います。","respondent":"古巻総務課長","answer":"電話対応といいましょうか、電話がつながりにくい状況の回避でありますとか、スムーズな予約に対しての支援、こういったものについては十分に人も割きまして、電話回線も十分に確保した上で。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと同じ対応を区も考えているということなのか、その点を確認させてください。この間繰り返し述べてきたことではありますけれども、ワクチン接種と同時に必要な感染症対策も並行して進めていただくことを重ねてお願いしたいとともに、感染拡大が広がる中、東京２０２０大会開催の中止を関係機関に求めることを重ねて、これは要望させていただきたいと思います。質問のところだけお願いします。","respondent":"古巻総務課長","answer":"移動の支援については、まだ直接的に何かこう、タクシー券をというようなお話のところについても十分な検討はしておりませんし、できていない状況ではありますけれども、移動については会場の拡大等を含めまして。","voiceIndex":9,"id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"ただ、先ほどそのようなことがないように、回線や人員などを増やしてというお答えだったのですけれども、具体的にふだんはどれぐらいのところをどれくらい増やしたかというような、何か具体的に区としてこれだけの対応はしているということが、区民の皆様に私たちからもお答えできるような情報があるとありがたいのですが、その点についていかがでしょうか。","respondent":"古巻総務課長","answer":"ここについてはしっかり数字を、きちんと確認しますけれども、専用回線、専用のコールセンターがありますので、お待たせしないような対応をしていきたいというような形で対応させていただきたいと思います。","voiceIndex":12,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"そのようなことについて、これは対策本部会議とか、そのようなところの役割かなと思うのですけれども、国や東京都へのこちらからの体制を踏まえた、何か連携というか、ただ言われるだけではなく、何かそのようなことを、先ほど対策本部会議の議論についても質問がありましたけれども、その辺についてどのようになっているのかということを伺いたいと思います。いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません。どうしても重なってしまうところ、所管を超えてしまうところはあるかもしれませんけれども、昨年この新型コロナウイルス感染症のことが大変話題になったときに、生活者ネットワークとしては、まだまだ先の話ではあるが、やはりこのパンデミックというものは今後も起こり得ることで、そのようなときに必要になるのが過去の経験なわけです。これについて何かお考えがあれば伺いたいと思います。","respondent":"古巻総務課長","answer":"新型コロナウイルス感染症対策本部会議もそうですし、ワクチン接種に関する会議につきましても、記録については全部公文書として残しておりますので、直ちに今整理をしてというのはなかなか難しい状況ではありますけれども、ご指摘いただいたとおり。","voiceIndex":20,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"これ最後にします。この公文書として、記録としてきちんと残してほしい、今後に活かしてほしいという意見は、いつの委員会だったか、総括質疑のときに所管のほうに求めたのですけれども、意味を理解していただけなくて、やはりそれは対策本部とか、そのようなものをまとめている、この総務委員会の所管だと思います。これは要望にとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"突然国が出した大規模接種会場、これは私も寝耳に水だったのですけれども、このように同時に２つ行っていったら、両方予約していいわけですから、それも片一方予約して、どちらかにするならどちらかを断ってくれということも、どこかで区民に伝えなければいけないという、そのような難しさもあるし、そのような混乱をしないように、私は対応していただきたいと思います。相当区は大変だなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"所管から離れた話をして申し訳ございません。ぜひ検討していただきたいと思いますので、要望として終わりたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"そういった部分に関して、その拡充を今後考えていく部分で、周知の仕方といいますか、やはり少しでも近くで打ちたいという区民の方に対して、難しいとは思うのですけれども、何といえばいいのですか、どのようにうまく周知をしていくと混乱が起きないで、難しい話で申し訳ないのですが、混乱が起きないような周知の仕方という、何かそのような考え方というものはあるのでしょうか。","respondent":"古巻総務課長","answer":"会場拡大の周知でありますとか、様々なことについては、なるべく早く正確な情報をということになると思います。周知の仕方につきましては、十分に今いただいたご意見を所管にきちんとお伝えしまして、周知が進むような形で段取りをしていきたいなと思います。","voiceIndex":29,"id":"exchange-010"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"もう１点が、最新情報が見られるところとして、ふれあい掲示板に最新情報を掲示していただくのが、多くの区民の方の目に触れることになると思うのですけれども、ちょっと私の探し方が悪かったのか、区内にふれあい掲示板がどこにあるのかということをホームページから探してみると、その一覧表というものが、ホームページに出ているのかどうか、ちょっと教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-011"},{"speaker":"新妻副委員長","kind":"意見","question":"すみません。では、ぜひお願いをします。ワクチン接種のところに特別サイトができておりますので、最新情報はこの掲示板に、ふれあい掲示板に載せていますということも含めて、掲示板はここにあるのだということも含めて、ぜひ周知をお願いできればと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":36,"id":"exchange-012"}]},{"id":"topic-02","title":"新庁舎整備に関する検討状況","agenda":"新庁舎整備に関する検討状況","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"公募区民ですけれども、何人の応募があって結果４人になったのか、その申込みの件数を伺いたいと思います。そして、前回に続いてワークショップのことについて伺いたいのですけれども、前回伺ったときはまだ決まっていないということでありましたが、いよいよ第１回の日程が決まったので、ワークショップの概要について、その目的、メンバーの選び方、どの時点で開催をするのか、お伺いしたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"その中から４名を選んでおります。２点目のワークショップですが、こちら具体的にはまだ未定という形になっております。新型コロナウイルス感染症の状況を踏まえながら、ワークショップの時期、また対象、方法等を検討してまいります。","voiceIndex":43,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"しっかり区民の意見が反映できる仕組みにしていただきたいと思いますので、改めて伺いたいと思います。これでは実質審議が２回目と３回目の僅か２回でまとめに至るという流れになってしまうと思います。ぜひ回数を増やしていただきたいのと、テーマごとの分科会を設けてしっかりと議論を尽くすという進め方をしていただきたいと、重ねて求めたいと思いますが、いかがでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"は障害者の方の意見を聴く、また子どもたちの意見を聴くといったものが考えられますが、今後状況も踏まえながら検討していって、また基本構想や基本計画に役立たせるタイミングのほうを検討していきたいと考えています。","voiceIndex":45,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に要望ですけれども、この委員会で進め方やその詳細については確認されるものだと私も理解しておりますが、十分な議論を保障していただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-015"},{"speaker":"吉田委員","kind":"質問・要望","question":"基本構想案です、案だと思います。障害者の団体の中でああだこうだとなってしまうのは失礼なのですけれども、やはり、身体障害の車椅子ユーザーだったり、視覚障害だったり、聴覚障害だったりする方が、庁舎機能の中では一番直接的な影響が及ぶ方ではないかなと私は想像してしまうので、そのような方たちの中から、もう一人でも２人でも、別に参加を求めたらどうなのかなと思います。","respondent":"濱中庁舎計画担当課長","answer":"ワークショップも、もちろん区民意見を聴いた上で基本構想に活かしていくというものですが、まずは庁舎機能検討を昨年度やりましたので、そちらのほうをテーマに、ワークショップ等でもやらせていただくということは考えております。","voiceIndex":48,"id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"その事業者の中でそのようなことができる、得手とする方が、きちんと区から見えた形で、この人に任せておけば大丈夫というような人がいるのか、その辺については確認されたのでしょうか。ぜひその辺、やはりよい形の庁舎を目指すということで、そちらが当然主たる目的だと思いますので、もう少しきちんとスケジュールも見直していただきたいと思いますが、その点についていかがでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"時期につきましても、もちろんワークショップをやってその意見を反映していくのですが、計画段階での詳細な機能の考え方など、そういったものもありますので、計画に向けてのワークショップという形もありますので、そちらのほうもスケジュール等を検討しながら。","voiceIndex":50,"id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ具体的にどのようにして進めるかということも落とし込みながら、スケジュールをぜひ見直していただきたいと思います。やはり、今年度中に何としてもというか、そのように進めていくということが無理なのではないか、令和３年１１月頃までに基本構想案ができているということは難しいのではないかなと思います。ぜひ検討していただきたいと思います。もし何かご答弁いただけるようでしたら伺います。","respondent":"榎本総務部長","answer":"は去年１年間してきた、機能の検討をしてきたことに対しての説明を行い意見を求めた上で、それを基本構想のほうに活かしていきたいということが第１段階かと認識しています。","voiceIndex":52,"id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"ではこれで最後にします。やはり文章で出されても、それがその文章の読み込みだけではなかなか理解できないというところがあって、私たちも説明会を求めてまいりましたけれども、その答申についてご説明の予定があったということは大変評価をしたいと思います。ぜひそのように進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"これから本当に煮詰まっていくと思います。大変だと思いますが、ちょっと希望だけ申し上げますと、前にも言ったかもしれないですけれども、やはり職員の皆さんが働きやすい、そのような職場環境をつくっていただきたいということと、区民の方が分かりやすい、手続しやすい、相談しやすい、そのような構造にしてほしい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまり、質疑の中でだんだんワークショップの中身が説明されるのだけれども、初めは未定と言われてしまったから何も決まっていないのかと思いきや、ちょこちょこ決まっている部分もあって、伺いたいことは、このようにワークショップをやりますという概要をしっかりと、この総務委員会に報告をしていただきたいと思いますが、これは質問したいと思います。","respondent":"濱中庁舎計画担当課長","answer":"ワークショップですが、今内容、方法、時期等は検討しておりまして未定ですけれども、基本計画に活かしていくのであれば、パブリックコメント中に開催をしていくというような考え方もありますので、今後詰めてまいります。総務委員会にも適宜ご報告をします。","voiceIndex":57,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"これが最後です。意見だけです。現庁舎の課題をいつも防災だ、バリアフリーだと言いますけれども、結局今、区が進めているＤ案では超高層にならざるを得ないのです。やはり十分に課題も抽出し、それに見合った庁舎にするのであれば、時間をかけて議論すべきだと重ねて求めたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-022"}]},{"id":"topic-03","title":"東京都議会議員選挙（品川区選挙区）における執行要領","agenda":"東京都議会議員選挙（品川区選挙区）における執行要領","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それと２つ目は選挙公報の配布期限なのですけれども、７月３日土曜日までということで、投票日の前日までとなっておりますが、期日前投票の率も選挙のたびに増えてきておりますので、できるだけ早く、具体的に言えば印刷が終わり次第速やかに配布ができる体制を組むことが、有権者への投票に必要な情報を届ける選挙公報の役割だと思いますので、理屈上は前日までなのかもしれないけれども。","respondent":"齋藤選挙管理委員会事務局長","answer":"選挙公報につきましてはご指摘のとおりでありまして、７月３日までと、選挙の前日ということになっておりますけれども、委託をしておりますシルバー人材センターにお願いして、可能な限り全戸に早めに配布ということで、今回お願いしたいと考えています。","voiceIndex":64,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2196#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":25052,"voices":68}},{"id":"r03-20210520-14","meetingId":"r03-cm05","date":"2021年5月20日","dateIso":"2021-05-20","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 １時０５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6108#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":2149,"voices":11}},{"id":"r03-20210521-18","meetingId":"r03-cm05","date":"2021年5月21日","dateIso":"2021-05-21","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 １時２７分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"日本ブラインドサッカー協会とのパートナーシップ協定再締結","agenda":"日本ブラインドサッカー協会とのパートナーシップ協定再締結","exchanges":[{"speaker":"田中委員","kind":"確認","question":"１点確認したいのですけれども、以前荏原第六中学校でブラインドサッカーの練習があった際に、近隣からのお声があって、場所を移動せざるを得なくなったという経緯があったと思います。そのときに少し残念だなと思ったのが、先ほどの説明にもあったように、障害者理解の促進という部分が十分に図れなかった部分があるのではないかということを思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"いろいろな形を取りながら、さらに混ざり合う社会ができるというのが理想だというのはお互いの思いですので、その形で進めていきたいと考えています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"プレスリリースの下のほうに、「このような取り組みを全国に拡大したい」と理事長が語られたということですが、品川区以外にこうしたパートナーシップ協定を締結しているところはどこら辺があるのか、どれくらいあるのかというのを、もしご存じでしたら教えてください。そういったところと何らかの情報交換とか経験交流はされていらっしゃるのか、そちらも併せてお伺いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ブラインドサッカー協会は、企業のいろいろなところと一緒に連携して、いろいろなプログラム展開ということはやっているように聞いております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"こういった障害者スポーツを通しての相互理解、障害そのものの理解の促進というのは非常に重要だと思いますので、様々な横の連携なども、情報交換など、経験交流などもしながら、いろいろ地域にさらに広げていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"品川区は特別共催ということなのですけれども、特別共催の品川区としてはどのような役割を担っているのでしょうかというのが１点です。それと、コロナ感染を防ぐ対策はどのように行う計画なのか、教えてください。選手自身と、大会関係者、あと一部招待される観客の方もいらっしゃったと思いますけれども、それぞれについて伺えればと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"選手に関しては、練習会場が天王洲にあるのですけれども、ホテルと試合のピッチの往復のみで、ホテルのほうには協会が委託した健康管理の会社から保健師等を２４時間配置して、何かあったときにはそちらと連携をとる、受け入れの病院等も契約をしていると聞いております。","voiceIndex":14,"id":"exchange-004"}]},{"id":"topic-03","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"伺ったのですけれども、やはりこれから区に求めていくといった中で、このような文言が書かれているのはどうなのかと違和感を持ちますということと、あとちょっと違う視点になるのですけれども、(1)を「前向きになれるような情報発信を行うこと」とわざわざ書くことによって、議会は、区民が後ろ向きになっているということを感じ取っているのかということがやはり読み取れるということと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"前回も述べさせていただいたのですけれども、共産党としては今や第４波が深刻になっている状況を踏まえて、今年夏の大会開催は中止すべきだという立場ですけれども、開催そのものがやはり感染爆発の大きなリスクになり、医療への多大な負荷になるという点では、感染対策と両立できないことはもう明らかなのですから、一日も早く中止を決断して、コロナ対策に専念すべきだという立場には変わりはありませんが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-006"},{"speaker":"田中委員","kind":"意見","question":"このレガシー政策に関しても、(4)のところの「積極的に」の部分を、生活者ネットワークとしては削除してもいいのではないかという修正案を出させていただきました。なくても文章が通じるので、なくてもいいのではないかと思ったのですけれども、これに関しては、生活者ネットワークの修正案が反映されなかった理由についてお知らせいただけますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-007"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"先ほどの部分と今回の部分と一緒なのですが、田中委員から頂いた意見というものに対して、私たちもどのようにと（考えました）。ですから、生活者ネットワークの意見が通る・通らないというよりも、当然委員会としてもご報告を上げる中では、そこはしっかり正副委員長でも最大限のことをさせていただいたつもりなので、そこはご理解いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、これまでの議論に基づいてということだったのですけれども、これまでの議論の中でも、積極的に求める委員の意見とともに、やはり感染症が広がっている中で、今、やはり情報発信していくのは、区としては感染症に関する情報発信だといった区とのやり取りも議事録の中でも確認できていましたし、生活者ネットワークとしても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6594#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":8840,"voices":31}},{"id":"r03-20210526-10","meetingId":"r03-cm05","date":"2021年5月26日","dateIso":"2021-05-26","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時２１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議会構成等","agenda":"議会構成等","exchanges":[{"speaker":"松澤委員","kind":"質問・要望","question":"すみません。皆様、この場をお借りして、私、松澤和昌の会派変更について、ご報告します。自民・無所属・子ども未来を見解の違いから退会いたしまして、品川区議会自民党へ入会させていただきたいと考えております。自民・無所属・子ども未来の皆様には大変お世話になりました。私が委員としてここにいるのは違うと思いますので、これにて退出します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-001"}]},{"id":"topic-02","title":"常任・議運・特別委員会の構成","agenda":"常任・議運・特別委員会の構成","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"今の局長のご説明だと、資料No.１１に文教委員として松澤議員が入っています。確認ですが、この委員会については、会派は変わるので、第３会派はいらっしゃらないと。文教委員会の中にはいらっしゃらないということでよろしいですね。","respondent":"工藤区議会事務局長","answer":"名簿の順番につきましては、後で入れ替えしますが、当該委員につきましては変更ございません。以上です。","voiceIndex":20,"id":"exchange-002"}]},{"id":"topic-03","title":"附属機関等・各種団体評議員における議会選出委員","agenda":"附属機関等・各種団体評議員における議会選出委員","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"私どもはご辞退するというような形を取らせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-003"},{"speaker":"こんの委員","kind":"意見","question":"私どもからは、たけうち委員をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問・要望","question":"後ほど可及的速やかに報告をさせていただきたいと考えています。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-005"},{"speaker":"若林副委員長","kind":"確認","question":"本件について前回の委員会でご説明しましたが、同議会議員の選挙候補者届出期間の関係上、明日の臨時会で候補者を推薦する議案を議決する必要があります。本日は、前回、候補者が２名示されましたので、議案を提示するにあたり、各候補者の議案の提出者になるかどうか。各議案への態度を確認したいと考えております。自民党からよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"前回の議運でお話しさせていただきましたが、石田秀男議員で進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-007"},{"speaker":"こんの委員","kind":"意見","question":"会派としても検討いたしまして、石田秀男議員というところでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"皆様のご意見を伺いまして、この場では石田秀男議員が多数ということを受け止めさせていただきました。共産党としては、石田ちひろ議員を候補者とする議案をと前回説明いたしましたが、今日の議論も踏まえまして、石田秀男議員を候補者とする議案の提出者にはならず、議案には反対の立場をもって、石田ちひろ議員の議案は提出しないということでご対応いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-009"},{"speaker":"若林副委員長","kind":"確認","question":"石田秀男議員を候補者とする議案、また当議案の議事日程への追加につき、資料No.５の本会議運営案および資料No.７の追加議事日程の内容に変更が生じますので、それを反映した資料No.５－２および資料No.７－２も併せて配付しております。先ほど各会派の態度を確認いたしましたので、本案については、共産党などを除く議会運営委員会のメンバーを提出者とすることでよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-010"},{"speaker":"若林副委員長","kind":"提案","question":"さよう決定いたします。採決方法につきましては、起立採決でよろしくお願いいたします。本議案の提案説明は、私からでよろしいでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-011"},{"speaker":"若林副委員長","kind":"質問","question":"資料No.５－２の日程第１０の議案説明者に若林の記入と、採決については起立採決の記入をお願いします。","respondent":"工藤区議会事務局長","answer":"初めに資料No.９の鈴木真澄議員の選任同意で、区長からの説明の後、議場即決を行う予定です。それが終わりましたら、資料No.１０、横山由香理議員の選任同意です。同じく区長から説明の後に、議場即決する予定です。","voiceIndex":51,"id":"exchange-012"}]},{"id":"topic-04","title":"議事日程(1)、追加議事日程および追加議事日程(2)","agenda":"議事日程(1)、追加議事日程および追加議事日程(2)","exchanges":[{"speaker":"こんの委員","kind":"意見","question":"会派の態度を申し上げる前に、一言申し上げします。５月７日に役職届等を出すということで、一応一定のルールの下に出され、それ以降、様々な事情があって変更せざるを得ない。そうした議会運営の流れも踏まえ、会派として今回の議案について検討しました結果、会派から出されたそうしたものについて進めるということから、賛成としたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"意見","question":"こんの委員のおっしゃるとおり、円滑な議会運営に、そして事務局の皆さんに、この短い期間の中で、様々な資料の作り直しなど、本当に大変ご迷惑をおかけしたことを改めておわび申し上げます。ついては、横山議員の議案に賛成したいと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"それは受け止めさせていただきたいと思いますが、先ほどお話があったとおり、この間の流れというのは、やはり改善すべきところは改善していかなければいけないなと。ただ、それぞれ事情があることも理解したいとは思いますが、一言添えさせていただきたいと思います。態度といたしましては、第３会派ということで反対をするものではありませんので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-015"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回、監査委員の選任ですが、これはやはり品川区の財政に対して監査をするということですから、全会派一致でやはりきちんと推薦する、送り出すということが、私は建前だと思います。今この場においてどうするということについて、もう少し熟慮させていただきたいと思います。明日、明確に自分たちの意見、態度を表明したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5412#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":15915,"voices":104}},{"id":"r03-20210527-6","meetingId":"r03-cm05","date":"2021年5月27日","dateIso":"2021-05-27","committee":"区民委員会","time":"午前１０時０９分～午前１１時３６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第３１号議案、令和３年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第３１号議案、令和３年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"マイナンバーについてですけれども、マイナンバーカード申請件数の激増ということで、窓口を増やすということですけれども、激増の理由、その状況について、今、交付がどれぐらい進んでいて、申請がどれぐらいあるのかというのと、あと、増えている理由が何かというのを伺いたいと思います。","respondent":"木村戸籍住民課長","answer":"激増の理由ですけれども、まず一つは、昨年の１０万円の特別定額給付金の申請で、オンライン申請ということで、マイナンバーをお持ちであればすぐに申請ができますというところで、その段階で申請しようという方々が増えたということ、それから、これも国のほうで。","voiceIndex":6,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"交付会場ということで、申請もできる会場になるのか、交付だけの窓口、会場になるのかというのと、あと、新予約システムの導入というのがあるのですけれども、これはどういうものになるのか。今までがどういうもので、それがどうなるのか。配送管理の負荷を軽減できるということは、何をどうするとそうなるのかというのを詳しく教えていただきたいと思います。","respondent":"木村戸籍住民課長","answer":"キャンセルが出たときの、いわゆるキャンセル待ちの融通性みたいなところも今まで課題がございましたので、それも容易に、キャンセルをしたらそこへすぐ予約が入れられるようにという形で、すぐ対応ができるような形で考えています。","voiceIndex":8,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"それと、キャッシュレスのところなのですけれども、区内中小店舗でということなので、キャッシュレス決済のシステムがある店舗というのは、どれぐらいあるのでしょうか。結構あるのか、そこら辺を伺いたい。そこをお願いします。","respondent":"遠藤商業・ものづくり課長","answer":"今回やるに当たって、いろいろ業者からお話を伺ったり、検討させていただいたところで、どこの会社というのはお話しできないのですが、５,０００店舗あるというふうに、こちらのほうでは聞いているところです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、その５,０００店舗というのは、区内中小店舗の大体何％ぐらいになるのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"５,０００店舗の中で、区内中小企業の内訳については、この後、契約した後でないとなかなか教えられないというようなことを業者から言われておりますが、見込みとしては、大型店舗は数としては少ないかと考えていますので。","voiceIndex":12,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"キャッシュレス決済ができるシステム、機器というのですか。それを導入するのは、店舗負担になるのか。そこについて伺いたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"ただ、今、機器を導入する場合でも、無料のキャンペーンをやられている事業者もありますので、恐らくＱＲコードでと考えていますが、もう少し様子を見て、場合によっては違う方法でという形も余地を残しています。","voiceIndex":14,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"少し戻って、商店街の感染対策を取った店舗に、商店街単位で助成金ということなのですけれども、感染症対策事業は１５件を考えていて、住民生活サポート事業２件ということで、もしこれを超えてきた場合はどうなるのかというのと、あと、住民生活サポート事業で、先ほどＣＳＲの事業でやっているようなことを商店街がということですけれども、今まで商店街はこういうことをやっていなくて。","respondent":"遠藤商業・ものづくり課長","answer":"それを見込んで一応１５件という形でしていますので、足りるかと思っているところですが、もしオーバーした場合も、内部のほうで流用させていただいて、全ての商店街に助成をさせていただければと考えているところです。","voiceIndex":16,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"住民生活サポート事業は、地域見守り活動事業とか、地域清掃事業とか、交通マナー向上事業というのが例で書かれていますけれども、こういうことを商店街は今までやっていなかったのですか。新たに始めなくてはいけないというか、新たに始める商店街が多いのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"昨年、令和２年度はコロナの関係でなかなかできなかったので、申請はなかったのですが、おととしも２件ほど申請をいただいておりまして、そのときも清掃事業をやるとか、地域の子どもたちの見守り事業みたいなものをやるという形で２件いただいているところですので。","voiceIndex":18,"id":"exchange-007"},{"speaker":"松本委員","kind":"意見","question":"マイナンバーのところに絡みまして、会計年度任用職員増員ということで、１０名、結構大きく増員になっているのだけれども、これ、たまたまここに載っていて、これよりも前と人数がそんなに変わらないのか、純増なのかというところをお願いいたします。","respondent":"木村戸籍住民課長","answer":"基本的には純増という形です。","voiceIndex":20,"id":"exchange-008"},{"speaker":"松本委員","kind":"質問","question":"これもやはりこれまでよりも交付の規模を拡大するからという趣旨と受け止めてよろしいでしょうか。","respondent":"木村戸籍住民課長","answer":"その趣旨です。","voiceIndex":22,"id":"exchange-009"},{"speaker":"松本委員","kind":"意見","question":"これ、もともと東京都が去年ぐらいずっと似たようなことをやられていたのかと思うのですけれども、多分、東京都の１００％負担でやっていた、商店街に対する感染症対策事業と今回の、東京都から助成は出ているけれども、区の負担も出ているという、この事業の切り分けについて、まだ理解できていない部分があるので、お願いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"今回、多分、そちらの部分を一旦やめてといいますか、ある程度整ったという状況なのか分からないですが、まだやれていないとか、追加でというところとか、今回改めてやりたいというところの部分で、区が幾ら都が幾らというパターンのものが結構多くありますので。","voiceIndex":24,"id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"これは言い方は悪いですけれども、都が１００％やっていたものを、区の財政で一部負担するというので、ある種、東京都がやっていたものを、特別区に対して押しつけているようにも思えるのですけれども、その辺りというのは、所管というか、また別かもしれませんけれども、都と区のやり取りの間で、都でやってくださいというふうな、これは区も関与するとなると。","respondent":"遠藤商業・ものづくり課長","answer":"東京都でも、近いような形でやっている状況がありましたので、今回、区としてはどうしようかと、別の部分の支援でと考えたところなのですが、東京都のほうでこういう補助メニューを用意しましたと。","voiceIndex":26,"id":"exchange-011"},{"speaker":"松本委員","kind":"意見","question":"厚労省とかＷＨＯでは、効果があるかと言われたら、明確にあるとは言えないと。場合によっては、物によっては、例えば皮膚に接触して炎症が起こるというものもあり得るという報道等もある中で、消毒液等の中に空間除菌に関するものが含まれ得るのかどうか、お願いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"効果が認められないものは難しいかです。","voiceIndex":28,"id":"exchange-012"},{"speaker":"大倉委員","kind":"質問・要望","question":"マイナンバーカード交付強化について、土曜交付窓口開設と、荏原第一地域センター、目黒行政サービスコーナーが増えることで、どのぐらいの件数が処理できるようになるのかという数を教えていただきたいので、お願いします。","respondent":"木村戸籍住民課長","answer":"現在は月間で約６,０００件交付の能力、これが土曜日と２か所拡大して約１万２,０００件という、倍の交付能力という形で運用してまいりたいと考えております。","voiceIndex":30,"id":"exchange-013"},{"speaker":"大倉委員","kind":"確認","question":"商店街の地域力向上事業のところで、新メニューで感染症対策事業ということで、今も松本委員の質問の中に、さらに追加の部分で活用していってもらいたいということで、今まで使っていたところもまた使えるのかという確認と、消耗品購入のところで、総額１０万円までということで、それについての考え方、今まで多分品川区として。","respondent":"遠藤商業・ものづくり課長","answer":"感染症対策事業は５０万円というところですけれども、６０万円買って５０万円が最大の補助という形になりますので、使う分だけご購入いただければ、それに合った補助率という形で支給をする予定です。","voiceIndex":32,"id":"exchange-014"},{"speaker":"大倉委員","kind":"質問","question":"品川区でやると、より補助が減ってしまうというところでは、この感染症の１０万円というのはしようがないということで分かりました。いろいろあるではないですか。いろいろな企業でＱＲコード決済をやっていて、どの事業者を選ぶとか、１社に決めていくのか、それとも何社か選んでやられるのか、どのような検討がされているのでしょうかというところを教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"この還元額５億円を有効に使うという観点から、一応１社でどこかの事業者でやらせていただければと考えているところです。","voiceIndex":34,"id":"exchange-015"},{"speaker":"大倉委員","kind":"質問","question":"１社でやると、その１社のＱＲコード決済ができる何かアプリとかをダウンロードして使っていくという認識でいいですか。","respondent":"遠藤商業・ものづくり課長","answer":"そのように考えてあります。","voiceIndex":36,"id":"exchange-016"},{"speaker":"大倉委員","kind":"意見","question":"いろいろな方が利用しやすいというところでは、使っている事業者が決まっていたりする方がいると、なかなかいろいろな方が使うというところでは、１社というよりも２社３社というのもあるのかと思ったのですが、一方で、何社もあると、そのアプリを片っ端からダウンロードして、１人で何回も使えてしまうというところもあるのかという懸念はあったので、１社ということで分かりました。理解しました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-017"},{"speaker":"くにば委員","kind":"質問","question":"最初に、キャッシュレス決済ポイント還元事業の部分なのですけれども、１点目が、今、大倉委員から質問がありましたが、キャッシュレス決済事業者、１社とのご答弁でした。これ、複数の事業者にしたほうが、当然、ユーザー側からは利便性が高いと思います。それを複数にできない理由というのが、何かあるのかどうかをまず伺いたいのですが。","respondent":"遠藤商業・ものづくり課長","answer":"私ども、産業振興というところがありまして、デジタルのところで、今まで導入していないところもあろうかと思いますので、取りあえず１社で試しで今回の３０％のポイント還元でやっていただこうという考えがあったのが一つと、それから。","voiceIndex":39,"id":"exchange-018"},{"speaker":"くにば委員","kind":"質問","question":"それこそ駄菓子屋で、全くキャッシュレスが分からないわというおばあちゃんのお店でも、このＱＲコードを読んで決済してねということで、お店側の負担とかシステムに対する理解が何もなくてもできるようなシステム、それがＱＲコードを店頭に置いたものを読み込むというメリットだと思うのですけれども、これは５,０００店というところと関係なく、もっと広げてできるのではないかと思うのですが。","respondent":"遠藤商業・ものづくり課長","answer":"本当は非接触の、いわゆる交通系のＩＣだとかというところもあるかと思いますけれども、導入に関して新たなものをいろいろと設置しなければいけないというところがありますので、まずは電子のキャッシュレスというものに慣れていただくため。","voiceIndex":41,"id":"exchange-019"},{"speaker":"くにば委員","kind":"質問","question":"もう一点、細かい部分なのですが、これ、上限１回２,０００円、期間内１万円までということで、１日で、例えば、１つの店舗で３万円分買うと、９,０００円分ポイントがつきます。１回で２,０００円、逆算すると、６,０００円購入すれば１,８００円まではつくから、６,０００円を５回に分けて買うみたいな形で、同一店舗で同じ日に５回買物をしても問題がないというような説明になるのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"私どもがお話ししている事業者ですと、それができてしまうというところがありますので、期間内の上限が１万円という形で設定させていただいて、両方の部分で歯止めをかけて、１人頭につきましてここまでという形で考えているところです。","voiceIndex":43,"id":"exchange-020"},{"speaker":"くにば委員","kind":"質問・要望","question":"今おっしゃった中では、結局は１店舗で同じ日に５回買物をしても問題がないという形の説明はあらかじめしておくのでしょうか。今おっしゃった形で、結局できてしまうという部分、ここをどこまで制限をするのかというのを教えていただきたいのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"実際の事業者がどうなるかというところもあろうかと思いますけれども、今お話ししているところでは、そういう縛りができないというところがあるので、そのようにしていただくのは、うちのほうの趣旨からすると、どうかというところはあるのですけれども。","voiceIndex":45,"id":"exchange-021"},{"speaker":"くにば委員","kind":"質問","question":"プレミアム付区内共通商品券、紙のほうに移りますけれども、これ、いつも実施するときに、１人当たり最大幾らまで申込みができるという形で書いてあったと思うのですけれども、今回、１人当たりのマックスが書いていなかったのですが、これに関してどのような予定なのか、伺います。","respondent":"遠藤商業・ものづくり課長","answer":"まだ商店街連合会と詰めているところではないのですが、これまで１０冊までという形でやっております。今回、１０％の商品券については８冊までという形になりますが、恐らくは８冊か１０冊かという形になろうかと思っているところです。","voiceIndex":47,"id":"exchange-022"},{"speaker":"くにば委員","kind":"質問","question":"こちら、結局、春の分の区内商品券がコロナの再拡大で中止になったような、たしか意味合い的にはそんな形だったような気がするのですけれども、そこに関して、もしまた８月、実際に販売期間が９月下旬または１０月上旬、この辺りにもう一度コロナの状況が変わっていった場合に、人流を抑制するという意味合い、あまりお店にたくさん買物に行ってと言えないような状況になったときに。","respondent":"遠藤商業・ものづくり課長","answer":"ですので、秋はまた秋でそのまま、今回のスキームの中で実施させていただいて、また今回、秋のほうでキャッシュレスと紙と両方やっていくところですので、また新たな消費喚起策が必要だということであれば、この方法か、あるいは別の方法。","voiceIndex":49,"id":"exchange-023"},{"speaker":"くにば委員","kind":"質問","question":"なので、春は申し込んだけれども、申し訳ないのですけれども今回取りやめではなく、あくまで販売がもう少し後の時期になります、延期になります、まだ未定ですという段階なのでしょうか。なので、恐らく同様に、今回申し込んだけれども、結局、お流れになってしまったのだと感じている区民の方もいらっしゃると思うのですが、そこに対して細かい周知であるとか、説明の部分とか、もう一度伺いたいのですが。","respondent":"遠藤商業・ものづくり課長","answer":"この後、一旦、皆さんのほうにはがき、あるいはメールで、販売は延期しますのでと。当初、５月の中旬にやる形だったのが、緊急事態宣言で少し遅れますというようなご案内をさせていただいて、恐らく６月に販売を開始する形になります。","voiceIndex":51,"id":"exchange-024"},{"speaker":"くにば委員","kind":"意見","question":"ということは、実際、春のプレミアム分１０％申し込んだ人も、まだ結局、お金を払っていません。そのお金を払っていない段階で、次、２０％のものをやりますということになったら、１０％のもののお金を払うのを取り消して、２０％のものを申し込んだほうがいいということになるような気がするのですけれども、そこに関して何か事前に検討というのは。","respondent":"遠藤商業・ものづくり課長","answer":"ただ、２０％のほうがまた抽せんという形になり、今回の分がまた買えるというわけではないので、１０％のほうはできれば１０％で夏の期間使っていただいて、秋は秋でまた申し込んでいただくというので、私どもは考えているところです。","voiceIndex":53,"id":"exchange-025"},{"speaker":"くにば委員","kind":"質問・要望","question":"そこの部分、区民の方々も含めて、今回の２０％のプレミアム分の商品券と両方が誤解がないように、消費者の方に分かりやすく申込みをしていただけるよう、もしくはキャンセルをしたらどうなるかであるとか、分かりやすく伝えていただけるようにお願いしたいと思うのが、それは希望というか、要望で終わります。それがまだ設置をしていない事業者の、例えば、アクリル板は物理的に店が狭いし置けないと。","respondent":"遠藤商業・ものづくり課長","answer":"感染症部門ではないので、積極的にやりなさいというのはなかなか難しいところです。ただ、そういう部分で、個店につきましては、新型コロナウイルス対応の、個店宛ての２０万円の助成という部分をやらせていただいたところです。","voiceIndex":55,"id":"exchange-026"},{"speaker":"くにば委員","kind":"質問","question":"先ほどのマスク、消毒液等という中にそういうものも含まれる、その中できちんと感染症対策になっているというもの、それを判断した上で買っていただいているというところで、今、例えば、等間隔に人を並ばせるために、ソーシャルディスタンスを保つために並んでもらうためのカラーコーンがこの中の範囲に入るというのを聞いて、意外とびっくりしたのですけれども、ちなみにカラーコーンというのは。","respondent":"遠藤商業・ものづくり課長","answer":"ガイドラインのほうを詳しく確認していないところですけれども、今回のこちらの助成金の要綱の中に、そういう部分での具体的な例として、カラーコーンみたいなものも入っているので、恐らく入っているのかと思っているところです。","voiceIndex":57,"id":"exchange-027"},{"speaker":"くにば委員","kind":"質問・要望","question":"こういった類いの補助金のときに私よく申し上げるのですれども、どういうものが実際使えますというのは、たくさんメニューを並べていただいたほうが事業者も分かりやすいし、これはオーケーなのだというのでどんどん活用していただけると思うので、具体的な例示というのをたくさんしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-028"},{"speaker":"小芝委員","kind":"確認","question":"商店街地域力向上事業について、確認というか、お聞きしたいのですけれども、地域の商店街を歩いていますと、相談を受けるもので圧倒的に多いのが、都の時短要請に基づく感染防止の協力金だとか、あと、次に多い相談が区独自の販路拡大の、この感染症対策事業に近いものなのですけれども、そういうところで、今回の商店街を対象にした感染症対策事業というところで。","respondent":"遠藤商業・ものづくり課長","answer":"その方に対してこれをお送りして、商店街の中で周知なり、あるいは使う使わないみたいな判断をしていただくという形を取っているところであります。ですので、個別の店舗に送るということは今のところないという形です。","voiceIndex":60,"id":"exchange-029"},{"speaker":"小芝委員","kind":"質問・要望","question":"かなりそれまでに日数がかかったという声も聞いておりましたので、その辺、ぜひ今回の事業について対応していただきたいと思うのですけれども、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"今回のこちらにつきましては、商店街という形で、これ以外にも、例えば、装飾灯の電気代の補助ですと、ほとんどの商店街がやられて、そういう部分でいろいろな形で慣れていらっしゃるところが多くありますので、そういう部分では。","voiceIndex":62,"id":"exchange-030"},{"speaker":"小芝委員","kind":"質問・要望","question":"このコロナの状況でなかなかお店も開けないという大変厳しい状況ですので、ぜひともきめ細かにフォローしていただきたいと強くお願いしまして、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"プレミアム付区内商品券についてお尋ねしますが、前々回に１０％のプレミアム率で商品券を出しますというときの私とのやり取りは忘れていないと思うのですけれども、そのときに課長言いましたよね。プレミアム率が、前にやったときに、３０％でしたか。時期がこれだけの期間で、もう２０％に変わってしまったのですか。やはり２０％、１年２年たっていないではないですか。その辺について説明してください。","respondent":"遠藤商業・ものづくり課長","answer":"前々回の区民委員会のところで、１０％のご説明をさせていただいたところです。","voiceIndex":65,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"期間内１万円まででしょう。次出るのが２０％でしょう。消費者としては、今さら変えられないといっても、２０％のほうがいいではないですか。ずっと緊急経済対策というので１０年ぐらいはやっているかもしれませんけれども、今回コロナ禍ということで、本当に特別なことになっていますので、やはりこのプレミアム率というのをもっと考えていっていただきたいと思うのです。","respondent":"遠藤商業・ものづくり課長","answer":"１０％の部分につきましても、春の１０％という形で、結果としては多分少なく見えるのかというところがあるかと思いますので、内部と、あるいは商店街連合会といろいろと、買う側と売る側とまたいろいろ意見が違う部分があろうかと思いますので。","voiceIndex":67,"id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういう補正予算は、今回直接的にはないということなのですけれども、今後、本当に緊急事態宣言が延長されて、それで先の見通しのない中で、中小業者や飲食店などは、それこそ借り入れるという借金は難しいわけで、東京都の協力金しか今頼るものがなく、それも１月の申込みのものがいまだに出ていないという状況で、本当に生き残れるかどうなのかという苦しい状況にあると思うのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"経済が疲弊している中での直接支援というお話かと思います。区の財源というところで直接支援をやるとなると、相当な金額がかかるのかというところがありまして、昨年ですと、家賃支援の上乗せ助成という形での対応をさせていただいたところです。","voiceIndex":69,"id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういう意味では、自宅の家賃とお店の家賃という両方がかかってしまっている事業主の方などは、本当に手が回らないという状況で、大家とも相談しているという状況もあるのですけれども、区に今必要なのはそうした直接支援なのではないかと私は思いますので、そこはぜひ拡大、充実、復活等々していただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-035"},{"speaker":"つる副委員長","kind":"提案","question":"商品券のところで幾つか確認したいと思います。今の各委員の質疑も伺っていて分かったところもありますが、今年の予算特別委員会の総括質疑で私のほうからも、東京都の予算を活用して、まさにこの生活応援事業を活用して区内経済の活性化を図るべきだということで提案をさせていただいて、それを区として都の予算を活用していただいたことは大いに歓迎して、推進をしていきたいと考えています。","respondent":"遠藤商業・ものづくり課長","answer":"新規の店舗のところですけれども、当然、今回の私どもの事業によって、新たに加盟しようと、やっていこうという方も増えていくだろうと考えていますので、区のほうでは、店舗宛ての説明会といいますか、新規の加入についての説明会みたいなもの。","voiceIndex":72,"id":"exchange-036"},{"speaker":"つる副委員長","kind":"質問・要望","question":"春の分については、販売が１か月、後ろになったわけだから、使用期間も確実に１か月ずれるのかと思うのですけれども、ただ、この商品券に既に記載されてしまっているという理解でいるのですが、その使用期限をどう考えるかというのも併せて伺いたいのと、販売が１か月遅れるのだから、利用できる期間も１か月、それに応じてずらすという考えが一般的かと思うのですが、その確認と、そうなってくると。","respondent":"遠藤商業・ものづくり課長","answer":"恐らく商品券のほうも、既に印字が済んでいるところがありますので、そこはこちらから販売の際にいろいろな形で、書いてありますけれども１か月延びるのです、使う店舗のほうにも、これは１か月延びているという形で。","voiceIndex":74,"id":"exchange-037"},{"speaker":"つる副委員長","kind":"質問・要望","question":"券そのものは、１０％分で使います、２０％分で使いますではなくて、販売のときに枚数が増えるのですよね。当然、状況に応じて、そういう財調の活用だとか、都の予算だとか、国から来たものとか、今後そういう経済支援とかが出てきたときには、今回のように積極的に活用していくという区の姿勢を、また今後も示していただきたいと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-038"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"マイナンバーについては、私たち共産党は、安全性が確保されていない下での推進はすべきでないと反対をしてきているものですけれども、今後もマイナンバーカードにおいては、健康保険証と結びつけたり、将来的には運転免許証や学生証、在留カードとの一体化も進めると。さらには、銀行口座や国税、年金とひもづけすることも考えられています。そして、さらに拡充、拡大していっていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2898#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":29427,"voices":90}},{"id":"r03-20210527-7","meetingId":"r03-cm05","date":"2021年5月27日","dateIso":"2021-05-27","committee":"厚生委員会","time":"午前１０時０９分～午前１１時１２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第３１号議案、令和３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第３１号議案、令和３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"今後も、せっかくこの補正予算で実ったものを枯らさないように、続けていっていただきたいと思っているのですけれども、こういう方針で今後もやっていくように考えられているという理解でよろしいのでしょうかというのが、第１点です。その辺のことを教えていただきたいと、まず思います。いかがでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"施設のほうでも、週１回の検査が正直、ご自身の業務との兼ね合いで負担になっているという声も我々のほうに届いておりますので、そういった声も大切にしながら、今後検討していくものと考えております。","voiceIndex":8,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"移動支援についてもお伺いしたいと思います。しかも、そのような制度にしても、莫大な額がかかるわけではないのですから、限られた人数の方にやるわけですし、タクシー代も品川区内での話ですから、そういうことをご検討していただければよかったのにと私などは思うのですけれども、そういう検討はなされなかったのかということを、まず第１点、伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"６月１日から北品川クリニックが開くということと、以前の厚生委員会でもご説明していますが、スクエア荏原も６月中旬から開設という形で、会場の確保は引き続き努めておりますので、その辺り、ご承知おきいただければと考えております。","voiceIndex":10,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"後で後悔するわけです。大井競馬場なんて、どこにあるのか知らないし、区で車でも用意してくれるのかと、抗議のファクスでも区に送ろうかというように、非常に怒っていらっしゃるわけですけれども、そういう説明なりを、何とか予約の申込みをされている方に、このようにしたらいいのですよという説明、情報の提供というのは、何とかできないものですか。その辺のご説明をお願いいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"コールセンターの件につきましては、お電話があった時点での空いている会場をご案内するということで、こちらからもお願いしているところでございまして、空いていない会場へは、さすがにご案内することができないということと。","voiceIndex":12,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今のに引き続いて、タクシーのところについてお伺いしたいのですけれども、私どもは要望をさせていただいていましたので、大変ありがたいなと思うのですが、タクシーを使うことを認めるというか、推奨するとまではいかないまでも、やむを得ずタクシーで移動される方がいらっしゃるから、こういう制度をされるということなのですが、いろいろな意見をいただいているのですけれども。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"お迎えにつきましては、今いただいたご意見を基に、急いで検討させていただきたいと考えております。","voiceIndex":14,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そういうことを考えたときに、高齢者の方の移動を考えると、会場が現状として、なかなか厳しい状況にあるというところで、先ほどおくの委員の質問であったのですけれども、北品川クリニックの話は今初めて伺ったのですが、もう少し教えていただけることが、週に何回やるのかとか、そのことについて教えていただきたいことが一つと、北品川の方からも、これは皆さんも聞いていると思うのですけれども。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"６月中に何とか開けるように、医師会の皆様も急いでやってくださってはいるのですが、いかんせん、まだ医療従事者の方が終わっていないということもありまして、なかなか区民の皆様を安全にお迎えできる状態にはなっていないというところから。","voiceIndex":16,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"委員長がおっしゃったようなことも伺っていますし、今、ぎりぎりの調整をされていることも、よく分かっていますけれども、地域ごとのことについても、ぜひよろしくお願いします。個別接種会場については、ぱらぱらと出てくる感じなのか、それともまとめてお考えになっているのか、この辺りのお考えについて、今言っていただけることを、いただける範囲で教えていただければと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"基本的には、一括してというか、ある程度まとめて公表できるような形で準備を進めているところです。","voiceIndex":19,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点だけ要望なのですが、個別接種会場でやっている自治体がたくさんあって、予約方法で混乱が生じているという報道もありますので、そこについては、一括がいいのか、それとも病院ごとがいいのか、幸いというか、幸か不幸か、そういう先行事例を見ていただいて、一番混乱のない方法でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ＰＣＲ検査ですけれども、６月末までに実施で２回分ということですので、６月に２回行うという考え方でしょうか。２週間に一遍ということなのか、その確認をお願いしたいと思います。それで、その２回というのは、なぜ２回なのかということと、それから、６月以後についてはどういう方向なのか、その点についてもお聞かせいただきたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"回数についてですが、委員がおっしゃったように、東京都が６月末までを今回の補助の対象としている関係で、こちらも２回という回数を設定しています。ただ、東京都もこの先について、全く予定がないということではないと。要は、これを延長する考えはあるやに聞いております。","voiceIndex":22,"id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"地域密着型の２９ベッド以下の特養ホーム以外の特養ホームとか、老健施設とか、特定施設とかは、直接東京都とやり取りをしながら、既にＰＣＲ検査を行っていると思うのですけれども、そこのところでどれぐらいＰＣＲ検査を行っているのかということについては、把握をされているのでしょうか。把握しているということであれば、そこの中身についてもお知らせいただきたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"こちらも東京都の補助事業で、都のスキームに従って行われているものですので、こちらは特段、把握はしておりません。ただ、東京都がこれをやるとなったときに、積極的にこれを活用するようにという要請は、各施設・事業所に出させていただいているところです。","voiceIndex":24,"id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう点では、どこでやっているのかということも、区としてぜひ把握していただきたいと思いますし、東京都が６月で終わりでなく検討しているということですけれども、そういうところでは、ぜひ６月以降もやっていただくように、東京都にも求めていただきたいと思いますし、区としても積極的に行っていただくように要望をしておきたいと思います。","respondent":"松山障害者福祉課長","answer":"受入対象者ですけれども、特にこの指定管理者の福栄会とは、まだそこまで細かく詰めているわけではございませんけれども、実際問題、受け入れるときに、最初、福栄会からは、児童も受け入れるという答えをいただいているのですけれども。","voiceIndex":26,"id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この高齢者のほうは、要支援・要介護の認定者の方ということで、その人数だと思うのですけれども、障害者の方の場合は５,０００人ということですが、この５,０００人という方は、多分、手帳を持っていらっしゃる方ということになると、もっとたくさんいらっしゃると思うのですけれども、障害者の対象をどういう形で５,０００人という人数にしているのかについて、伺いたいと思います。","respondent":"松山障害者福祉課長、宮尾高齢者福祉課長","answer":"ワクチン接種会場への移動が困難な障害者の方ということで、今回新たに想定させていただきましたのが、身体障害者手帳のうち。この商品券の事業の形ができて、お伝えするようになったところで、関係する機関には速やかにご案内をさせていただきたいと考えています。障害福祉の分野も同様に、地域拠点相談支援センターと連絡を取りながら、障害福祉サービスのメニューで、今後ですけれども。","voiceIndex":28,"id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今の障害者の５,０００人の対象ですが、視覚障害３級までということだと、今言われたところは、福祉タクシー券の配付の方と対象がほとんどかぶっていると思うのですけれども、福祉タクシー券の利用対象の方にプラスして、視覚障害３級の方は対象になっていないのですけれども、そこに視覚障害３級の方がプラスされたという形で考えればいいということでしょうか。精神の方も。","respondent":"松山障害者福祉課長","answer":"ただし前提として、高齢者や精神の方と重複している方もいらっしゃいますので、数字としては５,０００人ということで、大きく概算で見込んでいる次第です。","voiceIndex":32,"id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう対象もきめ細やかに検討していただいて、よかったなと思っています。６月１日から予約が始まって、接種がいつから始まるのか教えていただきたいのと、そういう情報をすごく地域の方が求めていまして、お聞かせいただきたいと思います。それから、６月半ばからは、スクエア荏原でも始まるということですけれども、スクエア荏原の予約はいつから始まるのかということもお聞かせいただきたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"一応、今週の火曜日に両医師会の皆様を区役所にお招きしまして、説明会を行いまして、それの第２弾として、もっと細かいお話と、病院名の公表等々について最後の調整を行って、どのように皆様に公表していくかということを決めていく予定になっておりますので、そこについては。","voiceIndex":34,"id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その後、様子を見なくてはいけなかったりとか、そういう点では、人員体制もつくってやらなくてはいけないということになっていくと思うのですけれども、そうすると、それに対してのコストもかかるようになってくると思うのですが、そういうコストも、国ではまだしっかりとできていないということで伺ったのですけれども、そういうところでは、区として巡回または往診で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"確認","question":"２つお尋ねします。もう一つは、国から７月末までに高齢者のワクチン接種をという話があって、区としては、やれますという回答をしたとお聞きしているのですが、まだ始まったばかりで、何ともあれだと思うのですが、現在の状況から、国の回答との感じはどういう感じになっているのでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"６月も順次予約枠を空けられるような、もっと増やせるような、今の会場で予約枠を増やせるような調整を現在進めているところですので、現時点では７月末の完了を目指して、各種調整を進めさせていただいているところです。","voiceIndex":41,"id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"移動支援のほう、共通商品券の配付については、介護サービスに従事されている方や、いろいろな方も、当事者の方にご説明できるように、何度も繰り返しますけれども、いいことをされているわけですから、ご本人に伝わるようにしてください。７月末までいろいろ大変かと思います。時間外勤務も多いと思いますが、ぜひ実現するように進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-016"},{"speaker":"西村委員","kind":"質問・要望","question":"福祉サービス従事者の方のＰＣＲ検査ですけれども、介護現場の方から、課題は特になく、大変ありがたいとの声をいただいておりまして、今、高齢者の方のワクチン接種の予約を、多くのケアマネジャーとか従事者の方がサポートしてくださっているのが現実で、疲弊した介護現場の方々への支援につながっていると感じるのですけれども、一方で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3596#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":19918,"voices":57}},{"id":"r03-20210527-9","meetingId":"r03-cm05","date":"2021年5月27日","dateIso":"2021-05-27","committee":"文教委員会","time":"午前１０時０９分～午前１１時４３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第３２号議案、専決処分の承認を求めること","agenda":"第３２号議案、専決処分の承認を求めること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"申請が必要な年金受給者、家計急変者へ給付金を支給したということなのですが、今のところ何名に支給したのでしょうかというのと、それと前回の質疑で、申請が必要な方にはやはり周知を徹底ということで、私も含めて各委員の意見も出されたと思うのですが、具体的にはチラシですとかポスターとか、いわゆるどのような工夫をしたのかというのを教えていただければと思います。","respondent":"伊東子育て応援課長","answer":"それとご案内につきましては、５月６日の時点で案内を送付ということですけれども、該当しそうだという方、資格がありそうだという方に対しては、その中でダイレクトにご案内をしたという状況です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"それと、私が伺ったのは、広報、ホームページはもちろんですけれども、案内の送付というのは、去年の実績にある方に送付ということは前回も伺いましたけれども、それ以外の方、例えば新たに今年度、この１年間でさらにその後急変した人とか、あと去年は申請が漏れてしまった方とか、そういう意味ではそれ以外の方への広報という意味で、例えば生活保護の窓口ですとか、暮らし・しごと応援センターですとか。","respondent":"伊東子育て応援課長","answer":"これからの見込みですけれども、当然ながら家計急変等で申請ができるということで、数値的には上がってくるという見込みになっております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"何かいろいろと工夫されて、可能性のある方にはかなり前回の実績を超えて案内を送っているということだとは思うのですが、それでもやはり漏れる方はいらっしゃると思うので、ＳＮＳとか、あとチラシやポスターといってもそれほどかしこまったものでなくてもいいですから、簡易なものでもいいので、とにかく作って早めに大きく知らせていくということはぜひ工夫していただいて、やはり受けられるのだけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"あべ委員","kind":"質問・要望","question":"数字等を確認させていただきたいのですけれども、２２世帯３７人分、これは支給が終わった数と受け止めていいのでしょうか。支給の手続きには至っていないけれども、これは児童扶養手当以外の方で、年金受給者とか家計急変者の中で、既にどのくらい、何世帯何人分の申請が出てきているかというのは、現段階で把握されていますでしょうか。","respondent":"伊東子育て応援課長","answer":"それと、もともとの児童扶養手当の受給者というところで、１０件１９名分が同日５月２６日の時点で支給されております。トータル２２件で３７名分というような形です。","voiceIndex":10,"id":"exchange-004"},{"speaker":"あべ委員","kind":"質問","question":"すみません、質問の趣旨と違ったと思うのですけれども、私が伺ったのは、５月２６日に支給された方、支給まで手続きが終わった方は２２世帯３７人分ということだと思うのですが、申請が出てきてある程度まとまったところで支給日に間に合うところが支給になっていると思うのです。","respondent":"伊東子育て応援課長","answer":"支出に関しては、一定程度こちらの想定としては月１回ぐらい支出していこうと思っているところですので、申請が上がって処理が終われば、大体その月末ぐらいには支給していくというようなことです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"あべ委員","kind":"質問・要望","question":"それだけ上がってきて、現段階での支給数というのはかなり少ないなという印象になっています。そうした意味では、申請数にもう少しアンテナを立てていただきたいと思うのですが、いかがでしょうか。それからもう一つ、７３９件のご案内をダイレクトで送付したということですけれども、この該当しそうな人というのはどういう基準で選んでいらっしゃるのですか、教えてください。","respondent":"伊東子育て応援課長","answer":"それは今後その都度状況を把握していきたいと考えていますけれども、いずれにしても５月の分は時間がなかったので確かに少ないのですが、今後はもっと数字的には、次回辺りは結構数字が上がってくるかと考えています。","voiceIndex":14,"id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"７３９件の内訳、大体分かりました。これは、昨年のひとり親世帯の給付で年金受給のために児童扶養手当がない方と、それから家計急変者、これで合わせて６００人弱、五百何十人。この方々には送っていらっしゃるのですか。それともこの方々というのは既に、当然に受給対象になっているということなのでしょうか。","respondent":"伊東子育て応援課長","answer":"もともとの大きなところというのは児童扶養手当、令和３年４月の児童扶養手当の受給者というところがこの給付金の対象です。","voiceIndex":16,"id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"今の説明はあまりよくわからなかったのですけれども、つまり昨年度に家計急変と年金受給の枠で給付がされた方にはダイレクトで通知を行っているということなのか、別にその枠組みでは行っていないということなのか、どちらなのでしょうかという趣旨の質問です。それはお分かりですか。","respondent":"伊東子育て応援課長","answer":"それを含めて行っているということです。","voiceIndex":18,"id":"exchange-008"},{"speaker":"芹澤副委員長","kind":"確認","question":"２点だけ確認をしたいのですけれども、これは手続き的には案内を送付して支給されるまで、大体間に７日間ぐらいということなので、その支給までの手続きというのはそこまで難しくないということでいいのでしょうか。併せて先ほどのご答弁の中で、月１回の支給日ということでお話があったと思うのですけれども、そうすると、５月２６日のが終わったので、次の支給が６月末頃になるということでいいでしょうか。","respondent":"伊東子育て応援課長","answer":"支給までの手続きですけれども、申請が上がってまいりまして、それであといろいろ所得要件が該当かどうかという判断が必要になりますので、書類審査の時間がかかります。","voiceIndex":21,"id":"exchange-009"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"生活が急変した方々への支給ということなので、なるべく早く支給できればという思いがあるので、ぜひ月２回とか、できればで結構ですけれども、前向きに早く支給できるような体制の整備というのを検討いただければと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-010"}]},{"id":"topic-02","title":"第３１号議案、令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第３１号議案、令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"一時たしかあまりなかなかできないという中で緊急事態が続いておりますが、何とかもっと開催してもらいたいという思いでのこういうものなのかどうなのか、その辺の目的、それで結果的に緊急事態宣言がまた延長されたりして、なかなか開けない場合には、これは来年の３月に申請なので、実績分のものに対しての補助なので分からないですけれども、子ども食堂によっては全くほぼできなかったというところは。","respondent":"伊東子育て応援課長","answer":"今回の補正は、その他世帯分ということで、先行して実施しましたひとり親世帯の部分とは対象は別となります。ひとり親世帯分でもらった子どもさんに関してはもう対象外という形になります。","voiceIndex":39,"id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問・要望","question":"分かりました。特別給付金については、その人数がはっきりとまだどうなるかというのは分からないということなのでしょう。だから補正予算も必要だということでいいのでしょうか。それから、この補正予算のタイミングについては分かりました。ただ、減少傾向ではあるという見方でいいのか、それとも横ばいなのか、クラスターはないけれども増えているのか、その辺のところだけちょっと教えてください。","respondent":"立木保育課長、伊東子育て応援課長","answer":"ただ、感染の予防も徹底されてきたところもありますので、大きく広がるということは、今のところないと認識をしています。通常開催しているところもあるのですけれども、現状では開催していない、やっていく予定というようなところも含めて１５か所になった次第です。","voiceIndex":44,"id":"exchange-012"},{"speaker":"たけうち委員","kind":"質問・要望","question":"感染対策費を５,０００円上乗せして、金額の増額をしてこういう補正を組むということは、区としてはこの子ども食堂が子どもたちのいろいろな孤立化とか、今コロナでなかなか大変な思いをしている子どもたち、なおかつ今まで子ども食堂に来ているような子どもたちは比較的そういう孤立しがちな中で、でもそこも休まれていると大変だという思いの中で、少しでもこの感染対策をしていただきながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-013"},{"speaker":"あべ委員","kind":"質問・要望","question":"２０歳未満の障害のある児童も対象になってくるということなのですけれども、この場合の障害のある児童というのは、要は手帳を持っている２０歳未満の児童と言ったらいいのか、１９歳だと若干児童からずれてきますけれども、要は手帳の有無が境目になってくるのかどうかということを確認させてください。","respondent":"伊東子育て応援課長","answer":"それと障害、これは特別児童扶養手当を受給していますので、その支給対象というのが愛の手帳の１から３とか、身体障害の１から３とありますので、それに合致していればそちらのほうの対象になってくるです。","voiceIndex":50,"id":"exchange-014"},{"speaker":"あべ委員","kind":"確認","question":"ということは、高校生のみというのは高校生相当年齢ということで、高校に在学しているかどうかではなくて１８歳まで、その部分が対象になるということでよろしいでしょうか。高校に在学しているかどうかはこの際関係ないということで、確認させていただければと思います。それから、障害のあるお子さんについては、家計状況に関係なくいろいろ……、両方かかってくるのか。確認させてください。","respondent":"伊東子育て応援課長","answer":"高校生というところですが、いわゆる１８歳ですので、高校生限定という話ではございません。一応国のほうの記載が高校生となってしまったということです。それと、特別児童扶養手当のことに関しては、２０歳未満ということです。","voiceIndex":52,"id":"exchange-015"},{"speaker":"あべ委員","kind":"質問","question":"特別児童扶養手当は１８歳未満ではなかったでしたか。あれは違うのですか、あれは２０歳未満でしたか。そうしたらなぜ2)でさらに取り出す必要があるのでしょうか。特別児童扶養手当が支給されている以外の２０歳未満の障害のある児童というのは、これは所得要件がかかってくるのですか、こないのですか。そうすると2)で特出しする必要はあるのでしょうか。私は分からないから聞いているのですけれども。","respondent":"伊東子育て応援課長","answer":"特別児童扶養手当の該当ということであれば２０歳未満という形ですので、それはいいのですけれども、所得要件、非課税要件がありますので、もともとの1)というのは年度末に１８歳までの子ということですので、そこは分けて書かれていると、対象者にしているです。","voiceIndex":54,"id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"子ども食堂のさっきのご答弁と私が認識している数字は若干ずれがあったのですけれども、開催状況については時々で変わるものだと思いますのでそれはそれといたしまして、子ども食堂と配食の両方をやっている場合にはどういう扱いになるのかということと、それから子ども食堂を開催している場合、これは感染症対策が上乗せされますけれども、この中には消耗品だけではなくて備品購入なども。","respondent":"伊東子育て応援課長","answer":"対象経費というところでは、食材費、会場使用料、光熱水費、保険料、消耗品費、配送料、感染症対策費ということでくくられてありますので、備品というか感染症対策としての備品ということであれば当然に認められると認識をしています。","voiceIndex":56,"id":"exchange-017"},{"speaker":"あべ委員","kind":"確認","question":"1)、2)は足してカウントしていいということですね。それから、感染症対策については、お金は出るけれども、まず１年間はちょっと前払い、自腹でやってくださいねという仕組みであるということを確認させていただきました。","respondent":"立木保育課長、若生保育支援課長","answer":"今年度４月以降の数字となりますが、職員、園児とそのご家族からは、３１件ほど陽性の方が出ています。休園になったところですけれども、私立保育園のほうが４月・５月で３園ございました。それから、私立幼稚園につきましては２園ございました。","voiceIndex":58,"id":"exchange-018"},{"speaker":"あべ委員","kind":"質問","question":"本年度に入って４月・５月、２か月足らずの間で結構あるのだなとは感じております。職員、園児、家族の中で、公立保育園の場合は３１件ということですが、これはそれぞれ陽性になった方が登園自粛だったり、職員の場合には一定期間出勤しない状態にしてということなのでしょうか。濃厚接触者の取り方というのは今どうなっているのかということを、併せて教えてください。いかがでしょうか。","respondent":"立木保育課長","answer":"公立のほうが割合としては高いのではないかということですけれども、これはたまたまと言いますかそういったことで、先ほどの内数で言いますと保護者が２２名、職員が２名、園児が７名という割合になっていますので、子どもの中での感染というよりは。","voiceIndex":61,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"子育て世帯生活支援特別給付金ですが、生活保護受給世帯の方は対象になるのかということと、もし対象になる場合、収入認定はされないということでよろしいのでしょうかということを確認させていただきたいと思います。補助を受けた場合は本人の自己負担はほぼなくなるのか。昨年も実施された事業ということですが、実績は何件くらいあったのかを伺いたいと思います。","respondent":"伊東子育て応援課長、若生保育支援課長","answer":"生活保護受給者の件ですけれども、この支給の対象にはなります。対象になるとともに、要件を満たしているかどうかというのがあるところです。それと、収入認定に関しては、収入認定しない扱いということで聞いてあります。そういった観点から負担割合としましては、東京都の設定、これは補助上限が２,２５０円ということになりますので、おおむね１時間１５０円プラスちょっと高いところをお願いした場合は若干足が出てしまう部分がありますけれども。","voiceIndex":63,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"こちらはちょっとお考えをお伺いしたいと思います。なぜそういう予算を今回組まないのか、伺いたいと思います。今回は学校教育部署の方がいないのでそちらに聞くのですけれども、区内の保育園のオリンピック・パラリンピック観戦の計画というのは現在どうなっているのかということと、あと、これは中止すべきなのではないかという点についてお考えを伺いたいと思います。","respondent":"初貝保育教育運営担当課長、伊東子育て応援課長","answer":"オリンピックの保育園児の観戦に関しましては、現在中止等々というところは決定しておりませんで、その辺り、今のところ予定どおり考えていくというところではありますが、状況を逐一確認しながら、また。併せてチラシ的なものも作るという話もありますので、その辺を総合的に考えまして、ひとり親の部分もありますので、今後考えていこうと考えています。","voiceIndex":66,"id":"exchange-021"},{"speaker":"安藤委員","kind":"提案","question":"給付金のほうについてです。やはり保育従事者の実態と声をつかんで、保育課として安全・安心の保育業務のために定期的なＰＣＲ検査実施の要望というのを、今回予算に入っていませんけれども、もう早期に区にも上げていくし、所管としてそれこそが今一番求められている対策ですよというところで予算化を求めていただきたいと思いますが、そこについてももう一度最後にお伺いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"オリンピックに関しては、先ほどの委員長の仕切りも私はちょっと納得できません。それほど質疑を絞る必要はあるのかと思っています。それをしっかりと把握して、それでクラスターの発生を防ぐということが目的なので、そういう様子見に陥らず、ぜひそこには確信を持っていただいて、保育現場の方々の声も聞いて、これは早期に予算化していただきたいと、これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-023"},{"speaker":"横山委員","kind":"確認","question":"低所得の子育て世帯に対する子育て世帯生活支援特別給付金の支給についてなのですけれども、こちらはスケジュールのほうで、７月下旬に、高校生のみ養育、新たに出生した世帯等への案内を送付とあるのですけれども、こちらは恐らく夏休みに入ると給食等がなくなって、低所得の子育て世帯の方々は食費の辺りとかをすごく心配なさっているかと思うのですが。","respondent":"伊東子育て応援課長、若生保育支援課長","answer":"スケジュールの部分ですが、どうしても先行して直接給付する部分の作業が６月以降に入ってくるという中では、それを先行させまして、その後に抽出しまして発送というような形で、結果的にはその申請をいただくということになりますので。コロナに関する臨時休園等の支援事業で、認証保育所、ベビーシッター等の利用支援事業の継続に関して、昨年度との変更点というところですけれども、特段都からの支援スキームにつきましては変更ございませんので。","voiceIndex":74,"id":"exchange-024"},{"speaker":"横山委員","kind":"質問・要望","question":"子ども食堂についてなのですけれども、こちらは子ども食堂の主体的な活動かと思うのですが、ただ、全体の地域バランスを見ていただきながら、いつどこで開催しているのかみたいなところを区のほうでも確認ですとか状況把握をしていただいて、少し手薄なエリア、ちょっとこの時期ここがちょっとみたいなところがあったときに。","respondent":"伊東子育て応援課長","answer":"子ども食堂のネットワーク事務局がありますので、その中でいろいろと意見交換をしつつ、地域バランス等を考えて要請的な話をしていこうと思っています。","voiceIndex":77,"id":"exchange-025"},{"speaker":"せお委員","kind":"質問","question":"ちょっと１点だけすごく細かいところで申し訳ないのですけれども、保育所等における感染拡大防止対策補助金なのですけれども、マスクや消毒液等の物品購入とあるのですが、そこは３０万円なり５０万円なり、その範囲でどうぞというか事業所が物品の内容を決めるのか、それとも区からこのようなものが対象ですとかが示されているのでしょうか。そこら辺を教えてください。","respondent":"若生保育支援課長","answer":"こちらの物品購入につきましては、事業者あるいは園が独自に選んでいただいて購入したものの費用をご提出いただいて、区のほうで後でお支払いするというような形になってあります。","voiceIndex":79,"id":"exchange-026"},{"speaker":"せお委員","kind":"質問","question":"それは小学校に上がったときにそうだからという流れで教育のところもあるのです。だから、多分年長児も今はやっていないので、小学校ではペーパータオルにする予定はないそうなので、そこの流れのところとか、今後どういった教育面での指導につながっていくのか。先ほど聞いたのは私立のほうもそうで、ペーパータオルとかを勧めているのか、そこのところを教えていただけたらと思います。","respondent":"初貝保育教育運営担当課長、若生保育支援課長","answer":"年長の園児に関しては、教育面で自分のハンカチをというところもあるのですけれども、一方で感染症に関して、現状ですと安全第一というところで、ペーパータオルを使うことで一定防げている部分があると考えておりますが。私立の園につきましては、区で特にペーパータオルを勧めるといったことではなく、各私立の特性ですとか状況に合わせて、ペーパータオルのほうも購入する際の補助金に活用できますということで。","voiceIndex":81,"id":"exchange-027"},{"speaker":"せお委員","kind":"質問・要望","question":"先生によっては、まだ自分のタオルを持ってきてポケットに入れていたりするのです。だから何かそこを統一するなり、あとはもうやはり先ほどご答弁にもありましたけれども、今後を見据えていろいろと検討していただきたいと要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-028"},{"speaker":"安藤委員","kind":"意見","question":"賛成ですけれども、一言言いますが、この当委員会所管の予算としてはすべて国と都の補助事業なのです。ただ、計上された事業というのは全部コロナ禍で苦しむ区民の支援にとっては本当に大切な事業ですので、賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":90,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5032#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":26517,"voices":98}},{"id":"r03-20210527-5","meetingId":"r03-cm05","date":"2021年5月27日","dateIso":"2021-05-27","committee":"総務委員会","time":"午前１０時０９分～午後 １時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第３３号議案、専決処分の承認を求めること","agenda":"第３３号議案、専決処分の承認を求めること","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"何点か伺いたいのですけれども、品川区に聞くことではないのですが、国が年度ぎりぎりの段階での公布、年度始めの施行としたのは、一体どういう事情があるのか、どのような説明を受けているのか、その点は、ご説明いただきたいと思います。３点目は、区にとっては税収が減るということになるわけですけれども、幾ら減るのか、その穴埋めは、誰がどう行うのか、３点まとめて伺いたいと思います。","respondent":"提坂税務課長","answer":"対象台数ですけれども、令和２年度の環境性能割の実績額が、金額的に言いますと７９１万円ほどで、台数的には約４００台ということで、令和３年度の予算額についても７８０万円で４１０台の見込みです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"吉田委員","kind":"意見","question":"賛成します。一言だけ意見を申し述べしますが、やはり現在の方向性としては賛成なのですけれども、専決処分となってしまったということについては、なるべく専決処分は避けるべきではないかという立場をとっております。ただ、今のご説明だと、今回についてはやむを得ないと考えますので、賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"区役所でも今週からでしょうか、ｉＰａｄを使って、ガラケーの方にも申請ができるようなことを行っていると伺っておりますけれども、６月からは６５歳以上の方の受付も始まりますので、やはり受付体制の強化が必要だと思います。そこで、受付電話は、現在５０台稼働していると伺っておりますが、これをさらに拡大していただきたい。こうした補正予算を直ちに組むべきだと思いますけれども、いかがでしょうか。","respondent":"黒田財政課長","answer":"いわゆるワクチン接種の予約の関係ですが、現在、７５歳以上の方の接種が開始されておりまして、６５歳以上の方につきましては、予約開始が６月８日からという予定です。","voiceIndex":20,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"インターネットでの申請も支援していただきたいと強く要望したいと思います。既に７５歳以上の方で、２回目の接種の予約が７月末だという方がいらっしゃいました。やはり都と同じく週１回にすべきではないのか伺いたいと思います。そして、７月以降もしっかり定期的に検査を行う必要があると思いますが、お考えを伺いたいと思います。","respondent":"黒田財政課長","answer":"補正予算を編成したときには、５月末まで緊急事態宣言という中で、現時点では、まずしっかり、入所施設については東京都が対応しますので、東京都が対応しないところについては区が対応していくというところで、２回の予算を計上しているところでございまして。","voiceIndex":22,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"ＰＣＲ検査のことですけれども、今、都の補正のスキームが６月末までということで、７月以降は、補正をまた組んでくるのではないかというご説明で分かりましたけれども、ぜひ障害者、高齢者施設で働く従業員に定期的に週１回のＰＣＲ検査を強く求めたいと思います。国および東京都に、東京２０２０大会の中止を求めていただきたいと改めて思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり外からの持ち込みを防ぐというのであれば、新規入所者、利用者には、しっかりＰＣＲ検査を行うと、この立場を感染が抑制するまで、しっかりと位置づけていただきたいと要望したいと思います。最後に、補償の問題です。つまりは、地域経済を回すためにも、事業所の固定費、家賃や人件費の直接支援、これをしっかりと打ち出していくことが、いよいよもって必要だと思いますが、最後にいかがでしょうか。","respondent":"黒田財政課長","answer":"区としては、今回、補正予算に計上していますプレミアム付区内共通商品券でありますとか、キャッシュレス決済ポイントなどを活用して、区内経済の消費喚起の一助になればというところで予算を計上しておりますので。","voiceIndex":28,"id":"exchange-006"},{"speaker":"吉田委員","kind":"確認","question":"その趣旨は、やっぱり急速に所得が下がった方というのがコロナの影響により出ていますので、既に児童扶養手当とかをもらっている方は、自分たちが対象になるということも自動的に知ることができるのかなと思うのですけれども、そうでない、この今の大変な状況のときに、急にそういうことが必要になったという方へのお知らせというか、この制度の利用の仕方の案内というか。","respondent":"黒田財政課長","answer":"今回の補正予算に計上しています低所得の子育て世帯に対する特別給付金につきましては、令和３年４月の児童手当または特別の扶養手当が支給されている方は、特段申請がなくても、住民税が非課税である方、判定が必要になりますが。","voiceIndex":30,"id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひその辺を丁寧にしていただきたいなというふうに思っております。私はぜひ補正を組むときに、全体的にそういうことをきちんと検証することを求めていただきたいと思うのですが、いかがでしょうか。だけど、その対策が、有効でないような対策で済んでしまっているのであれば、私は、感染を広げることになるので適切ではないと思うのですが、その辺の検証を、区としてどのようにお考えか伺いたいと思います。","respondent":"黒田財政課長","answer":"特に商店街にぎわい創出の地域力向上事業の感染症の事業ですが、これは東京都の補助事業を活用しておりますので、東京都の要綱を見ますと、商店街自らが感染拡大防止ライン等に基づく取組を行う事業で、趣旨に合う事業については補助対象となるというふうにしておりますので。","voiceIndex":32,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"ちょっと１つ訂正というか、銘柄指定をしろとかということを言っているわけではなくて、やっぱり有効な成分のものの購入に使ってくださいという、そういう検証をしてほしいですという意味ですので、ちょっとそれだけ訂正しておきます。これは強く要望しておきます。これも、最後、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"１点目なのですが、２１ページに、予防接種費に交通費助成があります。これについては、見解だけお聞かせ願いたいのですが、今、高齢者の方は、出歩くのが怖い、そして足腰等身体的に弱られている方が多いということで、かかりつけ医、身近なところで予防接種できるように、区として、今、積極的に進めるような対応はお考えなのかどうか、お聞きしたいと思います。お店に行ってもらいたくても行けない。","respondent":"黒田財政課長","answer":"２点目の共通商品券のところですが、今回の補正予算では、秋の商品券につきましては、当初予算では、発行額４億円というところについては、補正予算で５億円という形で発行総額を増額しまして、プレミアム率も１０％から２０％に上げておりますし。","voiceIndex":35,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"どうしても国が主導で動いて、混乱を招いて、それが東京都、そして各自治体、品川区にも、あれやれ、これやれ、でも、どうやって動いていいか、もう混乱をしていると思います。本当に上がしっかりしていれば、そういうことはなかったと思うのですが、最善の注意と、そして、区民に対する配慮をしていただいて、できるだけ多くの区民を助けていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-011"},{"speaker":"湯澤委員","kind":"質問・要望","question":"この間、私も品川区の公式ＬＩＮＥに登録をしておりましたところ、５月１９日でしょうか、マイナンバーカードにかかわる会計年度任用職員の募集というのが来まして、そちらのほうをちょっとお聞きしたいのですけれども、やっぱり今までは国からデータが自治体のほうにおりてきて、またそれがすごいたまってしまったりして、大分時間がかかっていたかと思うのですけれども、この職員を採用することによって。","respondent":"黒田財政課長","answer":"交付率ですが、現在、４月末現在で、約３１％の交付率となっておりまして、国の目標としては、令和４年度末に、ほとんどの国民にマイナンバーカードを行き渡らせるというのを目標として掲げておりますので、そういったところにも鑑みながら。","voiceIndex":38,"id":"exchange-012"},{"speaker":"湯澤委員","kind":"質問・要望","question":"本当にコロナ禍においては、手続を簡素化して、スムーズに区民の方々に、いろいろそういう交付するものとか、そういったものがスムーズにいくように、スピード感を持ってできるようにということでありますので、ぜひ区民の方々の生活や申請がスムーズにできて、サービスが向上するように努めていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それとあともう１つは、待ち時間、今、密の状態にならないよう、１席ずつ置いていると思うのですけれども、待っている時間に、シティプロモーション、とにかく品川区もシティプロモーションをやっているので、デジタルサイネージとか、そういうものを置いて、お待ちなっている時間を、少しでも区をもっともっと知ってもらいたいという意味合いでも、そういう宣伝効果といいますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-014"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。今回、補正予算を組んでいただきまして、これまで公明党が要望してまいりましたワクチン接種会場への移動支援、またはキャッシュレス決済ポイント等も予算化がされました。これから６５歳以上ということで、また拡充をされると、その時点でまた少し混乱が起きるのかなという心配をしておりますので、そこら辺の体制への取り組みもお願いしたいと思います。","respondent":"黒田財政課長","answer":"ワクチン接種のほうにつきましては、高齢者の接種については、７月末までの接種を目指しているというところで、国を挙げて取り組んでいるところですので、区といたしましても、所管が、特に医師会と調整しながら、個別接種も含めて。","voiceIndex":42,"id":"exchange-015"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"商品券、やはりプレミアムが付くということで、待ち望んでいる方が、声が多くありましたので、周知も含めて、混乱が起きないように、また丁寧に周知もしていただきたいと思いますが、緊急事態宣言もまた延びるというような報道もある中ではありますけれども、できる限りの対応をしていただきまして、早めに、また春の商品券の販売をぜひ進めていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-016"},{"speaker":"中塚委員","kind":"提案","question":"意見を述べたのち、態度を述べたいと思います。個人情報を一括化し、個人情報を危険にさらすこうした制度は普及すべきでないということは述べさせていただきたいと思います。款別審査での提案、総合審査での提案もぜひ受け止めていただき、一層の対策強化を求めたいと思います。よって、補正予算の態度としては、総合的に判断し、賛成したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からも、少しだけ意見を述べします。ぜひ感染拡大という視点からも、保育従事者、教員へのＰＣＲ検査の拡大は、今後の補正で計上していただきたいというふうに思います。あわせまして、先ほど申しましたように、この事業が有効に使われるような広報と、それから、その後の検証についてはやっていただきたいという要望を付け加えて賛成といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-018"}]},{"id":"topic-02","title":"委員長報告","agenda":"委員長報告","exchanges":[{"speaker":"新妻副委員長","kind":"質問・要望","question":"この１年間、理事者の皆様、そして委員の皆様、そして事務局の書記のお二人の皆様にお世話になりました。区民の皆様が、情報をどうやって取ればいいのか、品川区のサービスは何なのかということを求めているのだなということを非常に感じました。この１年間、大変にありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2198#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":19998,"voices":57}},{"id":"r03-20210527-10","meetingId":"r03-cm05","date":"2021年5月27日","dateIso":"2021-05-27","committee":"議会運営委員会","time":"午後 ３時３０分～午後 ３時３５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5414#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":1319,"voices":8}},{"id":"r03-20210607-6","meetingId":"r03-cm06","date":"2021年6月7日","dateIso":"2021-06-07","committee":"区民委員会","time":"午後 １時００分～午後 ２時４８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"地域活動課と商業・ものづくり課の所管についてそれぞれ伺いたいと思います。そうしたサポートの周知について対応を伺いたいと思います。質問は、シンプルですけれども、コロナによる収入源の影響をきめ細かくどのように今後とも把握をしていくのか、それに見合った対応として追加対策をどのように考えているのかそれぞれお伺いしたいと思います。","respondent":"川島地域活動課長、遠藤商業・ものづくり課長","answer":"周知ですが、こちらはワクチン接種の相談対応というのは庁舎でやっておりますけれども、周知をこれからもしっかりやっていくということで、地域センターのほうのご案内もその中に載せていただいて。今後も景況の状況等を判断いたしまして、そのときに沿った支援策などを検討させていただきたいというふうに考えているところです。","voiceIndex":28,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"結構区役所に来られる方もいるのですけれども、町会とかいろいろな取組を含めて地域センターを身近に感じている方は、何でも地域センターに相談できる関係も長年培ってきておりますので、ぜひそうした姿勢で進めていただきたいと要望しておきたいと思います。思い切ってそこへの直接支援をぜひ検討していただきたいと、この間も述べてきましたけれども、ご検討いただければと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"オリンピック・パラリンピックについて伺いたいと思います。先ほどもご説明の中で東京２０２０大会が開催されるかどうか、観客の有無はどうなのか、コロナの状況もよく見ながら、様々なシナリオを想定していると課長から説明がありました。ぜひ品川区として区と国と東京都に開催中止を要請していただきたいと思いますが、いかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"新型コロナウイルスがなかなか収まりを見せないような状況の中ですが、安全・安心を追求しながら、それをまず第一に考えて私どもも計画しております。今のところ、東京都や組織委員会にそういった申入れをする予定はございません。","voiceIndex":54,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"この状態でできると思うのかどうか、改めて伺います。こうした中で東京２０２０大会の開催は余りにも無謀だと、住民からもやめてほしいとの声も上がっています。聖火リレーについては後で述べますけれども、やはり密を作るこういう状況は避けるべきだと思いますが、改めていかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"ブラインドサッカーの件を例に出しましたけれども、おっしゃるとおり東京２０２０大会は幾つもの競技が同時に行われるわけですから、今おっしゃった例が参考にはなっても、実際の競技が同時に行われるにはとても安全・安心な状態は作れないと思います。ぜひとも国や東京都に対して開催中止を要望するよう、重ねて要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-005"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"聖火リレーですけれども、わざわざ密になることをなぜやるのか伺いたいと思います。そうした中で、なぜわざわざ密になるようなことをやるのか伺いたいと思います。しかも公道を使って、事前に広報でお知らせまでして、こうした聖火リレーはリスクを伴うから行うべきではないと思いますが、いかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"しかしながら、１カ月前ですとそれからコロナの状況というのは変わりやすいところがありますので、最終的には大体２週間ぐらい前まで様子を見て、それでどのような形式で行うかというのは決めるというふうな形になっておりますので。","voiceIndex":67,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"いやいや、ここから先はだめです、２ｍ以上のソーシャルディスタンスを保ってくださいという呼びかけを区の職員が行うのですか。実際に区の職員を配置して、ここから先はご遠慮くださいと、そういう対応をするのか、具体的に伺いたい。実際の開催そのものは少し直前でというお話がありましたけれども、例えば緊急事態宣言の下でも聖火リレーは行われるのか、改めて伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"その場合に、先ほど申し上げたとおりセレブレーション会場で少し小さくした形になろうかなと思いますので、そこはもちろん区民の安全・安心を第一に考えてやりますので、ご心配ないようによろしくお願いします。","voiceIndex":69,"id":"exchange-007"},{"speaker":"横山委員","kind":"確認","question":"１点だけ確認なのですけれども、こちらは「沿道には来ることはご遠慮ください」と案内するということで、この資料には「ＮＨＫの特設サイトで視聴できます」とあるのですけれども、インターネットをお持ちでない方に関しては、何か見られるような手段ですとか、何かあるのでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今のところインターネットでは、リアルタイムで見られるというものなのですね。どうしてもやはりインターネットをお持ちでない方ですと、なかなかちょっと見るのが難しいかなということもありますので、そのあたりはまたいろいろ考えていきたいと思います。","voiceIndex":72,"id":"exchange-008"},{"speaker":"横山委員","kind":"意見","question":"もし何かしら行われる場合には、インターネットをお持ちでない方にも、リアルタイムではなくても、ご視聴いただけるような何か手段があるといいかなと思いますので、ぜひご検討をお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-009"},{"speaker":"くにば委員","kind":"質問","question":"「ご遠慮ください」という言い方についてなのですけれども、基本的に密を作らないために沿道で観戦するのはやめてほしいというスタンスであれば、罰則つきでなくても、観戦は禁止しますという言い方ができないものなのかということを１点伺いたいのですけれども。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"遠慮いただいて、全く、１人も来なくなるとはとても思えないですが、少なくするための最大の措置としてご遠慮くださいという文言を使うというふうに決めたところです。なかなか禁止というところまで踏み込むのは厳しいかなというふうに認識しております。","voiceIndex":75,"id":"exchange-010"},{"speaker":"くにば委員","kind":"質問","question":"区としては協力という立場なのはわかりますけれども、観戦は可能であればゼロが望ましい、来てほしくないという立場なのか伺いたい。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ソーシャルディスタンスを取るために聖火リレーのボランティアに声を出さないでとか、ソーシャルディスタンスを守ってもらえるようボードを持ってもらい、距離を取ってもらうということで、また、観覧はご遠慮くださいというのは。","voiceIndex":77,"id":"exchange-011"},{"speaker":"くにば委員","kind":"質問・要望","question":"それがひいては間違いなく確実に安全な方法と思うので、そういったスタンスを私としては要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"昨年と重なる部分はあるかとは思うのですけれども、やはり中小企業支援について新型コロナウイルス感染拡大による事業所への補償、支援ということは区民委員会としては引き続き行っていくことが私は大切ではないかなと思いますので述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-013"},{"speaker":"くにば委員","kind":"意見","question":"遡ってそれぞれの年度を見ると、基本的には都市型観光が毎年所管事務調査に盛り込まれていたのですけれども、もちろん昨年に関してはコロナ禍というところで観光ではなく、あくまで一番大事なのは中小企業支援であったり、商店街への支援、困っていらっしゃる方々について我々は考えて、支援をどういうふうにしたら支援できるかというところを主眼に置いていたと思うのですけれども、令和３年に関しては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":84,"id":"exchange-014"},{"speaker":"横山委員","kind":"意見","question":"すみません、２点あるのですけれども、スポーツのイベント等が昨年中止になったものが多いというふうに感じております。２点目なのですけれども、世代間で、なかなか交流というのができない状況にありますので、分断を防止するような多世代の区民の触れ合いですとか交流の在り方みたいなところもぜひご検討いただけたらなというふうに思っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":85,"id":"exchange-015"},{"speaker":"新妻副委員長","kind":"意見","question":"今年度マイナンバーの推進というところでの職員の配置も増やしていただいた上での体制が取れるのかなと思っておりまして、マイナンバーの活用または推進というところで１つ取り上げていただけたらと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-016"},{"speaker":"中塚委員","kind":"確認","question":"マイナンバーのことについて事業を確認したり、理解を深めることはいいかと思いますが、推進と入ってしまうと私は推進すべきではないという立場になりますので、そのこと自体を所管事務調査で取り扱ってはいけないと言っているわけでは決してないのですけれども、推進という言葉はちょっと調整していただけたらなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-017"},{"speaker":"横山委員","kind":"意見","question":"今マイナンバーの話が出ていたかと思うのですけれども、本日の事務事業概要のご説明でも、マイナンバーの申請件数が昨年２倍以上になっているというところで、マイナンバーを含めた様々な戸籍住民課が取り扱っている申請関係ですとか、そういったところも件数が増えたり、インターネットを利用した申請などいろいろ手続方法が変わってきたりですとか、そういった時期に来ているかなと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2900#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":34806,"voices":89}},{"id":"r03-20210607-7","meetingId":"r03-cm06","date":"2021年6月7日","dateIso":"2021-06-07","committee":"厚生委員会","time":"午後 １時００分～午後 ３時４９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"石田（ち）委員","kind":"提案","question":"今度の第２回定例会に、手話言語条例が提案されるということだと思うのですけれども、聴覚障害者の皆さんがずっと要望されてきたことですので、やはりよいものにしていきたいと思っていますが、そこで大事なのが当事者参加ということで、この間、区は、品川の聴覚障害者の会の皆さんや明晴学園、また、関係される皆さんと議論を重ねてきたとも伺っているのですが、提案されるのが第２回定例会ということで。","respondent":"松山障害者福祉課長","answer":"手話言語条例につきましては、当事者の意向に沿って、これまでも何度もずっと意見交換を続けてまいりましたし、これからも同じように、それは変わらないものです。詳細につきましては、また上程のときに説明します。","voiceIndex":26,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"提案","question":"最後の、どういう条例が提案されるかというところまで、当事者の皆さんと確認し合っているのかというのをお聞きしたかったのですけれども、そこをもう一度お願いしたいのと、あと、併せて、同じ障害者福祉課のところなので伺いたいのですが、障害福祉計画と障害児福祉計画について、策定委員会が開催されていて、今度、厚生委員会にも報告されるということですけれども、計画が策定された後に。","respondent":"松山障害者福祉課長","answer":"２点目ですけれども、品川区障害福祉計画推進委員会につきましては、計画の策定委員会とは別に設置する予定です。","voiceIndex":28,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、策定委員会自体は、策定されたら解散ということでいいのでしょうか。","respondent":"松山障害者福祉課長","answer":"委員ご指摘のとおり、計画が策定されれば、策定委員会の役割はそこで一旦終了ということになります。それとは別に、品川区障害福祉計画推進委員会を新たに設置する予定です。","voiceIndex":30,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。コロナ禍ということもありますけれども、その２点、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"しかしながら、区内にも医療的ケアのコーディネーターを配置しており、できることは進めていっておりますので、今年度、また感染症の状況を見ながら、開催に向けて実施していきたいと考えています。","voiceIndex":32,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、２回目の準備会議がいつかとかというのは、今のこの状況では出せないということでしょうか。","respondent":"松山障害者福祉課長","answer":"医療的ケア児等支援関係機関連絡会の予定ですが、やはり出席される委員の方々が、病院の関係者、あるいは直接医療的ケア児に対しての支援をされている方が多うありますので、そこら辺はこちらも非常に慎重になっておりまして、委員の方々と意見交換しながら。","voiceIndex":34,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。それで、最後に、生活保護のところで、先ほど課長のほうからも、減少傾向にあるということでした。コロナ禍で生活が大変厳しくなっている方も多くいる中で、令和２年は減少しているという、この状況をどのように見ているか、伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"減少している主な要因といたしましては、申請自体が減っているということではないのですが、受給されている方で、残念ながらお亡くなりになられる方が年齢層的に非常に多いという状況でして、結果として減少傾向になっているです。","voiceIndex":36,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、保護基準などもどんどん引き下げられていく中で、やはり基準に合うというか、苦しいのだけれども、要はそこに対象にならないという方もいるのではないかと感じるのですけれども、そういった状況は感じられているでしょうか。","respondent":"櫻木生活福祉課長","answer":"生活が苦しいということで、生活保護に至らない状況の方に対して、生活困窮者自立支援制度ということで、住居確保給付金であったり、そのような制度が整っておりますので、そちらのほうも周知をしてまいりたいと考えています。","voiceIndex":38,"id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"職員体制について伺いたいと思います。それから、もう一つ、人員体制のところで、生活福祉課なのですが、９ページのところで、「暮らし・しごと応援センター所長を兼務」ということだけが書いてあるのですけれども、暮らし・しごと応援センターも生活福祉課の中に入っているかと思うのですが、暮らし・しごと応援センターの職員体制というのはどうなっているのかを伺いたいと思います。","respondent":"松山障害者福祉課長、櫻木生活福祉課長","answer":"今、職員は区の障害者福祉の向上のために日々努力をしています。業務に対して人員をどう配置するか等につきましては、区の全体の中、あるいは福祉部の中でまた検討していきたいと考えています。２点目、ケースワーカーの数と担当数が、現在、ケースワーカーが４４名で、１人当たりが１０１世帯ということで、また、最大の受持ち件数としては１３５件というケースワーカーがいるのですが、こちらは補足しますと。","voiceIndex":41,"id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう中で、ケースワーカーの方の支援というのも様々な形で求められることがすごく多くなっておりますので、ここのところはしっかりと配置人数を増やしていただきたいということで、改めて要望しておきたいと思います。それから、暮らし・しごと応援センターですけれども、これは本当にきめ細かにやっていただいて、感謝しております。","respondent":"櫻木生活福祉課長","answer":"暮らし・しごと応援センターにつきましては、いわゆる相談員という形で配置されている方は全て会計年度任用職員という形になっております。そのほかに、管轄するような者はまた別に正規職員としているです。","voiceIndex":44,"id":"exchange-009"}]},{"id":"topic-02","title":"に戻りまして、幹部職員紹介","agenda":"に戻りまして、幹部職員紹介","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"保健予防課で３名増えているということなのかと思うのですけれども、そこのところは、もっと抜本的な保健師の増員というのが私は必要なのではないかと思うのですが、今年、どういう考え方で保健師を配置されたのか、また、今後どのように増やしていかれる考えなのか、その点について伺いたいと思います。","respondent":"柏木品川保健センター所長、鷹箸保健予防課長","answer":"その部分は強化されたと認識しております。今後につきましては、当然、今の人数が十分かと言われれば、そこは検討する余地はあると思いますので、今後の計画については、人事部門のほうとは相談をしていきたいと考えています。それ以外に現在、派遣の看護師が１８名、派遣の事務職員が４名、東京都から常に応援職員が４名ということで、非常に大きな体制で対応しているところになります。","voiceIndex":85,"id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ありがとうございました。先ほども言いましたように、これから保健師の役割というのが本当に重要だと思いますので、乳幼児から高齢期に至るまでのあらゆる年代を対象にということで、ここのところをしっかりと充実させるということでは、これからも引き続き保健師の増員をしていただけますように要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-011"}]},{"id":"topic-03","title":"品川区の新型コロナウイルス感染症にかかるワクチン接種準備状況","agenda":"品川区の新型コロナウイルス感染症にかかるワクチン接種準備状況","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"予約されていない方の状況というのは、全て把握するというのは難しいかもしれないのですけれども、予約されていない３８％、接種したくない方や接種できないという人もいるので、１００％にはならないのかなと思うのですけれども、区としてはここはどのように考えられているのかというのを伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"予約をされていない方ですが、恐らくその中には、防衛省が設置している大規模接種センターに行かれた方、それから、高齢者施設での接種が既に終わっている方も含まれております。","voiceIndex":97,"id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。把握するというのは大変なことだと思うのですけれども、今、要は障害があってとか、あとは認知症でとか、接種券が来たこと自体、また、接種が始まっていること自体知らない方といった、７５歳以上の方へのサポートとして、ヘルパーや在支の方々の手も借りていることと思うのですけれども、そこの状況を伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ご指摘のとおり、在支の方等々のご協力をいただきながら、予約は進めさせていただいているところです。寝たきり等々の方への訪問に関しましては、現在、検討から調整を進めているところですので、今後、うまくできるように、今、医師会とまさに調整中です。","voiceIndex":99,"id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"確認","question":"ぜひ受けたいのに受けられない人がいないようにというのは、お願いしたいと思います。６５歳以上の人の予約が１４日から始まりますけれども、前回、新聞等々で、６５歳未満への接種開始時期というのが、品川区は未定だと出ていたのですけれども、ということは、先ほどの説明で、６４歳以下の方には６月２９日から接種券を配布、７月上旬から予約開始ということで、もう一回確認したいのですけれども。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"おっしゃるとおり、６月２９日に発送、７月上旬より予約を開始です。","voiceIndex":101,"id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、今、個別接種の箇所について、その説明もあったのですけれども、６月２１日からスタートできるようにという説明だったのですが、今現在、何か所ぐらいされるのでしょうか。そこをお聞きしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"現在まさに調整中でございまして、数については確定した数字ではございませんが、６月２１日の段階では、５０以上の個別接種の会場から進めさせていただいて、順次増えていくということで、１００以上の会場になろうかということで、現在調整を進めております。","voiceIndex":103,"id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。それで、障害を持たれている皆さんへの接種のサポートというのがどのようになっているのかというのをお聞きしたいのですけれども、接種会場で、聴覚障害の方には手話通訳とか要約筆記とかの配置、また、タブレットでの遠隔手話通訳などが会場でできるようにと思うのですけれども、そういった対応というのは、今現在の接種会場ではどのようになっているか、お聞きしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"手話のタブレット、通訳も含めてですが、タブレットは配備しております。筆談具も配備しております。","voiceIndex":105,"id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"確認","question":"分かりました。今ある接種会場の全会場でそれが実施できているということなのかを確認したいのと、あと、視覚障害者の方への接種券は、封筒に切り込みが入っていて、デイジー再生機で再生できるマークもついていると思うのですけれども、全員がデイジー再生機を持っているとは限らないと思うのですが、そうした見えずに認識できていないというところへの対応はどのようにされているのか、伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、秋山保健整備担当部長","answer":"Ｕｎｉ－Ｖｏｉｃｅの切り込みを入れて、発送はいたしました。その後の予約ができているかできていないかというところにつきましては、現時点ではこちらのほうで１００％の把握はできておりません。視覚障害者の方については、福祉部のほうから個別にご連絡をさせていただいて、予約を取るようなことをしています。","voiceIndex":107,"id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"きめ細かく対応していただきたいということで、お聞きしました。大幅にあるのか。そして、キャンセルになった部分というのはどのように。保育園などのところにも接種がと新聞にも載っていたのですけれども、そこら辺の状況を詳しく教えていただきたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"もちろん前日までにキャンセルが出ていれば、そこの予約枠は取れますので、埋まっている場合もありますし、実際にキャンセルがどれぐらいという数は流動的で分かりませんが、当日キャンセルが出てしまった分に関しましては、ワクチンは絶対に廃棄をしないようにということで。","voiceIndex":110,"id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうしたら、ワクチンの廃棄というのは出していないという状況で進んでいるということでよろしいですか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"廃棄は出ておりません。","voiceIndex":112,"id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、会場の空き状況が分かる一覧にならないものかという声も、この間、多数寄せられているのです。ほかの病院だったり、様々、ウェブ予約できるシステムとかを見ると、空いている時間、空いている場所というのが分かるようになるのですが、そういうものが出るようにしていただきたいと思うのですけれども、システム的にできないのでしょうか。伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"例えば、旧荏原第四中学校の会場を指定して、２０２１年６月７日と日程を入れますと、６月７日以降の旧荏原第四中学校の空いている時間枠と空いている日にちが時系列に出てくるという感じに今現在はなっております。","voiceIndex":114,"id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"個別接種が６月２１日からやっと始まるということで、すごくよかったと思っています。６月２１日から個別接種が行われるというのは、どういう形で区民にお知らせがされるのか。そこら辺のところを教えていただきたいと思います。そこら辺の仕組みも併せて、具体的なところで教えていただきたいと思います。その点についてもお聞かせいただきたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"かかりつけの患者のみなのか、それ以外なのかというのは、現状、クリニックのお考え等々もありまして、現時点でどうするというのは、全て集約できているものではございませんで、明日・明後日と、荏原医師会、品川区医師会の両医師会に、またシステム等々の説明に参りますので。","voiceIndex":118,"id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"地域センターなどでも、来られた方に対してはサポートをしていただいてすごく助かったということをお聞きしましたし、テントのところではかなりの方が予約でサポートしていただいたのではないかと思うのですけれども、今度、６５歳以上の方が１４日から始まるときには、そのサポートの仕組みというのは、皆さんに周知して、スマホでもなかなか取ることができないという方は。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、秋山保健整備担当部長","answer":"広報しながわについては、６月２１日号を予定しております。その辺りになろうかと思います。６月２１日号ということを言いましたけれども、広報しながわは（原稿の）締切りが１か月前ですので、もちろん今の時点で分かっていないということは、６月２１日号には出せませんので。","voiceIndex":120,"id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"分かるようであれば、例えば１週間のうちにははっきりするとか、そのようなことが分かったら教えていただきたいと思います。サポートセンターということは、この間みたいな形でテントでもサポートしてくださるし、各地域センターでもサポートをしてくださるということで、それをお知らせするということで、そういう体制を取っていただくということで確認させていただいてよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、高齢者施設とか障害者施設で働く方々から、すごく不安で早くやってほしいという要望も受けているのですけれども、先ほど６月２９日から６４歳以下の方に接種券を配布して、７月上旬から予約を取り始めるということなのですけれども、この予約の取り方というのは、初めは多分、基礎疾患のある方とか、こういう高齢者、障害者サービスの従事者の方とか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ただ、キャンセル対応というか、ワクチンが当日会場で余った分に関しましては、先ほどの繰り返しにもなりますが、ホームページには、施設従事者であったり保育士であったり、その辺りの順番を載せしていますので。","voiceIndex":126,"id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"接種の順番というのは、国で示されている手引きもありますので、そういうところに則ってやっていくということになると思うのですが、６月２９日に６４歳以下の方に接種券を配布するというところでは、残りの全ての区民に、一斉に接種券が配布されるということで考えていいのでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"発送についてですが、基礎疾患の方は年齢問わずおりますので、むしろ一斉に発送しないとまずいだろうということで、一斉に発送します。訪問しての予防接種ですが、調整中です。お待ちくださいませ。","voiceIndex":128,"id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"最後にします。毎回申し上げておりますけれども、今までにやったことのない、これだけのたくさんの区民の方へのワクチン接種ということで、本当にご苦労が多いと思います。でも、区民の方にとっても早くやりたいというすごく切実な思いもありますので、これからもいろいろ取組をよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":130,"id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"確認","question":"６５歳以上の接種率が分かるということでよろしいですか。これは確認なのですけれども、６５歳未満の方々も、先ほどの保育園とかいろいろなところの従事者の方々についての欄があって、それはシステム上優先して予約できるようになるのでしょうかということです。７５歳以上とか６５歳以上の方のところには、基礎疾患のあれはあったけれども、そういう仕事の枠がなかったと思うので、そこの確認です。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"施設の職員、従事者、要は優先順位に含まれている方に関しましては、そういった優先できる期間等々をつくることで、今現在検討して進めているところですので、今後、その方たちがほかの方よりも優先して受けることができるように、現在、最後の調整を進めているです。","voiceIndex":132,"id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そういう従事者の方に優先してやっていただくということをしていただきたいという意味で言っているのですけれども。すみません、予約の仕方が分からなかったので。では、特にそちらで把握するのではなくて、申し込む方が自己申告で入れていって、行った先で、本当にそうですかというのを証明していくというやり方で、特に６４歳以下の方は進めていくということでよろしいでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"そのとおりです。","voiceIndex":137,"id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問","question":"それで、特に私の地域のほうだと、北品川クリニックが後から追加されたので、それで皆さんは競馬場とか、様々予約をされたけれども、７月中旬だとか、それぐらいの予約の方もいらっしゃったりして、そうすると、キャンセルして北品川クリニックに電話をかけて予約の変更をすると、この時期なので、予約が取れて６月中旬に１か月早まったとか、電話で予約をするので、空き状況とか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":140,"id":"exchange-029"},{"speaker":"若林委員","kind":"確認","question":"１点だけ。これ、各区ばらばらなので、あえて聞かなくてはいけないと思っているのですけれども、先ほどのくだりの施設の従事者の接種、会場で一定の枠があって、ワクチンの無駄が出ないように、余りそうになったときは施設の従事者に来ていただいてというお話があったり。そういった場合に、品川区民でなくて区内の施設に従事している方も、同じように打てるのかどうか。そこの確認をさせてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、鈴木（博）委員長","answer":"現状では、接種券が、当区で手筈することのできる、品川区民の従事者に、キャンセルの対応等々で、各会場に打ちに行ってもらっているという運用をしております。一番最初に住所と住民票とを照らし合わせて、それが合わなかったら、はねられてしまうから。だから、多分、今の説明は、要するに、品川区民ではないとマッチングしないから駄目ではないのかということです。","voiceIndex":144,"id":"exchange-030"},{"speaker":"若林委員","kind":"質問・要望","question":"という現状を、改めて私なりに認識させていただきました。そうすると、同じ職場の中で、施設従事者の中で、私は区民だから受けられましたという人がいる、また、区民ではないから受けられない人がいるという。これは明確に言えることだと思いますので、そこら辺の対応は改めて、研究はされていると思いますけれども、進めていって、改善をよろしくお願いしたいと。これは要望にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"品川区のワクチンメーターで、６５歳以上の接種率が１回目接種が１７.７％で、２回目が１.２％ということで、６月２日の時点ということでたしか書かれていたと思うのですけれども、集団接種会場も増えましたし、２１日からそういう個別接種も始まるということで、接種できる枠というのがぐっと広がるということになっていくと思うのですけれども、そういうことで。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"あくまで試算ではありますが、７月中に終わる方向で、今現在、一生懸命準備を進めておりますし、区としても動いているです。","voiceIndex":149,"id":"exchange-032"},{"speaker":"せお委員","kind":"質問・要望","question":"すみません、１点だけ。６５歳未満の方、７月初めから接種が開始されると思うのですけれども、ここら辺、今、施設も増えてきているのですが、まだ今の時点で、区民の方のお声を聞くと、予約が取れないと。そこら辺の見込みが分かれば、教えていただきたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"その一方、会場が大きいであったりとか、長い時間開設してくださっていることによって、１日の接種人数としては、さらに大きな人数を打つことができる会場も実際にはありますので、そういった会場も含めての見込みというか、試算をしているとご理解いただければと思います。","voiceIndex":151,"id":"exchange-033"},{"speaker":"せお委員","kind":"質問","question":"先ほど個別接種の会場も準備されているということで、いろいろな委員からも質問があったと思うのですけれども、かかりつけの患者なのか、そうでなくても取れるのかというところで、クリニックのお考えがすごく重要になってくるのですけれども、それは統一するということですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-034"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それをどこかで取り上げたほうがいいと思っていて、人ばかりという話ではないと思うので、すぐ人ばかりと誰か言う人がいるかもしれないけれども、そういう視点ではなくて、保健所機能の強化は、どこかでやはり１回はやったほうがいいような気がしてならないので、そういう問題も取り上げていただけたらどうですかということ。感染症対策は、それは私は分からない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3598#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":48149,"voices":161}},{"id":"r03-20210607-8","meetingId":"r03-cm06","date":"2021年6月7日","dateIso":"2021-06-07","committee":"建設委員会","time":"午後 １時００分～午後 ３時１３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"あべ委員","kind":"意見","question":"立憲・無所属しながわのあべ祐美子です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":6,"id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"リニア新幹線について伺いたいのですけれども、明日、説明会が行われるということですが、区としてもこの説明会には参加をしていくのかどうか。区民に大きな影響を与えるものですので、どうしていくのかというのを伺いたいのと、あと、このリニア新幹線によるシールド工法の安全性ですね。今後どのように取り組んでいくご予定なのか、伺いたいと思います。２９号線を含む特定整備路線の問題ですね。","respondent":"中道まちづくり立体化担当課長、鈴木都市計画課長","answer":"そうした中で、今、ＪＲ東海は、シールドについての安全性の向上という観点で検討しているというところは聞いてありますので、明日の説明会も含めて、また確認していきたいというふうに考えてあります。品川区のまちづくりマスタープランの改定ですが、平成２５年に策定した計画について、今、中間期を迎えるということで、今回改定を、今年度ならびに昨年度、２年間かけて行っていく予定です。","voiceIndex":35,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"リニアのほうでは、明日の説明会も含めて確認していくということですので、ぜひ確認していただきたいと思いますし、今回の調布の陥没事故のことで、大深度の工事が地上に影響を及ぼさないというのはうそだったということが明らかになりましたので、そこはやはり、この品川にも影響が出てくる可能性があるということだと思いますので、それはしっかりと注視をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回コロナ禍ということで、今後の工事の説明会が個別説明ということになってしまったのですけれども、コロナの中なのでそういったこともあるとは思うのですが、やはり住民の皆様は一緒に聞きたいというのもあると思いますので、住民が一緒に聞きたいと、集会室など借りて聞きたいと言う場合には、ぜひ応じていただきたいと思うのですけれども、そういったことを業者にも言っていただきたいと思うのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-004"},{"speaker":"あべ委員","kind":"質問","question":"すみません。２点ほどお伺いしたいと思います。１点目ですけれども、品川区、リニアの話も出ましたし、道路あるいは立体化の事業など、様々な、地域住民に大きなインパクトを与える事業がこれからも続いていくかと思います。取り入れる考えがまずあるのか、ないのか。既に取り入れているよということであれば、ちょっとまだ不十分な気もするのですけれども、その評価も含めて教えていただければと思います。","respondent":"中道まちづくり立体化担当課長","answer":"今回、連続立体交差事業、または駅前広場というものは、都市計画事業になりますので、今後は都市計画事業の流れに沿って進んでいくというところで、説明会であったり、または都市計画資料の縦覧、また意見をいただくといった場面で。","voiceIndex":48,"id":"exchange-005"},{"speaker":"あべ委員","kind":"質問・要望","question":"２点目なのですけれども、航空機騒音常時測定事業、こちらは都市計画課のほうで整備をされておりますけれども、これの騒音以外の環境問題というのは、これも都市計画課で扱っていくのか、それとも、そちらは環境課になるのか、どういうくくりなのかというのをご説明いただきたいのと、現在、測定局２局ということですけれども、これを増やす考えがあるのかということを確認したいと思います。","respondent":"鈴木都市計画課長","answer":"測定局の増設につきましては、基本的には現在のところ考えはございませんが、国のほうで、昨年度も短期測定局の設置というところで、区内を含めて、他区のほうでも測定局を増設して、短期ですが行ってきたですので、そうしたところを国のほうに。","voiceIndex":50,"id":"exchange-006"},{"speaker":"あべ委員","kind":"質問・要望","question":"そうした国との折衝ということも含めて都市計画課なのだと理解をしておりますけれども、例えば、航路上でしたら東大井の集会所ですとか、住民の方々からご要望も多いところですので、そうしたことも、国との折衝の中でも役立てていただきたいですし、また、区としてもぜひ主体的に取り組んでいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"大きく２つ確認をしたいと思います。ただ、これから議論する中で、この建設委員会として、品川区の建設委員会としての位置づけというのは、やはりあまり考えられないことなのでしょうか。けれども、新ルートについて、具体的な例で言うと、位置づけが明確ではないなと。","respondent":"鈴木都市計画課長","answer":"そうした経過、経緯をしっかり都市計画課と、所管として建設委員会の皆様のほうにも適宜適切にお知らせし、ご議論といいますか、報告をさせていただいてご説明させていただきたいというところで、私としては考えている次第です。","voiceIndex":54,"id":"exchange-008"},{"speaker":"西本委員","kind":"提案","question":"もう１つの確認事項、仕切りの問題です。先ほども委員長のほうから仕切りの話についてはいただきました。総務とかいろいろ入っているので。ですので、非常に、これから１年間、建設委員会で議論する、それから、報告事項も含め、議案も含めて、仕切りが非常に難しいのではないか、その辺の、特別委員会の正副委員長との打合せはどういうところまでされているのか、今後のお考えも聞きたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"少しクリアになってまいりました。ですので、できれば私たちも建設委員会の立場として議論したい部分もたくさんあるものですから、そこを仕切りですと言われてしまう部分があると、ではどこまでやったらいいのみたいなことになってしまうので、できる限り議論ができるような配慮をしていただければありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後に３つ伺いたいのですが、区営住宅について、住宅課の２ページのところで、目的を区営住宅の維持管理ということで記載されておりますが、この姿勢を改めるべきだと私は思っておりまして、区民の住宅事情は大変さを増しています。やはり家賃が高い。なぜ、この目的が維持管理なのか伺います。区内で言うと京急線などがなかなか設置されない状況ですけれども、区のお考えを伺いたいと思います。","respondent":"竹田住宅課長、鈴木都市計画課長","answer":"ご質問のありました区営住宅の増設ですが、今のところは考えておりませんので、維持管理という表現にしています。事務事業概要への航空機騒音の測定結果の記載についてですが、昨年４月以降、今年２月まで測定結果をホームページで公表していますけれども、非常にボリュームが多くて、全てを載せるということは現実的に不可能ですが、今。","voiceIndex":60,"id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"区営住宅のところです。推進をしていきたいということですが、増設はしないというのは矛盾するのではないかと思うのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-012"}]},{"id":"topic-03","title":"事務事業概要を再び議題に供します。 進め方でございますが、先ほどと同様に、災害対策担当も含め、防災まちづくり部の事務事業概要","agenda":"事務事業概要を再び議題に供します。 進め方でございますが、先ほどと同様に、災害対策担当も含め、防災まちづくり部の事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"それで、冊子の９０ページに、備蓄品について記載がありますけれども、食料について、都と区の役割分担で、区は１日分の備蓄をするということになっておりますけれども、都との分担がどうなっているのかということと、あと、大災害時には、特に地震だと思いますが、１週間の備蓄をと、住民には呼びかけられているかと思うのですが、そこの関係性というのはどういうふうになっているのか伺います。","respondent":"高梨公園課長、平原防災体制整備担当課長","answer":"最初に、私のほうから、しながわ区民公園の説明会についてのお答えをします。６月１日１８時から、事前申込み制といった形で説明会の開催をいたしました。このような形での分担となっておりまして、合わせて３日分、それ以降につきましては、政府等々からの支援物資により対応ということになってあります。","voiceIndex":102,"id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"備蓄のところで、仮に首都直下地震が来たときに、この３日間で、都と区で合わせて３日間ということですが、その後、政府の物資というのがしっかり来るのかというのが、相当な被害になると思うのですね。震度７レベルになると。そうしたときに、３日分で足りるのかという思いがあるのですが、いかがでしょうか。","respondent":"平原防災体制整備担当課長","answer":"３日分ですけれども、まず、政府の物資につきましては、これまでの大きな災害の中で、実際にものが届かない、あるいは自治体側の被災に伴いまして、どのような物資が必要かということが政府に届かないということもございました。","voiceIndex":105,"id":"exchange-014"},{"speaker":"あべ委員","kind":"質問・要望","question":"すみません。その理由とか、だからこういう形で置いておくことが必要なのだということがあれば教えていただきたいのと、これは道路課にくっついているのですけれども、例えば、公園ですとか、防災広場ですとか、いろいろ用地が必要になってくるものもあると思うのですが、用地担当課長というのは道路だけの用地なのでしょうか。どういうくくりになっているのか確認させてください。","respondent":"溝口用地担当課長","answer":"もともと、一番はやはり都市計画道路等、一番、用地買収の関係でいろいろ難航しながら、それでも事業を進めていかなければいけない、そういったところがありますので、事業部隊と、用地を買う部隊が一緒になって用地交渉に当たる、そういったことでの。","voiceIndex":108,"id":"exchange-015"},{"speaker":"西本委員","kind":"確認","question":"防災訓練の件で、８４ページにあります避難所訓練なのですが、防災訓練は、コロナ禍があったので昨年の実績は０ということになっているのは、これは当然だと思うのですが、避難所訓練の場合、１１会場になっているのですね。ですので、この件は、今年はどうされるのかなと思っているのですが、確認したいと思います。","respondent":"五十嵐災害対策担当課長","answer":"差引き４１会場の訓練については、実際にはできておりません。今年度は、コロナ禍ではありますけれども、まだ続くかもしれませんが、その中でもできる訓練というのをご提案しながら進めていきたいと考えております。","voiceIndex":113,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"これも確認ですが、１１会場でされたということで、決めたのは、やるよという手を挙げたところだったのか、自由選択になってしまっている部分があったのか。ですので、半強制ではないのですけれども、ご理解をやはり求めていくということは、今年度は必要なのではないかなというふうに、すみません、意見になってしまいますけれども、その辺のお考えを教えてください。","respondent":"五十嵐災害対策担当課長","answer":"西本委員のご意見を踏まえて、今年度はそのような形で進めていきたいと考えています。","voiceIndex":115,"id":"exchange-017"}]},{"id":"topic-04","title":"が、所管する議題が終了した理事者の方は、ご退席いただいて結構です。 ありがとうございました。 それでは、報告事項「『東京河川改修促進連盟』の総会および促進大会」","agenda":"が、所管する議題が終了した理事者の方は、ご退席いただいて結構です。 ありがとうございました。 それでは、報告事項「『東京河川改修促進連盟』の総会および促進大会」","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"ここは、今すぐにどうしろというわけではないのですけれども、この事業予算に見合った額程度の予備費になるように、数年かけて調整していくような考え方も出していくべきではないかと思うのですが、私としてはそういう意見も付していただきたいなと思いますけれども、いかがでしょうか。","respondent":"栗原河川下水道課長","answer":"それにつきましては、繰越金等の金額を見て判断したものと、事務局から伺っているところです。本日伺った、今後の分担金の徴収等に関しましては、私のほうから事務局のほうに申し伝えて、今後のあり方について検討するよう伝えていきたいと思います。","voiceIndex":130,"id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4322#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":41015,"voices":136}},{"id":"r03-20210607-9","meetingId":"r03-cm06","date":"2021年6月7日","dateIso":"2021-06-07","committee":"文教委員会","time":"午後 １時００分～午後 ３時２８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"品川改革連合の筒井ようすけです。どうぞよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"そういった点で、やはり安心して学校で学べる環境を整えるためには、教育委員会としてはできることは何でもやるべきだと思いますし、この学校の教育従事者への定期的なＰＣＲ検査の実施というものは必要だと思うのですが、その考えがあるのかということと、あともう一つはオリンピックなのですけれども、やはり感染対策がどう見ても逆行してしまうのではないかということで。","respondent":"矢部教育総合支援センター長、工藤指導課長、勝亦学務課長、有馬庶務課長、米田教育次長","answer":"昨年度の不登校ということなので、そういう傾向と、あと実態的には相談員が関わっていますけれども。区としての準備といたしましては、暑さ対策のための物品の購入でありますとか、看護師、あるいは引率補助者などが配置できるよう。１年ごとにこの学年が引き上げられてまいりますので、こちら、その受入人数について。私のほうはコロナ対応の、安心して生徒が学べるための教員のＰＣＲ検査ですが、ＰＣＲ検査はそのとき、その時点での状態ということで。","voiceIndex":29,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"東京都の条例のほうも、やはりそのような、これまでの人権の歴史などもそうです。なので、ぜひこれは改善していく必要があると考えています。それと併せて、先ほど巻末のほうで紹介されましたけれども、現時点で３５人の学級編制になるのにもかかわらず、いろいろ学校の都合というか、学校のお考えなのでしょうか、第二延山小学校や芳水小学校などでは、一部３５人以上の学級をつくっているところがあります。","respondent":"勝亦学務課長、有馬庶務課長、工藤指導課長","answer":"３５人編制が弾力的な運用を行われているですけれども、来年度以降どうなるかというお問合せですが、学校それぞれと十分協議をして。どうしても物理的なところでの限界があれば、やむを得ないところはありますけれども、今そうならないように。現在も、緊急事態宣言下におきましても、学校行事等につきましては、ガイドラインに従いながら工夫して実施をしている部分があります。","voiceIndex":35,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"１つだけ、第二延山小学校のところですが、前回ですと、物理的な制約ではないのですという話だったと思います。教室はあるのだけれども、その転用など様々工夫すれば、３５人という国が決めた、しかも世論でつくったこの学級編制を実践することは、来年４月から可能だという理解でよろしいのか、それをお伺いします。","respondent":"有馬庶務課長、矢部教育総合支援センター長","answer":"前回答弁させてもらった内容になりますけれども、これは第二延山小学校は物理的にも厳しいということは事実としています。少し補足すると、聞いているところでは、私たちは、例えば４階だったら４階に５年生と６年生を配置して、担任の指導が全部行き届くように、何かあったときには同じ学年で共有するという場面はたくさんあるのですけれども。","voiceIndex":39,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後意見だけ言わせてください。すごい差が出てしまうのです。でもやはり子どもにとって、どの学校に通っても、少なくとも３５人というところでは、本当にこう、何というか、公平な、そして手厚い教育を受けられるような環境を整えるために、選択制、学区をどうするかということも含めて、総合的にぜひ検討して、改善していただきたいというように、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-005"},{"speaker":"松本委員","kind":"意見","question":"今日は概要ということで、細かくはやりたくないのです。組織委員会から、キャンセルする場合は連絡してくださいというような通知が来ているのかどうか、それをお願いします。","respondent":"工藤指導課長","answer":"先般の報道は私どもも把握していますが、私どもが予定しております学校連携応援観戦というものは、都教育委員会からチケットの配券をいただいて、また、その都教育委員会は組織委員会からチケットを配券いただくというものです。","voiceIndex":45,"id":"exchange-006"},{"speaker":"松本委員","kind":"意見","question":"ちょっとこの報道とは違うというような理解なのだと思います。その上で、よく保護者の方たちから言われるのは、欠席扱いするのかどうかというところ、この観戦に行かなかった場合に、子どもは欠席扱いになるのかどうかということもよく最近聞かれるので、そこもお願いいたします。","respondent":"工藤指導課長","answer":"オリンピック・パラリンピック、夏季休業中に当たる場合には、その日は授業日というように設定する予定ではありますが、ただ夏季休業中ということもありますので、欠席した場合には、出席停止と同じ扱いで。","voiceIndex":47,"id":"exchange-007"},{"speaker":"松本委員","kind":"質問・要望","question":"概要なので以上にとどめたいと思うのですけれども、個人的には、オリンピックをやるならば、やはりどれだけ人流を止められるかというところが大事だと思っていて、この観戦も、例えばわざわざ会場に行くのではなくて、モニターなどで動かずにやるという手段もあると思っていますので、ぜひご検討いただきたいですし、あと、これやはり東京都と組織委員会と。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"ＩＣＴ推進のほうにはあまり感染症対策というか、それを補完するような形というようにも書いていないのですが、ちょっと今年の事務事業概要には、教育という、学びという視点からのコロナ対策というものがあるのかと思っていたのですけれども、その辺についてはいかがなのでしょうか。","respondent":"有馬庶務課長、矢部教育総合支援センター長","answer":"具体的な学びのところはちょっと省きますけれども、まず教育委員会の事務事業概要の５ページのところで、新型コロナ感染症への対応というところで項目を設けさせていただきました。庶務課長からもありましたとおり、ガイドラインを毎回バージョンアップして、今１１です。","voiceIndex":51,"id":"exchange-009"},{"speaker":"吉田委員","kind":"確認","question":"すみません。５ページのここの表記、見落としていました。感染症予防ガイドラインは、予算特別委員会のときにも、私たちもそこから質問させていただきまして、常にバージョンアップされているということは認識しております。やはりなかなか表記が難しいということも理解できますので、今のお話でその辺のことをきちんとされていると確認できましたので、これからまた具体的なことで伺っていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"ですから、この辺の考え方や、やり取りがあるのかどうかということを教えていただきたいということと、あともう１点が、その接種に関して、昨年の９月の一般質問で投げさせていただいて、教育長のほうから、１２月だったでしょうか、発信で、コロナに罹患することに関して、人権の視点で働きかけていただいた動画を作っていただきましたが、今度接種の有無についても、やはり先ほど申し上げたように、個人。","respondent":"有馬庶務課長、矢部教育総合支援センター長","answer":"前段のほうですけれども、中学生のワクチン接種の関係ですが、今、区のほうのワクチン接種については高齢者中心ということで、集団接種会場も設けられていて、これはもう区全体として対応するということで。今のお話に続きますけれども、国や都の方向ですとか、ワクチンの接種の数とか、時期などの状況を見ること、あとお子さんたちの様子が一番大切ですので、そちらを十分踏まえて。","voiceIndex":56,"id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"それも含めての確認と、ぜひここは文教委員会なので、厚生委員会の所管というか、担当のほうで主軸になってやっていただくのでしょうが、もしそのような体制になったときに、いろいろ教職員の方々の体制も大変だとは思うのですけれども、学校医などの協力も含めて、いずれにしてもスムーズに接種をしたいという方ができる体制というものは、もしそうなった場合ですが。","respondent":"矢部教育総合支援センター長","answer":"一番大切な権利ですので、大事にして、子どもたちや保護者に不都合が生じないように、平等に進めてまいります。","voiceIndex":59,"id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺います。公園を利用している方に対しての説明会を持ってほしいという要望が上がっていて、区に求めていると思うのですが、これまだ行われていないのですけれども、これいつ頃、少なくとも公園の利用者の方への説明というのですか、もう工事が始まってしまっているので、これは早くやるべきだと思いますが、そちらはいつなのかということを伺います。","respondent":"加島児童相談所移管担当課長、山下子ども家庭支援センター長","answer":"それから公園利用者への説明会の件ですけれども、現在説明会を開催というよりも、個別にご意見等、また、ご要望等を伺っていく考えでおります。私ども子ども家庭支援センターのほうが、令和２年４月から始動したところを含めて、いろいろ細かいご相談等も一元的に受けられるようになったというところで、体制の整備が相談の増につながっているという部分もあります。","voiceIndex":107,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"それでこれから、そのような子育て支援に当たっては、非常に子育て世代の方にとっても重要な施設になると思うので、今後のことを考えても、やはりまずは建設の段階で様々ご意見が出ているわけですから、少なくとも利用者への説明、私たちにぜひ説明会をやってほしいという要望が上がっているわけですから、そこは区の都合で考えるのではなくて、最大限コミュニケーションを取るという意味で。","respondent":"加島児童相談所移管担当課長","answer":"住民や公園利用者の方からのご意見、疑問等については、工事期間中はもちろん、公園利用者と児相が互いに共存していけるよう、ご意見、ご要望には可能な限り対応してまいりますが、今現在、ご説明のほうにつきましては。","voiceIndex":110,"id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"この事務事業概要の作り方は、所管によってそれぞれ特徴があるかと思うのですけれども、よく他課との連携やほかとの連携というものがあって、当然連携は中身を見れば大体分かるのですが、例えばこのこども冒険ひろば事業については、子ども育成課の所管ということなのですけれども、公園内につくられているというところから、当然公園課と一緒に推進していくのか。","respondent":"廣田子ども育成課長","answer":"例えば公園等を使って事業をする場合には、所管である子どもの部門から公園課にこのようなことをやりたいというところを諮って、協議していくという形になっています。","voiceIndex":113,"id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"では結局、子ども育成事業なので、そちらのこのような事業をやりたいというイメージが先にあって、そこから公園課に連携を諮るというような理解でよろしいのでしょうか。","respondent":"廣田子ども育成課長","answer":"冒険ひろばについては場所を探しているのでというところもありましたけれども、例示がちょっと具体的にできないのですが、公園側から、ここにこんな場所があるので、何か子ども向けの事業ができないかということもないことはないので、必ずしもこちらからということではないです。","voiceIndex":115,"id":"exchange-016"},{"speaker":"吉田委員","kind":"質問","question":"それは分かりました。それから、先ほど一緒に聞けばよかったのですけれども、保育教育運営担当というものが今回からできていて、前回の委員会の議事録を読ませていただいたところ、これについての趣旨の議論があったようですが、ちょっと私にはよく意味が分からなかったので、改めて伺いたいと思います。ぜひそうあってほしいなと思っての質問なのですけれども、いかがでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"今ご質問にありました保育教育運営担当課長ができた経緯なのですけれども、先ほど説明もありましたが、今までは施設を担当する課長だったのですけれども、それにプラスしてソフトの部分である、教育の部分も一括して担当することで。","voiceIndex":117,"id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"最後は意見のような感じになりますけれども、やはり、今課長からお答えありましたが、残念ながら私たちから見えてくる事例では、品川区の保育の質とはどうなのだろうかというような事例が具体的に意見として上がってきます。これは要望にとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-018"}]},{"id":"topic-03","title":"長３のその他","agenda":"長３のその他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２日間の出席停止ということですが、その間の学校の活動というものは、教育活動はどのような形でカバーされるのか伺います。","respondent":"矢部教育総合支援センター長","answer":"必要な紙の資料等も配付することになりまして、長い期間になりましたら、いよいよＩＣＴも早速使ってフォローしていきたいと考えております。ただ、学校の事情もありますので、センターとしての連絡を取り合って支援してまいります。","voiceIndex":65,"id":"exchange-019"}]},{"id":"topic-04","title":"に戻りまして、幹部職員紹介","agenda":"に戻りまして、幹部職員紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"品川改革連合の筒井ようすけです。どうぞよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":75,"id":"exchange-020"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"当委員会としても現状を把握、調査して、３５人学級の早期実現において何が必要か、提言すべきところは提言すべきなのではないかと思いますので、したがいまして、所管事務調査項目として、少人数学級についてというものを提案したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":123,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5034#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":45897,"voices":124}},{"id":"r03-20210607-5","meetingId":"r03-cm06","date":"2021年6月7日","dateIso":"2021-06-07","committee":"総務委員会","time":"午後 １時００分～午後 ２時１８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"今ご注意がありましたけれども、デジタル化に関することは全く質問しないほうがいいのですか。ちょっと伺いたいなと思ってきたのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"デジタル化、情報推進課の事務事業概要でいろいろ触れられていたのですけれども、今後の展開、それから、どういう分野で、どういう展開を考えておられるのか、ざっとでいいですから、ご説明いただければと思ったのですが、いかがでしょうか。","respondent":"宮澤情報推進課長","answer":"国のほうも、実際、自治体ＤＸ推進計画というものを出していますけれども、その具体的な中身としましては、例えばシステムの標準化対応であったり、または様々ある行政の手続きのオンライン化でありますとか、マイナンバーカードの普及、それ以外には。","voiceIndex":45,"id":"exchange-002"},{"speaker":"おくの委員","kind":"確認","question":"でも、大事なことですから、それを１点確認しておきたいと思います。それがいかがでしょうかというのが第１点です。それからもう１つ、国会などでも議論になりましたので、デジタル化というと、よく問題になるのがプライバシー権だと思います。ですから、やっぱりもう１点確認しておきたいと思います。この２点、いかがでしょうか。お願いいたします。","respondent":"宮澤情報推進課長","answer":"２点目のプライバシー、個人情報の取扱いに関するところです。デジタル化を含めて、これに関わらず、個人情報の取扱いについては、細心の注意を払いながら進めているところです。それは引き続き気をつけながら進めていきたいと考えています。","voiceIndex":47,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"今のお話と関連するのかもしれないですけれども、品川区内の５Ｇ基地局の設置場所の把握は、情報推進課になるのか、それとも、また別の部署になるのか、そこだけ確認させていただきたいのですけれども、いかがでしょうか。","respondent":"宮澤情報推進課長","answer":"いわゆる民間の携帯電話会社等の５Ｇ、携帯電話の基地局に関しましては、情報推進課のほうでは特段把握はしてございません。","voiceIndex":50,"id":"exchange-004"}]},{"id":"topic-02","title":"に戻りまして、幹部職員紹介","agenda":"に戻りまして、幹部職員紹介","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"先月も内閣府の発表で、２０２０年度のＤＶの相談件数の速報値が過去最多となって、２０１９年度の１.６倍に急増したのだと報道され、グラフなどを見ると、本当にもう倍近くに増えていて驚いたのですけれども、まず、品川区でのその辺りの実態、それから、それへの対応はどうなっているのかということを伺いたいと思います。お願いいたします。","respondent":"島袋人権啓発課長","answer":"こちらのほうは、関係機関と、あとは担当、区の職場の皆様との情報共有等々をする会を開催するところです。これによりまして、やはり引き続き区内の状況にも注視しながら対応していきたいと考えているところです。","voiceIndex":89,"id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"ありがとうございました。啓発をやられている担当部署なのですけれども、深刻なＤＶの実態の一端が品川区でも表れているということであると思います。対策はもちろん、啓発のほうも、これからも強化していっていただきたいと思います。これは要望として申し上げておきたいと思います。どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-006"},{"speaker":"田中委員","kind":"意見","question":"なるほど。すみません。ごめんなさい。それで聞きたいのが、今年の１２月末、男女共同参画センターが仮移転するということで、性の多様性の啓発が今年の１２月ということなのですけれども、場所が変わるということで、そこの告知とかは大丈夫なのかというのがちょっと不安だったのですけれども、そこら辺についてお知らせいただけますか。","respondent":"島袋人権啓発課長","answer":"委員からご指摘いただきました講座の件ですが、本来でしたら７月に開催する予定でしたが、やはりコロナ禍の影響ということで、こちらは１２月、昨年度と同様に１２月に変更しているものです。","voiceIndex":93,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"国の対応も、都の対応も、なかなかすんなりいっていなかったので、区に対するしわ寄せはあるかと思うのですが、その辺、もっと区民を安心させるような何か対策、対応というのは、今後、何か、広報もそうですが、いろいろな媒体を通じて、皆さんに説明というか、報告をされたほうがいいと思うのですが、その辺は何かお考えでしょうか。もし答えられたら、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2200#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":25680,"voices":102}}]);
